// 00_hello_dojo / ex1 - reference solution (author only, used by `dojo verify`).

export function describeRuntime(): string {
  return `Node.js ${process.version} on ${process.platform}`;
}

// 00_hello_dojo / ex2 - reference solution (author only, used by `dojo verify`).

export function sumOfArgs(argv: string[]): number {
  return argv.slice(2).reduce((total, arg) => total + Number(arg), 0);
}

// 00_hello_dojo / ex3 - reference solution (author only, used by `dojo verify`).

export async function totalOf(promises: Promise<number>[]): Promise<number> {
  const values = await Promise.all(promises);
  return values.reduce((total, value) => total + value, 0);
}

