// 01_modules / challenge - reference solution (author only, used by `dojo verify`).

export interface ModuleCache<T> {
  get(key: string): Promise<T>;
  size(): number;
}

export function createModuleCache<T>(load: (key: string) => Promise<T>): ModuleCache<T> {
  const entries = new Map<string, Promise<T>>();

  return {
    get(key: string): Promise<T> {
      const cached = entries.get(key);
      if (cached !== undefined) return cached;

      const pending = load(key);
      entries.set(key, pending);
      // A load that failed is not a module: drop it so the next get retries.
      pending.catch(() => {
        if (entries.get(key) === pending) entries.delete(key);
      });
      return pending;
    },
    size(): number {
      return entries.size;
    },
  };
}

// 01_modules / ex1 - reference solution (author only, used by `dojo verify`).
import path from "node:path";
import { fileURLToPath } from "node:url";

export function moduleDirname(metaUrl: string): string {
  return path.dirname(fileURLToPath(metaUrl));
}

// 01_modules / ex2 - reference solution (author only, used by `dojo verify`).
import { createRequire } from "node:module";

const require = createRequire(import.meta.url);
const legacy = require("./legacy-pricing.cjs") as {
  RATES: Record<string, number>;
  priceWithTax: (cents: number, region: string) => number;
};

export function checkout(cents: number, region: string): number {
  return legacy.priceWithTax(cents, region);
}

export function regions(): string[] {
  return Object.keys(legacy.RATES).sort();
}

// 01_modules / ex3 - reference solution (author only, used by `dojo verify`).

let issued = 0;

export function nextId(): string {
  issued += 1;
  return `job-${issued}`;
}

export function idsIssued(): number {
  return issued;
}

// 01_modules / ex4 - reference solution (author only, used by `dojo verify`).
import type { Formatter } from "./formatters/registry";

export type FormatterKind = "json" | "csv";

export async function loadFormatter(kind: FormatterKind): Promise<Formatter> {
  switch (kind) {
    case "json": {
      const module = await import("./formatters/json");
      return module.default;
    }
    case "csv": {
      const module = await import("./formatters/csv");
      return module.default;
    }
    default:
      throw new Error(`unknown formatter: ${kind}`);
  }
}

// 01_modules / review1 - reference solution (author only, used by `dojo verify`).

const seen = new Set<string>();

export function firstTimeSeeing(token: string): boolean {
  if (seen.has(token)) return false;
  seen.add(token);
  return true;
}

export function seenCount(): number {
  return seen.size;
}

