// 10_middleware_validation / challenge - reference solution (author only, used by `dojo verify`).
import express, { type Express, type RequestHandler } from "express";

export interface RateLimiterOptions {
  limit: number;
  windowMs: number;
  now: () => number;
}

interface Bucket {
  count: number;
  start: number;
}

export function createRateLimiter(options: RateLimiterOptions): RequestHandler {
  const buckets = new Map<string, Bucket>();

  return (req, res, next) => {
    const header = req.headers["x-api-key"];
    const key = typeof header === "string" ? header : "anonymous";
    const time = options.now();

    const existing = buckets.get(key);
    const bucket: Bucket =
      existing === undefined || time - existing.start >= options.windowMs
        ? { count: 0, start: time }
        : existing;
    buckets.set(key, bucket);

    if (bucket.count >= options.limit) {
      const msLeft = bucket.start + options.windowMs - time;
      res.setHeader("retry-after", String(Math.ceil(msLeft / 1000)));
      res.status(429).json({ error: "too many requests" });
      return;
    }

    bucket.count += 1;
    res.setHeader("x-ratelimit-limit", String(options.limit));
    res.setHeader("x-ratelimit-remaining", String(options.limit - bucket.count));
    next();
  };
}

export function createApp(options: RateLimiterOptions): Express {
  const app = express();

  app.use(createRateLimiter(options));

  app.get("/ping", (_req, res) => {
    res.json({ pong: true });
  });

  return app;
}

// 10_middleware_validation / ex1 - reference solution (author only, used by `dojo verify`).
import express, { type Express } from "express";

export function createApp(log: (line: string) => void): Express {
  const app = express();

  app.use(express.json());

  app.use((req, res, next) => {
    // "finish" fires once the last byte of the response is handed to the
    // socket - the first moment the status code is final.
    res.on("finish", () => {
      log(`${req.method} ${req.path} ${res.statusCode}`);
    });
    next();
  });

  app.post("/echo", (req, res) => {
    res.json(req.body);
  });

  return app;
}

// 10_middleware_validation / ex2 - reference solution (author only, used by `dojo verify`).
import express, { type Express, type RequestHandler } from "express";
import { z, type ZodSchema } from "zod";

export const createOrderSchema = z.object({
  item: z.string().min(1),
  qty: z.number().int().positive(),
});

export function validateBody<T>(schema: ZodSchema<T>): RequestHandler {
  return (req, res, next) => {
    const result = schema.safeParse(req.body);
    if (!result.success) {
      res.status(400).json({
        error: "validation failed",
        details: result.error.issues.map((issue) => ({
          path: issue.path.join("."),
          message: issue.message,
        })),
      });
      return;
    }

    // The handler downstream sees the parsed value, not the raw input.
    req.body = result.data;
    next();
  };
}

export function createApp(): Express {
  const app = express();
  let nextId = 1;

  app.use(express.json());

  app.post("/orders", validateBody(createOrderSchema), (req, res) => {
    const order = { id: nextId, ...req.body };
    nextId += 1;
    res.status(201).json(order);
  });

  return app;
}

// 10_middleware_validation / ex3 - reference solution (author only, used by `dojo verify`).
import express, {
  type Express,
  type NextFunction,
  type Request,
  type Response,
} from "express";

export class AppError extends Error {
  constructor(
    readonly status: number,
    readonly code: string,
    message: string,
  ) {
    super(message);
    this.name = "AppError";
  }
}

export const ORDERS = [
  { id: "1", item: "keyboard" },
  { id: "2", item: "monitor" },
];

export function createApp(logError: (error: unknown) => void = () => {}): Express {
  const app = express();

  app.get("/orders/:id", (req, res) => {
    const order = ORDERS.find((candidate) => candidate.id === req.params.id);
    if (order === undefined) throw new AppError(404, "not_found", "no such order");
    res.json(order);
  });

  app.get("/boom", () => {
    throw new Error("query failed on postgres://app:hunter2@db:5432/orders");
  });

  // Nothing matched: still an error, so it goes through the same funnel.
  app.use((_req, _res, next: NextFunction) => {
    next(new AppError(404, "not_found", "no such route"));
  });

  // Four parameters is what makes express treat this as an error handler.
  app.use((error: unknown, _req: Request, res: Response, _next: NextFunction) => {
    if (error instanceof AppError) {
      res.status(error.status).json({ error: error.code, message: error.message });
      return;
    }
    logError(error);
    res.status(500).json({ error: "internal_error", message: "internal server error" });
  });

  return app;
}

// 10_middleware_validation / ex4 - reference solution (author only, used by `dojo verify`).
import express, {
  type Express,
  type NextFunction,
  type Request,
  type Response,
} from "express";

export class AppError extends Error {
  constructor(
    readonly status: number,
    readonly code: string,
    message: string,
  ) {
    super(message);
    this.name = "AppError";
  }
}

export async function fetchPrices(): Promise<never> {
  throw new AppError(503, "upstream_unavailable", "the pricing service is down");
}

export function errorHandler(
  error: unknown,
  _req: Request,
  res: Response,
  _next: NextFunction,
): void {
  if (error instanceof AppError) {
    res.status(error.status).json({ error: error.code, message: error.message });
    return;
  }
  res.status(500).json({ error: "internal_error", message: "internal server error" });
}

export function createApp(): Express {
  const app = express();

  app.get("/ok", async (_req, res) => {
    await Promise.resolve();
    res.json({ status: "ok" });
  });

  // No try/catch: in express 5 the rejected promise reaches errorHandler.
  app.get("/slow-dependency", async (_req, res) => {
    const prices = await fetchPrices();
    res.json(prices);
  });

  app.get(
    "/queued",
    (_req, _res, next: NextFunction) => {
      next(new AppError(409, "conflict", "that job is already queued"));
    },
    (_req, res) => {
      res.json({ queued: true });
    },
  );

  app.use(errorHandler);

  return app;
}

