// 11_rest_capstone / ex2 - reference solution (author only, used by `dojo verify`).
import express, { type Express } from "express";

export type TaskStatus = "todo" | "doing" | "done";

export interface Task {
  id: string;
  title: string;
  status: TaskStatus;
}

export const STATUSES: readonly TaskStatus[] = ["todo", "doing", "done"];

export const SEED: Task[] = [
  { id: "seed-1", title: "write the readme", status: "done" },
  { id: "seed-2", title: "ship it", status: "todo" },
  { id: "seed-3", title: "review the pull request", status: "doing" },
];

export function createApp(): Express {
  const app = express();
  const tasks: Task[] = SEED.map((task) => ({ ...task }));

  app.get("/tasks", (req, res) => {
    const status = req.query.status;

    if (status !== undefined) {
      if (typeof status !== "string" || !STATUSES.includes(status as TaskStatus)) {
        res.status(400).json({
          error: "invalid_status",
          message: "status must be one of todo, doing, done",
        });
        return;
      }
    }

    const items = status === undefined
      ? tasks
      : tasks.filter((task) => task.status === status);

    res.json({ items: items.map((task) => ({ ...task })), total: items.length });
  });

  app.get("/tasks/:id", (req, res) => {
    const task = tasks.find((candidate) => candidate.id === req.params.id);
    if (task === undefined) {
      res.status(404).json({ error: "not_found", message: "no such task" });
      return;
    }
    res.json(task);
  });

  app.use((_req, res) => {
    res.status(404).json({ error: "not_found", message: "no such route" });
  });

  return app;
}

// 11_rest_capstone / ex3 - reference solution (author only, used by `dojo verify`).
import express, { type Express } from "express";
import { z, type ZodSchema } from "zod";

export type TaskStatus = "todo" | "doing" | "done";

export interface Task {
  id: string;
  title: string;
  status: TaskStatus;
}

export const statusSchema = z.enum(["todo", "doing", "done"]);

export const createTaskSchema = z.object({
  title: z.string().min(1),
  status: statusSchema.optional(),
});

export const patchTaskSchema = z.object({
  title: z.string().min(1).optional(),
  status: statusSchema.optional(),
});

export const SEED: Task[] = [
  { id: "seed-1", title: "write the readme", status: "done" },
  { id: "seed-2", title: "ship it", status: "todo" },
];

function parseOr400<T>(schema: ZodSchema<T>, body: unknown, res: express.Response): T | null {
  const result = schema.safeParse(body);
  if (result.success) return result.data;

  res.status(400).json({
    error: "validation_failed",
    details: result.error.issues.map((issue) => ({
      path: issue.path.join("."),
      message: issue.message,
    })),
  });
  return null;
}

export function createApp(): Express {
  const app = express();
  const tasks: Task[] = SEED.map((task) => ({ ...task }));
  let nextId = 1;

  app.use(express.json());

  app.post("/tasks", (req, res) => {
    const input = parseOr400(createTaskSchema, req.body, res);
    if (input === null) return;

    const task: Task = {
      id: `task-${nextId}`,
      title: input.title,
      status: input.status ?? "todo",
    };
    nextId += 1;
    tasks.push(task);

    res.setHeader("location", `/tasks/${task.id}`);
    res.status(201).json(task);
  });

  app.patch("/tasks/:id", (req, res) => {
    const patch = parseOr400(patchTaskSchema, req.body, res);
    if (patch === null) return;

    const task = tasks.find((candidate) => candidate.id === req.params.id);
    if (task === undefined) {
      res.status(404).json({ error: "not_found", message: "no such task" });
      return;
    }

    if (patch.title !== undefined) task.title = patch.title;
    if (patch.status !== undefined) task.status = patch.status;
    res.json(task);
  });

  app.delete("/tasks/:id", (req, res) => {
    const index = tasks.findIndex((candidate) => candidate.id === req.params.id);
    if (index === -1) {
      res.status(404).json({ error: "not_found", message: "no such task" });
      return;
    }
    tasks.splice(index, 1);
    res.status(204).end();
  });

  return app;
}

exercises.importantHints:
## Hint 1

This is assembly, not invention: every piece exists in a file you have already
written. What is new is that the routes stop answering errors themselves and
start *throwing* them, and one handler at the bottom turns every throw into a
response.

Build it in this order and run the gate after each step:

1. the request-id middleware, first in the stack;
2. `express.json()`;
3. the four routes from ex2 and ex3;
4. the "no such route" middleware;
5. the error handler, last.

## Hint 2

The shape that makes the routes short: a helper that finds a task or throws.

```ts
function find(tasks: Task[], id: string): Task {
  const task = tasks.find((candidate) => candidate.id === id);
  if (task === undefined) throw new AppError(404, "not_found", "no such task");
  return task;
}
```

Now `GET /tasks/:id` is one line, and the 404 rule lives in exactly one place.

Validation failures need a *different* body from other errors -
`{ error: "validation_failed", details: [...] }` rather than
`{ error, message }` - so either subclass `AppError` with the details attached
(the reference does this) or check for a `ZodError` in the handler. Both are
respectable; pick one and make the handler read cleanly.

## Hint 3

The error handler:

```ts
app.use((error: unknown, _req: Request, res: Response, _next: NextFunction) => {
  if (/* a validation failure? */) { /* 400 + details */ return; }
  if (error instanceof AppError) { /* its status, code and message */ return; }
  res.status(500).json({ error: "internal_error", message: "internal server error" });
});
```

Two decisions left: how you recognise a validation failure, and the order of
the branches (a subclass matches `instanceof AppError` too, so the specific
test has to come first - get this backwards and your details silently
disappear). Check the request-id header on an error response before you call
it done: it is set by the first middleware in the stack, so it should be there
whatever happens afterwards.

