// d02_module_patterns / ex1 - reference solution (author only, used by `dojo verify`).

export function once<T>(factory: () => T): () => T {
  // The flag, not the value, is what records that the factory has run - a
  // factory is allowed to return undefined.
  let done = false;
  let value: T;

  return (): T => {
    if (!done) {
      // Assign only after the factory returns: a throw must leave `done`
      // false so the next caller gets a real second attempt.
      value = factory();
      done = true;
    }
    return value;
  };
}

// d02_module_patterns / ex2 - reference solution (author only, used by `dojo verify`).

export interface Registry<T> {
  register(name: string, value: T): void;
  get(name: string): T;
  has(name: string): boolean;
  names(): string[];
}

export function createRegistry<T>(): Registry<T> {
  // A Map, not a plain object: no prototype keys to collide with, and a real
  // has() that does not confuse "registered as undefined" with "absent".
  const entries = new Map<string, T>();

  return {
    register(name: string, value: T): void {
      if (entries.has(name)) {
        throw new Error(`duplicate registration: ${name}`);
      }
      entries.set(name, value);
    },
    get(name: string): T {
      if (!entries.has(name)) {
        throw new Error(`nothing registered under: ${name}`);
      }
      return entries.get(name) as T;
    },
    has(name: string): boolean {
      return entries.has(name);
    },
    names(): string[] {
      return [...entries.keys()].sort();
    },
  };
}

// d02_module_patterns / ex3 - reference solution (author only, used by `dojo verify`).

export interface Limits {
  maxBodyBytes: number;
  timeoutMs: number;
}

export interface Config {
  port: number;
  host: string;
  limits: Limits;
  tags: string[];
}

export interface ConfigOverrides {
  port?: number;
  host?: string;
  limits?: Partial<Limits>;
  tags?: string[];
}

// A *function*, not a constant. A shared constant would hand every caller the
// same nested objects, and the first freeze would freeze them for everybody.
function defaults(): Config {
  return {
    port: 3_000,
    host: "0.0.0.0",
    limits: { maxBodyBytes: 1_000_000, timeoutMs: 5_000 },
    tags: [],
  };
}

export function defineConfig(overrides: ConfigOverrides): Config {
  const base = defaults();
  const config: Config = {
    ...base,
    ...overrides,
    limits: { ...base.limits, ...overrides.limits },
    tags: [...(overrides.tags ?? base.tags)],
  };

  Object.freeze(config.limits);
  Object.freeze(config.tags);
  return Object.freeze(config);
}

// d02_module_patterns / ex4 - reference solution (author only, used by `dojo verify`).

export function createNamespace(
  factories: Record<string, () => unknown>,
): Record<string, unknown> {
  const namespace: Record<string, unknown> = {};

  for (const [name, factory] of Object.entries(factories)) {
    let built = false;
    let value: unknown;

    Object.defineProperty(namespace, name, {
      // enumerable so Object.keys() can describe the namespace without
      // evaluating any of it.
      enumerable: true,
      configurable: true,
      get(): unknown {
        if (!built) {
          value = factory();
          built = true;
        }
        return value;
      },
    });
  }

  return namespace;
}

// d02_module_patterns / ex5 - reference solution (author only, used by `dojo verify`).

export interface Entry {
  id: string;
  event: string;
  at: number;
}

export interface Store {
  save(entry: Entry): void;
  all(): Entry[];
}

export interface Deps {
  now: () => number;
  ids: () => string;
  store: Store;
}

export interface Service {
  record(event: string): Entry;
  history(): Entry[];
}

function createMemoryStore(): Store {
  const entries: Entry[] = [];
  return {
    save(entry: Entry): void {
      entries.push(entry);
    },
    all(): Entry[] {
      return [...entries];
    },
  };
}

// Built per call. A module-level `const defaultDeps` would mean every service
// in the process shared one store - and one counter.
function createDefaultDeps(): Deps {
  let next = 0;
  return {
    now: () => Date.now(),
    ids: () => `e-${(next += 1)}`,
    store: createMemoryStore(),
  };
}

export function createService(overrides: Partial<Deps> = {}): Service {
  const deps: Deps = { ...createDefaultDeps(), ...overrides };

  return {
    record(event: string): Entry {
      const entry: Entry = { id: deps.ids(), event, at: deps.now() };
      deps.store.save(entry);
      return entry;
    },
    history(): Entry[] {
      return deps.store.all();
    },
  };
}

// d02_module_patterns / ex6 - reference solution (author only, used by `dojo verify`).

export interface PluginApi {
  addCommand(name: string, run: () => string): void;
}

export interface Plugin {
  name: string;
  setup(api: PluginApi): (() => void) | void;
}

export interface PluginHost {
  use(plugin: Plugin): PluginHost;
  start(): void;
  run(command: string): string;
  stop(): void;
  started(): boolean;
}

export function createPluginHost(): PluginHost {
  const plugins: Plugin[] = [];
  const commands = new Map<string, () => string>();
  const teardowns: (() => void)[] = [];
  let running = false;

  const host: PluginHost = {
    use(plugin: Plugin): PluginHost {
      if (running) throw new Error("cannot add plugins after start");
      plugins.push(plugin);
      return host;
    },

    start(): void {
      if (running) throw new Error("already started");
      running = true;
      const api: PluginApi = {
        addCommand(name: string, run: () => string): void {
          commands.set(name, run);
        },
      };
      for (const plugin of plugins) {
        const teardown = plugin.setup(api);
        if (typeof teardown === "function") teardowns.push(teardown);
      }
    },

    run(command: string): string {
      if (!running) throw new Error("not started");
      const handler = commands.get(command);
      if (!handler) throw new Error(`unknown command: ${command}`);
      return handler();
    },

    stop(): void {
      if (!running) throw new Error("not started");
      // Reverse: a later plugin may have been built on an earlier one, so the
      // earlier one has to still be alive while the later one shuts down.
      for (let i = teardowns.length - 1; i >= 0; i -= 1) teardowns[i]();
      teardowns.length = 0;
      commands.clear();
      running = false;
    },

    started(): boolean {
      return running;
    },
  };

  return host;
}

// d02_module_patterns / ex7 - reference solution (author only, used by `dojo verify`).

export interface Container {
  register(name: string, factory: (container: Container) => unknown): void;
  resolve<T>(name: string): T;
}

export function createContainer(): Container {
  const factories = new Map<string, (container: Container) => unknown>();
  const instances = new Map<string, unknown>();
  //: the names currently being built, outermost first
  const building: string[] = [];

  const container: Container = {
    register(name, factory): void {
      factories.set(name, factory);
    },

    resolve<T>(name: string): T {
      if (instances.has(name)) return instances.get(name) as T;

      const factory = factories.get(name);
      if (!factory) throw new Error(`nothing registered under: ${name}`);

      if (building.includes(name)) {
        const path = [...building.slice(building.indexOf(name)), name];
        throw new Error(`circular dependency: ${path.join(" -> ")}`);
      }

      building.push(name);
      try {
        const value = factory(container);
        instances.set(name, value);
        return value as T;
      } finally {
        // The finally is the point: without it a detected cycle leaves the
        // stack dirty and every later resolve reports a phantom loop.
        building.pop();
      }
    },
  };

  return container;
}

// d02_module_patterns / ex8 - reference solution (author only, used by `dojo verify`).

export interface Orderable {
  name: string;
  after?: string[];
}

export function orderPlugins(plugins: Orderable[]): string[] {
  const pending = new Map<string, Set<string>>();
  const known = new Set(plugins.map((plugin) => plugin.name));

  for (const plugin of plugins) {
    for (const dependency of plugin.after ?? []) {
      if (!known.has(dependency)) {
        throw new Error(`unknown dependency: ${plugin.name} needs ${dependency}`);
      }
    }
    pending.set(plugin.name, new Set(plugin.after ?? []));
  }

  const ordered: string[] = [];
  while (pending.size > 0) {
    // Sorting the ready set is what makes the result a property of the graph
    // rather than of the input array.
    const ready = [...pending.entries()]
      .filter(([, blockers]) => blockers.size === 0)
      .map(([name]) => name)
      .sort();

    if (ready.length === 0) {
      const stuck = [...pending.keys()].sort().join(", ");
      throw new Error(`circular dependency among: ${stuck}`);
    }

    const next = ready[0];
    ordered.push(next);
    pending.delete(next);
    for (const blockers of pending.values()) blockers.delete(next);
  }

  return ordered;
}

