// d03_event_loop_order / ex1 - reference solution (author only, used by `dojo verify`).
//
// A and E are synchronous, so they run before anything is scheduled at all.
// Then the checkpoint: the nextTick queue first (C), then the microtask queue
// (D). The timer (B) belongs to a later phase of the loop entirely.

export function predictOrder(): string[] {
  return ["A", "E", "C", "D", "B"];
}

// d03_event_loop_order / ex2 - reference solution (author only, used by `dojo verify`).
//
// "sync" first. Then the checkpoint drains the whole nextTick queue: tick-1
// (which pushes a microtask onto a queue that has not started yet) and tick-2.
// Only then are microtasks run, in the order they were queued: micro-1 (queued
// during the synchronous code) before micro-from-tick. micro-1 pushes onto the
// nextTick queue, which is already empty - so the checkpoint goes round again
// and picks it up.

export function predictOrder(): string[] {
  return ["sync", "tick-1", "tick-2", "micro-1", "micro-from-tick", "tick-from-micro"];
}

// d03_event_loop_order / ex3 - reference solution (author only, used by `dojo verify`).
//
// Synchronously: outer() runs to its await, which first calls inner(), which
// runs to ITS await - so "outer-start", "inner-start". Then the .then chain is
// registered (nothing logged) and "sync-end" runs.
//
// Microtask 1: inner resumes -> "inner-end", and inner's promise fulfils.
// Microtask 2: the first .then handler -> "then-1".
//   (outer is awaiting a *promise*, and adopting one costs an extra hop, so
//   outer has not resumed yet. This is the whole point of the problem.)
// Microtask 3: outer resumes -> "outer-end".
// Microtask 4: the second .then handler -> "then-2".

export function predictOrder(): string[] {
  return [
    "outer-start",
    "inner-start",
    "sync-end",
    "inner-end",
    "then-1",
    "outer-end",
    "then-2",
  ];
}

// d03_event_loop_order / ex4 - reference solution (author only, used by `dojo verify`).

export function scheduleLabels(log: (label: string) => void): void {
  log("sync");
  process.nextTick(() => log("tick"));
  queueMicrotask(() => log("micro"));
  setImmediate(() => log("check"));
  setTimeout(() => log("timer"), 0);
}

// d03_event_loop_order / ex5 - reference solution (author only, used by `dojo verify`).

/** One driver, parameterised by how the next step is scheduled. */
function drainWith<T>(
  items: readonly T[],
  handle: (item: T) => void,
  schedule: (step: () => void) => void,
): Promise<void> {
  return new Promise<void>((resolve) => {
    let index = 0;
    const step = (): void => {
      if (index >= items.length) {
        resolve();
        return;
      }
      handle(items[index]);
      index += 1;
      schedule(step);
    };
    // The first item runs synchronously; only the *gaps* are scheduled.
    step();
  });
}

export function drainQueue<T>(items: readonly T[], handle: (item: T) => void): Promise<void> {
  // process.nextTick re-enters the checkpoint without ever reaching a loop
  // phase, so nothing else runs until the queue empties.
  return drainWith(items, handle, (step) => process.nextTick(step));
}

export function drainQueueFairly<T>(
  items: readonly T[],
  handle: (item: T) => void,
): Promise<void> {
  // setImmediate parks the work in the check phase, so the loop completes a
  // turn - timers, I/O, everything - between items.
  return drainWith(items, handle, (step) => setImmediate(step));
}

// d03_event_loop_order / ex6 - reference solution (author only, used by `dojo verify`).
//
// "sync" runs first, as always. Then the nextTick queue is drained to
// exhaustion - and each callback pushes another one onto it while it is being
// drained, so all three run back to back with nothing in between. Only when the
// queue finally empties does the microtask run, and only after the whole
// checkpoint does the loop reach the timers phase.

export function predictOrder(): string[] {
  return ["sync", "tick-1", "tick-2", "tick-3", "micro", "timer"];
}

// d03_event_loop_order / ex7 - reference solution (author only, used by `dojo verify`).
//
// Synchronously: registering the chain logs nothing, queueMicrotask logs
// nothing, job() runs to its first await and logs "a-start", then "sync".
//
// The microtask queue starts as [p1, q1, q2, job-resume-1]:
//   p1  -> "p1", and only now is the p2 handler queued (position 5)
//   q1  -> "q1"
//   q2  -> "q2"
//   job -> "a-1", and the second await queues job-resume-2 (position 7)
//   p2  -> "p2", queueing p3 (position 8)
//   job -> "a-2"
//   p3  -> "p3"

export function predictOrder(): string[] {
  return ["a-start", "sync", "p1", "q1", "q2", "a-1", "p2", "a-2", "p3"];
}

// d03_event_loop_order / ex8 - reference solution (author only, used by `dojo verify`).

export interface YieldingResult<R> {
  results: R[];
  yields: number;
}

/** A real turn of the loop, not a microtask. */
function yieldToLoop(): Promise<void> {
  return new Promise<void>((resolve) => setImmediate(resolve));
}

export async function yieldingMap<T, R>(
  items: readonly T[],
  size: number,
  fn: (item: T, index: number) => R,
): Promise<YieldingResult<R>> {
  const results: R[] = [];
  let yields = 0;

  for (let start = 0; start < items.length; start += size) {
    // Yield *before* every chunk except the first: that puts the gaps between
    // chunks rather than after the last one.
    if (start > 0) {
      await yieldToLoop();
      yields += 1;
    }
    const end = Math.min(start + size, items.length);
    for (let i = start; i < end; i += 1) {
      results.push(fn(items[i], i));
    }
  }

  return { results, yields };
}

