// d04_timers_micro / ex1 - reference solution (author only, used by `dojo verify`).

export function delay(ms: number): Promise<void> {
  return new Promise<void>((resolve) => {
    setTimeout(resolve, ms);
  });
}

export function immediate(): Promise<void> {
  // Promise.resolve() is already a settled promise; awaiting it costs one
  // microtask and nothing else. No timer means nothing to clear and nothing
  // keeping the process alive.
  return Promise.resolve();
}

// d04_timers_micro / ex2 - reference solution (author only, used by `dojo verify`).

export interface TickerOptions {
  intervalMs: number;
  onTick: (n: number) => void;
}

export interface Ticker {
  start(): void;
  stop(): void;
  ticks(): number;
  running(): boolean;
}

export function createTicker(options: TickerOptions): Ticker {
  // The handle IS the running flag: an interval you are holding is one you can
  // clear, and one you are not holding is one you have leaked.
  let handle: ReturnType<typeof setInterval> | undefined;
  let count = 0;

  return {
    start(): void {
      if (handle !== undefined) return;
      handle = setInterval(() => {
        count += 1;
        options.onTick(count);
      }, options.intervalMs);
    },
    stop(): void {
      if (handle === undefined) return;
      clearInterval(handle);
      handle = undefined;
    },
    ticks(): number {
      return count;
    },
    running(): boolean {
      return handle !== undefined;
    },
  };
}

// d04_timers_micro / ex3 - reference solution (author only, used by `dojo verify`).

export interface Debounced<A extends unknown[]> {
  (...args: A): void;
  cancel(): void;
  pending(): boolean;
}

export function debounce<A extends unknown[]>(
  fn: (...args: A) => void,
  waitMs: number,
): Debounced<A> {
  let handle: ReturnType<typeof setTimeout> | undefined;
  let lastArgs: A | undefined;

  const debounced = ((...args: A): void => {
    lastArgs = args;
    // Clearing first is what makes the wait restart instead of stacking up.
    if (handle !== undefined) clearTimeout(handle);
    handle = setTimeout(() => {
      handle = undefined;
      const args_ = lastArgs as A;
      lastArgs = undefined;
      fn(...args_);
    }, waitMs);
  }) as Debounced<A>;

  debounced.cancel = (): void => {
    if (handle !== undefined) clearTimeout(handle);
    handle = undefined;
    lastArgs = undefined;
  };

  debounced.pending = (): boolean => handle !== undefined;

  return debounced;
}

// d04_timers_micro / ex4 - reference solution (author only, used by `dojo verify`).

export function throttle<A extends unknown[]>(
  fn: (...args: A) => void,
  waitMs: number,
): (...args: A) => void {
  let handle: ReturnType<typeof setTimeout> | undefined;
  let suppressed: A | undefined;

  // "Is a window open" and "is a timer armed" are the same question, so one
  // variable answers both.
  const openWindow = (): void => {
    handle = setTimeout(() => {
      handle = undefined;
      if (suppressed === undefined) return; // nothing waited: let the window close
      const args = suppressed;
      suppressed = undefined;
      fn(...args);
      openWindow(); // the trailing call is a call, so it opens its own window
    }, waitMs);
  };

  return (...args: A): void => {
    if (handle === undefined) {
      fn(...args);
      openWindow();
      return;
    }
    suppressed = args;
  };
}

// d04_timers_micro / ex5 - reference solution (author only, used by `dojo verify`).

export interface PollOptions {
  intervalMs: number;
  timeoutMs: number;
}

export function pollUntil(check: () => boolean, options: PollOptions): Promise<number> {
  return new Promise<number>((resolve, reject) => {
    let attempts = 0;
    let poll: ReturnType<typeof setTimeout> | undefined;

    const deadline = setTimeout(() => {
      cleanup();
      reject(new Error(`timed out after ${options.timeoutMs}ms`));
    }, options.timeoutMs);

    function cleanup(): void {
      if (poll !== undefined) clearTimeout(poll);
      poll = undefined;
      clearTimeout(deadline);
    }

    const attempt = (): void => {
      attempts += 1;
      if (check()) {
        cleanup();
        resolve(attempts);
        return;
      }
      poll = setTimeout(attempt, options.intervalMs);
    };

    // The first check is free: something already true must not wait an interval.
    attempt();
  });
}

// d04_timers_micro / ex6 - reference solution (author only, used by `dojo verify`).

export interface Scheduler {
  at(time: number, run: () => void): void;
  advanceTo(time: number): number;
  now(): number;
  pending(): number;
}

interface Entry {
  time: number;
  /** insertion order, so entries due at the same instant keep their order */
  seq: number;
  run: () => void;
}

export function createScheduler(): Scheduler {
  const entries: Entry[] = [];
  let seq = 0;
  let current = 0;

  return {
    at(time: number, run: () => void): void {
      seq += 1;
      entries.push({ time, seq, run });
    },

    advanceTo(time: number): number {
      if (time < current) throw new Error("time cannot go backwards");
      current = time;

      let ran = 0;
      // Re-scan every pass: a callback may have added something that is also
      // due, and it has to run in this same advance.
      for (;;) {
        let next: Entry | undefined;
        for (const entry of entries) {
          if (entry.time > current) continue;
          if (
            next === undefined ||
            entry.time < next.time ||
            (entry.time === next.time && entry.seq < next.seq)
          ) {
            next = entry;
          }
        }
        if (next === undefined) return ran;
        entries.splice(entries.indexOf(next), 1);
        ran += 1;
        next.run();
      }
    },

    now(): number {
      return current;
    },

    pending(): number {
      return entries.length;
    },
  };
}

// d04_timers_micro / ex7 - reference solution (author only, used by `dojo verify`).

export interface SelfCorrectingOptions {
  intervalMs: number;
  now: () => number;
  onTick: (n: number) => void;
}

export interface SelfCorrecting {
  start(): void;
  stop(): void;
}

export function createSelfCorrectingInterval(
  options: SelfCorrectingOptions,
): SelfCorrecting {
  let handle: ReturnType<typeof setTimeout> | undefined;
  let startedAt = 0;
  let count = 0;

  // setTimeout, not setInterval: the delay has to be recomputed every time.
  const arm = (): void => {
    const due = startedAt + (count + 1) * options.intervalMs;
    const wait = Math.max(0, due - options.now());
    handle = setTimeout(() => {
      handle = undefined;
      count += 1;
      options.onTick(count);
      arm();
    }, wait);
  };

  return {
    start(): void {
      if (handle !== undefined) return;
      startedAt = options.now();
      count = 0;
      arm();
    },
    stop(): void {
      if (handle !== undefined) clearTimeout(handle);
      handle = undefined;
    },
  };
}

// d04_timers_micro / ex8 - reference solution (author only, used by `dojo verify`).

export interface DelayQueue {
  enqueue(delayMs: number, run: () => void): () => void;
  size(): number;
}

interface Entry {
  at: number;
  seq: number;
  run: () => void;
}

export function createDelayQueue(now: () => number): DelayQueue {
  const entries: Entry[] = [];
  let seq = 0;
  let handle: ReturnType<typeof setTimeout> | undefined;

  const earlier = (a: Entry, b: Entry): boolean =>
    a.at < b.at || (a.at === b.at && a.seq < b.seq);

  const remove = (entry: Entry): boolean => {
    const index = entries.indexOf(entry);
    if (index === -1) return false;
    entries.splice(index, 1);
    return true;
  };

  const rearm = (): void => {
    if (handle !== undefined) {
      clearTimeout(handle);
      handle = undefined;
    }
    if (entries.length === 0) return;
    const next = entries.reduce((best, entry) => (earlier(entry, best) ? entry : best));
    handle = setTimeout(fire, Math.max(0, next.at - now()));
  };

  function fire(): void {
    handle = undefined;
    const current = now();
    const due = entries
      .filter((entry) => entry.at <= current)
      .sort((a, b) => a.at - b.at || a.seq - b.seq);
    // Remove them all before running any, so a callback that enqueues more
    // work cannot disturb this pass.
    for (const entry of due) remove(entry);
    for (const entry of due) entry.run();
    rearm();
  }

  return {
    enqueue(delayMs: number, run: () => void): () => void {
      seq += 1;
      const entry: Entry = { at: now() + delayMs, seq, run };
      entries.push(entry);
      rearm();
      return () => {
        if (remove(entry)) rearm();
      };
    },
    size(): number {
      return entries.length;
    },
  };
}

