// d05_promise_basics / ex1 - reference solution (author only, used by `dojo verify`).

export interface Deferred<T> {
  promise: Promise<T>;
  resolve(value: T): void;
  reject(reason: unknown): void;
  settled(): boolean;
}

export function deferred<T>(): Deferred<T> {
  // The executor runs synchronously, which is the only reason capturing the
  // two functions out of it works at all.
  let settleValue!: (value: T) => void;
  let settleReason!: (reason: unknown) => void;
  const promise = new Promise<T>((resolve, reject) => {
    settleValue = resolve;
    settleReason = reject;
  });

  let done = false;

  return {
    promise,
    resolve(value: T): void {
      if (done) return;
      done = true;
      settleValue(value);
    },
    reject(reason: unknown): void {
      if (done) return;
      done = true;
      settleReason(reason);
    },
    settled(): boolean {
      return done;
    },
  };
}

// d05_promise_basics / ex2 - reference solution (author only, used by `dojo verify`).

export function mapPromise<T, R>(
  promise: Promise<T>,
  fn: (value: T) => R | Promise<R>,
): Promise<R> {
  // Every requirement in the doc comment is something .then already does:
  // it returns a NEW promise, it catches a throw in the handler and turns it
  // into a rejection, it adopts a returned promise, and it leaves a rejected
  // input alone when there is no rejection handler.
  return promise.then(fn);
}

// d05_promise_basics / ex3 - reference solution (author only, used by `dojo verify`).

export function orElse<T>(
  promise: Promise<T>,
  fallback: (reason: unknown) => T | Promise<T>,
): Promise<T> {
  // .catch(fn) is .then(undefined, fn): a rejection handler that RETURNS turns
  // the rejection into a fulfilment, and one that throws produces a new
  // rejection. Both requirements are already in the method.
  return promise.catch(fallback);
}

// d05_promise_basics / ex4 - reference solution (author only, used by `dojo verify`).

export type SettleState = "fulfilled" | "rejected";

export function tap<T>(
  promise: Promise<T>,
  onSettle: (state: SettleState, valueOrReason: unknown) => void,
): Promise<T> {
  return promise.then(
    (value) => {
      // No try/catch: a throw here should reject the result, which is exactly
      // what an uncaught throw in a .then handler already does.
      onSettle("fulfilled", value);
      return value;
    },
    (reason: unknown) => {
      onSettle("rejected", reason);
      // Rethrow, or the rejection quietly becomes a fulfilment of undefined.
      throw reason;
    },
  );
}

// d05_promise_basics / ex5 - reference solution (author only, used by `dojo verify`).

export type Snapshot<T> =
  | { state: "pending" }
  | { state: "fulfilled"; value: T }
  | { state: "rejected"; reason: unknown };

export function inspect<T>(promise: Promise<T>): Promise<Snapshot<T>> {
  // Attaching first matters: on an already settled promise these handlers are
  // queued as microtasks before the marker below, so they win the race.
  const settled: Promise<Snapshot<T>> = promise.then(
    (value) => ({ state: "fulfilled", value }) as Snapshot<T>,
    (reason: unknown) => ({ state: "rejected", reason }) as Snapshot<T>,
  );

  const marker: Promise<Snapshot<T>> = Promise.resolve().then(
    () => ({ state: "pending" }) as Snapshot<T>,
  );

  return Promise.race([settled, marker]);
}

// d05_promise_basics / ex6 - reference solution (author only, used by `dojo verify`).

export function chainSequential<T, R>(
  items: readonly T[],
  step: (item: T, index: number) => Promise<R>,
): Promise<R[]> {
  const results: R[] = [];

  // reduce builds the chain without ever holding two steps in flight: each
  // link's .then is what CALLS the next step, so nothing starts early.
  return items
    .reduce<Promise<void>>(
      (chain, item, index) =>
        chain.then(() =>
          step(item, index).then(
            (value) => {
              results.push(value);
            },
            (error: unknown) => {
              throw new Error(`step ${index} failed`, { cause: error });
            },
          ),
        ),
      Promise.resolve(),
    )
    .then(() => results);
}

// d05_promise_basics / ex7 - reference solution (author only, used by `dojo verify`).

export interface Thenable<T> {
  then(onFulfilled: (value: T) => void, onRejected: (reason: unknown) => void): void;
}

export function adoptThenable<T>(value: T | Thenable<T>): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    if (value === null || (typeof value !== "object" && typeof value !== "function")) {
      resolve(value as T);
      return;
    }

    let settled = false;
    try {
      // ONE read. `.then` may be a getter, and a getter is allowed to return a
      // different function every time it is asked - or to throw.
      const then = (value as Thenable<T>).then;
      if (typeof then !== "function") {
        resolve(value as T);
        return;
      }
      then.call(
        value,
        (result: T) => {
          if (settled) return;
          settled = true;
          resolve(result);
        },
        (reason: unknown) => {
          if (settled) return;
          settled = true;
          reject(reason);
        },
      );
    } catch (error) {
      // A throw after the thenable already settled is not our business.
      if (!settled) reject(error);
    }
  });
}

// d05_promise_basics / ex8 - reference solution (author only, used by `dojo verify`).

export interface MinimalThenable<T> {
  then(
    onFulfilled?: ((value: T) => void) | null,
    onRejected?: ((reason: unknown) => void) | null,
  ): void;
}

export interface Settleable<T> {
  thenable: MinimalThenable<T>;
  resolve(value: T): void;
  reject(reason: unknown): void;
}

type State = "pending" | "fulfilled" | "rejected";

interface Handlers<T> {
  onFulfilled?: ((value: T) => void) | null;
  onRejected?: ((reason: unknown) => void) | null;
}

export function createSettleable<T>(): Settleable<T> {
  let state: State = "pending";
  let value: T;
  let reason: unknown;
  const waiting: Handlers<T>[] = [];

  /** One handler pair, delivered on the microtask queue - never inline. */
  const deliver = (handlers: Handlers<T>): void => {
    queueMicrotask(() => {
      if (state === "fulfilled") handlers.onFulfilled?.(value);
      else handlers.onRejected?.(reason);
    });
  };

  const settle = (next: State, payload: unknown): void => {
    if (state !== "pending") return;
    state = next;
    if (next === "fulfilled") value = payload as T;
    else reason = payload;
    // Registration order is preserved because the queue is drained in order
    // and each entry is scheduled in order.
    while (waiting.length > 0) deliver(waiting.shift() as Handlers<T>);
  };

  return {
    thenable: {
      then(onFulfilled, onRejected): void {
        const handlers: Handlers<T> = { onFulfilled, onRejected };
        if (state === "pending") waiting.push(handlers);
        else deliver(handlers);
      },
    },
    resolve(next: T): void {
      settle("fulfilled", next);
    },
    reject(next: unknown): void {
      settle("rejected", next);
    },
  };
}

