// d06_async_await / ex1 - reference solution (author only, used by `dojo verify`).

export interface User {
  id: string;
  name: string;
  teamId: string;
}

export interface Team {
  id: string;
  name: string;
}

export interface ProfileDeps {
  findUser(id: string): Promise<User>;
  findTeam(teamId: string): Promise<Team>;
}

export interface Profile {
  id: string;
  name: string;
  team: string;
}

export async function loadProfile(id: string, deps: ProfileDeps): Promise<Profile> {
  // The second call needs a value only the first can produce, so the await is
  // load bearing rather than lazy - and it is why a rejection from findUser
  // means findTeam is never reached.
  const user = await deps.findUser(id);
  const team = await deps.findTeam(user.teamId);
  return { id: user.id, name: user.name, team: team.name };
}

// d06_async_await / ex2 - reference solution (author only, used by `dojo verify`).

export async function startBoth<A, B>(
  first: () => Promise<A>,
  second: () => Promise<B>,
): Promise<[A, B]> {
  // Calling is starting. Both calls happen before the first await, so the two
  // waits overlap.
  const a = first();
  const b = second();
  // Promise.all rather than `[await a, await b]`: it attaches handlers to both
  // immediately, so a rejection from the second one while we are waiting on
  // the first is never an unhandled rejection.
  return Promise.all([a, b]);
}

// d06_async_await / ex3 - reference solution (author only, used by `dojo verify`).

export type Attempt<T> = [error: null, value: T] | [error: Error, value: null];

export async function attempt<T>(fn: () => Promise<T> | T): Promise<Attempt<T>> {
  try {
    // The CALL is inside the try, not just the await. A function that throws
    // while validating its arguments never gets as far as returning a promise.
    const value = await fn();
    return [null, value];
  } catch (error) {
    return [error instanceof Error ? error : new Error(String(error)), null];
  }
}

// d06_async_await / ex4 - reference solution (author only, used by `dojo verify`).

export async function withCleanup<T>(
  run: () => Promise<T>,
  cleanup: () => Promise<void> | void,
): Promise<T> {
  let result: T;

  try {
    result = await run();
  } catch (error) {
    // On the failure path the cleanup is best effort: whatever it does, the
    // caller must still be told what actually broke.
    try {
      await cleanup();
    } catch {
      // deliberately swallowed - see the original throw below
    }
    throw error;
  }

  // On the success path there is no error to protect, so a failing cleanup is
  // the most important thing that happened.
  await cleanup();
  return result;
}

// d06_async_await / ex5 - reference solution (author only, used by `dojo verify`).

export async function sumUntil(
  source: AsyncIterable<number>,
  stopAt: number,
): Promise<number> {
  let total = 0;

  // `break` out of a for-await calls the iterator's return() for you. A
  // hand-rolled `while (true) { const { value, done } = await it.next(); }`
  // does not, and that is how a database cursor stays open.
  for await (const value of source) {
    if (value === stopAt) break;
    total += value;
  }

  return total;
}

// d06_async_await / ex6 - reference solution (author only, used by `dojo verify`).

export async function mapValuesAsync<T, R>(
  record: Record<string, T>,
  fn: (value: T, key: string) => Promise<R>,
): Promise<Record<string, R>> {
  const keys = Object.keys(record);

  // map() calls every fn before Promise.all ever waits, so all of them are in
  // flight together; the array keeps them lined up with `keys` by position.
  const values = await Promise.all(keys.map((key) => fn(record[key], key)));

  return Object.fromEntries(keys.map((key, index) => [key, values[index]]));
}

// d06_async_await / ex7 - reference solution (author only, used by `dojo verify`).

export async function* chunked<T>(
  source: AsyncIterable<T>,
  size: number,
): AsyncGenerator<T[], void, undefined> {
  let chunk: T[] = [];

  for await (const item of source) {
    chunk.push(item);
    if (chunk.length === size) {
      yield chunk;
      // A fresh array, not chunk.length = 0: the consumer is holding the one
      // just yielded and would watch it empty itself.
      chunk = [];
    }
  }

  // Whatever is left over, unless there is nothing - an empty trailing chunk
  // is not a chunk.
  if (chunk.length > 0) yield chunk;
}

// d06_async_await / ex8 - reference solution (author only, used by `dojo verify`).

export interface Stage {
  name: string;
  run(): Promise<void>;
  rollback?(): Promise<void>;
}

export async function runStages(stages: readonly Stage[]): Promise<string[]> {
  const completed: Stage[] = [];

  for (const stage of stages) {
    try {
      await stage.run();
    } catch (error) {
      const rollbackErrors: Error[] = [];
      // Reverse, and only the ones that finished: the stage that threw did not
      // complete, so there is nothing of it to undo.
      for (let i = completed.length - 1; i >= 0; i -= 1) {
        const done = completed[i];
        if (typeof done.rollback !== "function") continue;
        try {
          await done.rollback();
        } catch (rollbackError) {
          rollbackErrors.push(
            rollbackError instanceof Error
              ? rollbackError
              : new Error(String(rollbackError)),
          );
        }
      }
      if (error instanceof Error && rollbackErrors.length > 0) {
        (error as Error & { rollbackErrors?: Error[] }).rollbackErrors = rollbackErrors;
      }
      throw error;
    }
    // Push AFTER the await returns, so "completed" means completed.
    completed.push(stage);
  }

  return completed.map((stage) => stage.name);
}

