# d07 — Concurrency control

Eight problems on the one question every async service eventually asks: **how
many at once?** Lesson **03_async_patterns** taught the limiter; this set drills
the family it belongs to — permits, de-duplication, queues, batches, keyed
locks, pools and cancellation. If problem 5 feels unfamiliar rather than
mechanical, go back to lesson 03 ex3 first.

Nothing here is graded by timing. The gate holds each unit of work open and
releases it by hand, so every claim about concurrency is an exact count.

## Problem 1 — the primitive underneath

Edit `ex1/solution.ts`. `createSemaphore(limit)` returns `{ acquire, available,
waiting }`. `acquire()` resolves with a **release function** once a permit is
free; waiters are served FIFO; each release function is idempotent, so calling
it twice returns one permit rather than two.

```
uv run dojo test node d07_concurrency_control ex1
```

## Problem 2 — de-duplicate, do not cache

Edit `ex2/solution.ts`. `singleFlight(fn)` returns a wrapper: while a call is in
flight, further calls join it and share its outcome. Once it settles — either
way — the next call starts a **new** one. Nothing is remembered between flights,
including failures.

```
uv run dojo test node d07_concurrency_control ex2
```

## Problem 3 — a queue you keep pushing into

Edit `ex3/solution.ts`. `createTaskQueue({ concurrency })` returns `{ push,
size, active, onIdle }`. `push(task)` returns a promise for **that task's**
outcome, and a failing task rejects only its own promise while the queue carries
on. `onIdle()` resolves when nothing is queued and nothing is running.

```
uv run dojo test node d07_concurrency_control ex3
```

## Problem 4 — batches, which are not limits

Edit `ex4/solution.ts`. `batched(items, size, worker)` processes in groups:
everything in a group starts together, and group *n+1* does not start until
every member of group *n* has settled. Results are flat and in input order; one
failure fails the call and no later group starts.

```
uv run dojo test node d07_concurrency_control ex4
```

## Problem 5 — a limiter that reports instead of failing

Edit `ex5/solution.ts`. `mapSettledLimit(items, limit, worker)` keeps at most
`limit` workers in flight, freeing a slot the moment one settles either way. It
returns one `{ status, value }` / `{ status, reason }` record per input, in
input order, and never rejects.

```
uv run dojo test node d07_concurrency_control ex5
```

## Problem 6 — lock the row, not the table

Edit `ex6/solution.ts`. `createKeyedLock()` returns `{ withLock, held }`. Calls
on the same key run one at a time in call order; calls on different keys do not
wait for each other. The lock is released whatever `fn` does, and `fn`'s outcome
reaches its caller unchanged.

```
uv run dojo test node d07_concurrency_control ex6
```

## Problem 7 — a resource pool

Edit `ex7/solution.ts`. `createPool({ create, max })` returns `{ acquire,
release, size, waiting }`. Resources are created lazily and never more than
`max` of them; a release goes straight to the longest waiter; releasing the same
resource twice must not put two copies in the free list.

```
uv run dojo test node d07_concurrency_control ex7
```

## Problem 8 — a limiter you can call off

Edit `ex8/solution.ts`. `mapLimitAbortable(items, limit, worker, signal)` is an
ordinary limiter until the signal aborts. Then: nothing further is started, the
call rejects with `signal.reason` immediately rather than waiting for the work
in flight, and an already-aborted signal starts nothing at all. The worker is
handed the signal as its third argument.

```
uv run dojo test node d07_concurrency_control ex8
```

## The gate

This is the entire gate, `gate.test.ts`:

```ts
// Gate for node/d07_concurrency_control. Quoted verbatim in README.md.
//
// Every concurrency claim here is graded by COUNTING, never by timing. The gate
// holds each unit of work open with a deferred it controls and releases them
// one at a time, so "how many were in flight" is an exact number on any
// machine.
import { describe, expect, test } from "vitest";

import { createSemaphore } from "./ex1/solution";
import { singleFlight } from "./ex2/solution";
import { createTaskQueue } from "./ex3/solution";
import { batched } from "./ex4/solution";
import { mapSettledLimit } from "./ex5/solution";
import { createKeyedLock } from "./ex6/solution";
import { createPool } from "./ex7/solution";
import { mapLimitAbortable } from "./ex8/solution";

const settle = () => new Promise<void>((resolve) => setTimeout(resolve, 0));

/** A unit of work the gate can start, count and release by name. */
function workshop<T = string>() {
  const started: string[] = [];
  const releases = new Map<string, (value: T) => void>();
  const fails = new Map<string, (reason: unknown) => void>();
  let active = 0;
  let maxActive = 0;

  const task = (name: string) => (): Promise<T> => {
    started.push(name);
    active += 1;
    maxActive = Math.max(maxActive, active);
    return new Promise<T>((resolve, reject) => {
      releases.set(name, (value: T) => {
        active -= 1;
        resolve(value);
      });
      fails.set(name, (reason: unknown) => {
        active -= 1;
        reject(reason);
      });
    });
  };

  return {
    task,
    started,
    release: (name: string, value: T) => releases.get(name)?.(value),
    fail: (name: string, reason: unknown) => fails.get(name)?.(reason),
    maxActive: () => maxActive,
  };
}

describe("d07_concurrency_control", () => {
  test("ex1 - createSemaphore() hands out permits and takes them back", async () => {
    const semaphore = createSemaphore(2);
    const entered: string[] = [];
    const release = new Map<string, () => void>();

    for (const name of ["a", "b", "c", "d"]) {
      void semaphore.acquire().then((done) => {
        entered.push(name);
        release.set(name, done);
      });
    }
    await settle();

    expect(
      entered,
      "two permits means exactly two callers get in; the rest wait for one to " +
        "come back",
    ).toEqual(["a", "b"]);
    expect(semaphore.available(), "no permits left").toBe(0);
    expect(semaphore.waiting(), "and two callers queued").toBe(2);

    release.get("a")?.();
    await settle();
    expect(
      entered,
      "one release lets in exactly one more, and the queue is FIFO - c was " +
        "waiting before d",
    ).toEqual(["a", "b", "c"]);

    release.get("a")?.();
    await settle();
    expect(
      entered,
      "releasing the same permit twice must not conjure an extra one. Without " +
        "that guard a limit of 2 quietly becomes a limit of 3 the first time " +
        "somebody calls release in both a then and a finally",
    ).toEqual(["a", "b", "c"]);

    release.get("b")?.();
    await settle();
    expect(entered, "and now d gets in").toEqual(["a", "b", "c", "d"]);

    release.get("c")?.();
    release.get("d")?.();
    await settle();
    expect(semaphore.available(), "everything handed back").toBe(2);
    expect(semaphore.waiting(), "nobody waiting").toBe(0);
  });

  test("ex2 - singleFlight() collapses overlapping calls into one", async () => {
    const shop = workshop();
    const load = singleFlight(shop.task("load"));

    const first = load();
    const second = load();
    const third = load();
    await settle();

    expect(
      shop.started,
      "three overlapping callers, one actual call. This is the fix for the " +
        "cache stampede: a hundred requests arriving on a cold cache must not " +
        "become a hundred database queries",
    ).toEqual(["load"]);

    shop.release("load", "value-1");
    expect(
      [await first, await second, await third],
      "and every caller of that flight gets the same answer",
    ).toEqual(["value-1", "value-1", "value-1"]);

    const later = load();
    await settle();
    expect(
      shop.started,
      "once the flight has landed, the next call starts a new one - this is " +
        "de-duplication, not caching, and the difference is the whole point",
    ).toEqual(["load", "load"]);
    shop.release("load", "value-2");
    expect(await later, "with the newer value").toBe("value-2");

    const failingShop = workshop();
    const flaky = singleFlight(failingShop.task("flaky"));
    const doomedA = flaky();
    const doomedB = flaky();
    doomedA.catch(() => {});
    doomedB.catch(() => {});
    await settle();
    failingShop.fail("flaky", new Error("upstream down"));

    await expect(doomedA, "a failed flight fails every caller in it").rejects.toThrow(
      "upstream down",
    );
    await expect(doomedB).rejects.toThrow("upstream down");

    void flaky();
    await settle();
    expect(
      failingShop.started,
      "and a failure is never remembered: the next caller gets a real attempt",
    ).toEqual(["flaky", "flaky"]);
  });

  test("ex3 - createTaskQueue() keeps N running and survives a failing task", async () => {
    const shop = workshop();
    const queue = createTaskQueue({ concurrency: 2 });

    const results = new Map<string, Promise<string>>();
    for (const name of ["a", "b", "c", "d"]) {
      const promise = queue.push(shop.task(name));
      promise.catch(() => {});
      results.set(name, promise);
    }
    await settle();

    expect(shop.started, "two start, two wait").toEqual(["a", "b"]);
    expect(queue.active(), "two in flight").toBe(2);
    expect(queue.size(), "and two still queued").toBe(2);

    shop.fail("a", new Error("a exploded"));
    await settle();
    await expect(
      results.get("a"),
      "push() hands back a promise for THAT task, so a failure lands on the " +
        "caller who submitted it",
    ).rejects.toThrow("a exploded");
    expect(
      shop.started,
      "and the queue keeps going - one bad task must not stop the pipeline",
    ).toEqual(["a", "b", "c"]);

    const idle = queue.onIdle();
    let done = false;
    void idle.then(() => {
      done = true;
    });
    await settle();
    expect(done, "onIdle() waits while there is work").toBe(false);

    shop.release("b", "B");
    await settle();
    shop.release("c", "C");
    await settle();
    shop.release("d", "D");
    await settle();

    expect(await results.get("d"), "each caller gets its own result").toBe("D");
    await idle;
    expect(queue.active(), "nothing running").toBe(0);
    expect(queue.size(), "nothing queued").toBe(0);
    expect(shop.maxActive(), "and the limit held throughout").toBeLessThanOrEqual(2);
  });

  test("ex4 - batched() runs a batch together and the batches in order", async () => {
    const shop = workshop();
    const promise = batched(["a", "b", "c", "d", "e"], 2, (item: string) => shop.task(item)());
    promise.catch(() => {});
