// d07_concurrency_control / ex1 - reference solution (author only, used by `dojo verify`).

export interface Semaphore {
  acquire(): Promise<() => void>;
  available(): number;
  waiting(): number;
}

export function createSemaphore(limit: number): Semaphore {
  let free = limit;
  //: callers waiting for a permit, oldest first
  const queue: ((release: () => void) => void)[] = [];

  const makeRelease = (): (() => void) => {
    // One flag per permit handed out: this is what makes a double release a
    // no-op instead of an extra permit.
    let returned = false;
    return () => {
      if (returned) return;
      returned = true;
      const next = queue.shift();
      // Hand the permit straight on rather than incrementing and re-checking.
      if (next) next(makeRelease());
      else free += 1;
    };
  };

  return {
    acquire(): Promise<() => void> {
      if (free > 0) {
        free -= 1;
        return Promise.resolve(makeRelease());
      }
      return new Promise<() => void>((resolve) => {
        queue.push(resolve);
      });
    },
    available: () => free,
    waiting: () => queue.length,
  };
}

// d07_concurrency_control / ex2 - reference solution (author only, used by `dojo verify`).

export function singleFlight<T>(fn: () => Promise<T>): () => Promise<T> {
  let inFlight: Promise<T> | undefined;

  return (): Promise<T> => {
    if (inFlight) return inFlight;

    const flight = fn().finally(() => {
      // Clear only if this flight is still the current one, and clear on BOTH
      // outcomes - a remembered rejection would be a cache of a failure.
      if (inFlight === flight) inFlight = undefined;
    });
    // The .finally() promise is the one callers share, so every one of them
    // sees the same settlement.
    inFlight = flight;
    return flight;
  };
}

// d07_concurrency_control / ex3 - reference solution (author only, used by `dojo verify`).

export interface TaskQueue {
  push<T>(task: () => Promise<T>): Promise<T>;
  size(): number;
  active(): number;
  onIdle(): Promise<void>;
}

export function createTaskQueue(options: { concurrency: number }): TaskQueue {
  //: each entry starts its task and settles its own caller's promise
  const queued: (() => void)[] = [];
  const idleWaiters: (() => void)[] = [];
  let running = 0;

  const finish = (): void => {
    running -= 1;
    pump();
    if (running === 0 && queued.length === 0) {
      while (idleWaiters.length > 0) idleWaiters.shift()?.();
    }
  };

  const pump = (): void => {
    while (running < options.concurrency && queued.length > 0) {
      running += 1;
      queued.shift()?.();
    }
  };

  return {
    push<T>(task: () => Promise<T>): Promise<T> {
      return new Promise<T>((resolve, reject) => {
        queued.push(() => {
          // Each task's outcome goes to ITS caller. The queue itself never
          // sees a rejection, so one bad task cannot stop the pipeline.
          Promise.resolve()
            .then(task)
            .then(resolve, reject)
            .finally(finish);
        });
        pump();
      });
    },
    size: () => queued.length,
    active: () => running,
    onIdle(): Promise<void> {
      if (running === 0 && queued.length === 0) return Promise.resolve();
      return new Promise<void>((resolve) => {
        idleWaiters.push(resolve);
      });
    },
  };
}

// d07_concurrency_control / ex4 - reference solution (author only, used by `dojo verify`).

export async function batched<T, R>(
  items: readonly T[],
  size: number,
  worker: (item: T, index: number) => Promise<R>,
): Promise<R[]> {
  const results: R[] = [];

  for (let start = 0; start < items.length; start += size) {
    const group = items.slice(start, start + size);
    // The map starts every worker in the group; the await is the barrier that
    // makes the NEXT group wait for all of them.
    const settled = await Promise.all(
      group.map((item, offset) => worker(item, start + offset)),
    );
    results.push(...settled);
  }

  return results;
}

// d07_concurrency_control / ex5 - reference solution (author only, used by `dojo verify`).

export type Settled<R> =
  | { status: "fulfilled"; value: R }
  | { status: "rejected"; reason: unknown };

export async function mapSettledLimit<T, R>(
  items: readonly T[],
  limit: number,
  worker: (item: T, index: number) => Promise<R>,
): Promise<Settled<R>[]> {
  const results = new Array<Settled<R>>(items.length);
  //: the shared cursor. Reading and bumping it happens with no await in
  //: between, so no two runners can claim the same index.
  let next = 0;

  const runner = async (): Promise<void> => {
    for (;;) {
      const index = next;
      next += 1;
      if (index >= items.length) return;

      try {
        results[index] = { status: "fulfilled", value: await worker(items[index], index) };
      } catch (reason) {
        // Caught, recorded, and the loop carries on - which is what frees the
        // slot for the next item.
        results[index] = { status: "rejected", reason };
      }
    }
  };

  const runners = Array.from({ length: Math.min(limit, items.length) }, () => runner());
  await Promise.all(runners);
  return results;
}

// d07_concurrency_control / ex6 - reference solution (author only, used by `dojo verify`).

export interface KeyedLock {
  withLock<T>(key: string, fn: () => Promise<T>): Promise<T>;
  held(key: string): boolean;
}

export function createKeyedLock(): KeyedLock {
  //: key -> a promise that settles when the current holder is finished
  const tails = new Map<string, Promise<void>>();

  return {
    withLock<T>(key: string, fn: () => Promise<T>): Promise<T> {
      const previous = tails.get(key) ?? Promise.resolve();

      // Chaining onto the tail is the queue: each new caller waits for the one
      // in front of it, and becomes the new tail.
      const result = previous.then(fn);

      const tail = result.then(
        () => undefined,
        () => undefined, // a failed holder still releases the lock
      );
      tails.set(key, tail);

      void tail.then(() => {
        // Only the last waiter clears the entry, or a key in active use would
        // be forgotten mid-queue.
        if (tails.get(key) === tail) tails.delete(key);
      });

      return result;
    },

    held(key: string): boolean {
      return tails.has(key);
    },
  };
}

// d07_concurrency_control / ex7 - reference solution (author only, used by `dojo verify`).

export interface PoolOptions<T> {
  create: () => T;
  max: number;
}

export interface Pool<T> {
  acquire(): Promise<T>;
  release(resource: T): void;
  size(): number;
  waiting(): number;
}

export function createPool<T>(options: PoolOptions<T>): Pool<T> {
  const idle: T[] = [];
  const waiters: ((resource: T) => void)[] = [];
  let created = 0;

  return {
    acquire(): Promise<T> {
      // Reuse before creating: the whole point of a pool is that the expensive
      // part already happened.
      if (idle.length > 0) return Promise.resolve(idle.shift() as T);
      if (created < options.max) {
        created += 1;
        return Promise.resolve(options.create());
      }
      return new Promise<T>((resolve) => {
        waiters.push(resolve);
      });
    },

    release(resource: T): void {
      // Guard against a double release, or the same connection ends up lent to
      // two callers at once.
      if (idle.includes(resource)) return;
      const next = waiters.shift();
      if (next) next(resource);
      else idle.push(resource);
    },

    size: () => created,
    waiting: () => waiters.length,
  };
}

// d07_concurrency_control / ex8 - reference solution (author only, used by `dojo verify`).

export async function mapLimitAbortable<T, R>(
  items: readonly T[],
  limit: number,
  worker: (item: T, index: number, signal: AbortSignal) => Promise<R>,
  signal: AbortSignal,
): Promise<R[]> {
  // Check before anything: an already-aborted signal must not start work.
  if (signal.aborted) throw signal.reason;

  const results = new Array<R>(items.length);
  let next = 0;

  let onAbort!: () => void;
  const aborted = new Promise<never>((_resolve, reject) => {
    onAbort = () => reject(signal.reason);
    signal.addEventListener("abort", onAbort, { once: true });
  });
  // Nobody may ever look at this promise; make sure that is not a crash.
  aborted.catch(() => {});

  const runner = async (): Promise<void> => {
    // Re-checked every lap, so an abort stops the SCHEDULING immediately even
    // though the work already in flight cannot be un-started.
    while (!signal.aborted) {
      const index = next;
      next += 1;
      if (index >= items.length) return;
      results[index] = await worker(items[index], index, signal);
    }
  };

  const runners = Array.from({ length: Math.min(limit, items.length) }, () => runner());

  try {
    // Whichever happens first: all the work, or the cancellation.
    await Promise.race([Promise.all(runners), aborted]);
    return results;
  } finally {
    signal.removeEventListener("abort", onAbort);
  }
}

