// d08_promise_combinators / ex1 - reference solution (author only, used by `dojo verify`).

export function allInOrder<T>(promises: readonly Promise<T>[]): Promise<T[]> {
  return new Promise<T[]>((resolve, reject) => {
    // Pre-sized and written by index: that is what keeps input order without
    // any sorting, and why nothing here cares who finished first.
    const results = new Array<T>(promises.length);
    let remaining = promises.length;

    if (remaining === 0) {
      resolve([]);
      return;
    }

    promises.forEach((promise, index) => {
      promise.then((value) => {
        results[index] = value;
        remaining -= 1;
        if (remaining === 0) resolve(results);
      }, reject); // the first rejection settles the whole thing; later ones are no-ops
    });
  });
}

// d08_promise_combinators / ex2 - reference solution (author only, used by `dojo verify`).

export function raceFirst<T>(promises: readonly Promise<T>[]): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    // No bookkeeping at all: attach to everything and let the promise's own
    // settle-once rule pick the winner. An empty array attaches nothing, so
    // the promise stays pending forever - which is the specified behaviour.
    for (const promise of promises) promise.then(resolve, reject);
  });
}

// d08_promise_combinators / ex3 - reference solution (author only, used by `dojo verify`).

export function anyOf<T>(promises: readonly Promise<T>[]): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    const errors = new Array<unknown>(promises.length);
    let outstanding = promises.length;

    if (outstanding === 0) {
      reject(new AggregateError([], "all promises were rejected"));
      return;
    }

    promises.forEach((promise, index) => {
      promise.then(resolve, (reason: unknown) => {
        // By index, so the reasons stay in input order however they arrived.
        errors[index] = reason;
        outstanding -= 1;
        if (outstanding === 0) {
          reject(new AggregateError(errors, "all promises were rejected"));
        }
      });
    });
  });
}

// d08_promise_combinators / ex4 - reference solution (author only, used by `dojo verify`).

export function allWithProgress<T>(
  promises: readonly Promise<T>[],
  onProgress: (done: number, total: number) => void,
): Promise<T[]> {
  const total = promises.length;

  return new Promise<T[]>((resolve, reject) => {
    const results = new Array<T>(total);
    let done = 0;

    if (total === 0) {
      resolve([]);
      return;
    }

    promises.forEach((promise, index) => {
      promise.then((value) => {
        // Two different orders live side by side here: the write is by INDEX
        // (input order) and the report is by arrival (completion order).
        results[index] = value;
        done += 1;
        onProgress(done, total);
        if (done === total) resolve(results);
      }, reject);
    });
  });
}

// d08_promise_combinators / ex5 - reference solution (author only, used by `dojo verify`).

export type Outcome<T> =
  | { status: "fulfilled"; value: T }
  | { status: "rejected"; reason: unknown }
  | { status: "timedout" };

export function settleWithin<T>(
  promises: readonly Promise<T>[],
  ms: number,
): Promise<Outcome<T>[]> {
  return new Promise<Outcome<T>[]>((resolve) => {
    // Start with everything marked timedout and overwrite as answers arrive:
    // then the deadline handler has nothing to work out.
    const outcomes: Outcome<T>[] = promises.map(() => ({ status: "timedout" }));
    let remaining = promises.length;

    if (remaining === 0) {
      resolve([]);
      return;
    }

    const deadline = setTimeout(() => resolve(outcomes), ms);

    const finish = (): void => {
      remaining -= 1;
      if (remaining > 0) return;
      clearTimeout(deadline);
      resolve(outcomes);
    };

    promises.forEach((promise, index) => {
      promise.then(
        (value) => {
          outcomes[index] = { status: "fulfilled", value };
          finish();
        },
        (reason: unknown) => {
          outcomes[index] = { status: "rejected", reason };
          finish();
        },
      );
    });
  });
}

// d08_promise_combinators / ex6 - reference solution (author only, used by `dojo verify`).

export function firstMatching<T>(
  promises: readonly Promise<T>[],
  predicate: (value: T) => boolean,
): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    let outstanding = promises.length;

    const giveUp = (): void => {
      outstanding -= 1;
      // Only when every input has had its say: a value that failed the
      // predicate is not a reason to stop, it is a reason to keep waiting.
      if (outstanding === 0) reject(new Error("no result matched"));
    };

    if (outstanding === 0) {
      reject(new Error("no result matched"));
      return;
    }

    for (const promise of promises) {
      promise.then((value) => {
        if (predicate(value)) resolve(value);
        else giveUp();
      }, giveUp);
    }
  });
}

// d08_promise_combinators / ex7 - reference solution (author only, used by `dojo verify`).

export type Settled<T> =
  | { status: "fulfilled"; value: T }
  | { status: "rejected"; reason: unknown };

export interface Landed<T> {
  index: number;
  result: Settled<T>;
}

export async function* settledStream<T>(
  promises: readonly Promise<T>[],
): AsyncGenerator<Landed<T>, void, undefined> {
  const landed: Landed<T>[] = [];
  //: set while the consumer is waiting for something to arrive
  let wake: (() => void) | undefined;
  let remaining = promises.length;

  const deliver = (entry: Landed<T>): void => {
    landed.push(entry);
    const notify = wake;
    wake = undefined;
    notify?.();
  };

  // Attached up front, before the first yield: every input is already in
  // flight, and nothing may be missed while the consumer is away.
  promises.forEach((promise, index) => {
    promise.then(
      (value) => deliver({ index, result: { status: "fulfilled", value } }),
      (reason: unknown) => deliver({ index, result: { status: "rejected", reason } }),
    );
  });

  while (remaining > 0) {
    if (landed.length === 0) {
      await new Promise<void>((resolve) => {
        wake = resolve;
      });
    }
    while (landed.length > 0) {
      yield landed.shift() as Landed<T>;
      remaining -= 1;
    }
  }
}

// d08_promise_combinators / ex8 - reference solution (author only, used by `dojo verify`).

export function firstQuorum<T>(
  promises: readonly Promise<T>[],
  quorum: number,
): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    // Object.is semantics for the keys, which is what a Map gives you.
    const votes = new Map<T, number>();
    let undecided = promises.length;

    /**
     * The best score any value could still reach: the current leader plus
     * every vote not yet cast. If that is short of the quorum, no further
     * settlement can change the answer.
     */
    const checkImpossible = (): void => {
      let leader = 0;
      for (const count of votes.values()) leader = Math.max(leader, count);
      if (leader + undecided < quorum) reject(new Error("no quorum"));
    };

    if (promises.length === 0) {
      checkImpossible();
      return;
    }

    for (const promise of promises) {
      promise.then(
        (value) => {
          const count = (votes.get(value) ?? 0) + 1;
          votes.set(value, count);
          undecided -= 1;
          if (count >= quorum) resolve(value);
          else checkImpossible();
        },
        () => {
          undecided -= 1;
          checkImpossible();
        },
      );
    }
  });
}

