// d09_emitters / ex1 - reference solution (author only, used by `dojo verify`).
import { EventEmitter } from "node:events";

export class Store extends EventEmitter {
  readonly #entries = new Map<string, string>();

  set(key: string, value: string): void {
    const previous = this.#entries.get(key);
    // An event for something that did not change is noise, and noise is what
    // makes people stop listening.
    if (this.#entries.has(key) && previous === value) return;
    this.#entries.set(key, value);
    this.emit("change", key, value, previous);
  }

  get(key: string): string | undefined {
    return this.#entries.get(key);
  }

  delete(key: string): boolean {
    const value = this.#entries.get(key);
    if (!this.#entries.delete(key)) return false;
    this.emit("delete", key, value);
    return true;
  }

  size(): number {
    return this.#entries.size;
  }
}

// d09_emitters / ex2 - reference solution (author only, used by `dojo verify`).
import type { EventEmitter } from "node:events";

export interface FirstEvent {
  event: string;
  args: unknown[];
}

export function firstOf(
  emitter: EventEmitter,
  names: readonly string[],
): Promise<FirstEvent> {
  return new Promise<FirstEvent>((resolve, reject) => {
    // Keep what was added so exactly that can be removed - never
    // removeAllListeners, which would take other people's listeners with it.
    const added: Array<[string, (...args: unknown[]) => void]> = [];

    const cleanup = (): void => {
      for (const [event, listener] of added) emitter.off(event, listener);
      added.length = 0;
    };

    const onError = (error: unknown): void => {
      cleanup();
      reject(error);
    };
    emitter.on("error", onError);
    added.push(["error", onError as (...args: unknown[]) => void]);

    for (const name of names) {
      const listener = (...args: unknown[]): void => {
        cleanup();
        resolve({ event: name, args });
      };
      emitter.on(name, listener);
      added.push([name, listener]);
    }
  });
}

// d09_emitters / ex3 - reference solution (author only, used by `dojo verify`).
import type { EventEmitter } from "node:events";

export interface ForwardOptions {
  events: readonly string[];
  prefix?: string;
}

export function forward(
  source: EventEmitter,
  target: EventEmitter,
  options: ForwardOptions,
): () => void {
  const prefix = options.prefix ?? "";
  const added: Array<[string, (...args: unknown[]) => void]> = [];

  for (const event of options.events) {
    // Named once, kept, and used for both on() and off(): a fresh arrow
    // function at removal time is a different function and removes nothing.
    const listener = (...args: unknown[]): void => {
      target.emit(`${prefix}${event}`, ...args);
    };
    source.on(event, listener);
    added.push([event, listener]);
  }

  return () => {
    for (const [event, listener] of added) source.off(event, listener);
    // Emptying the list is what makes a second call a no-op.
    added.length = 0;
  };
}

// d09_emitters / ex4 - reference solution (author only, used by `dojo verify`).

export type Listener = (...args: unknown[]) => void;

export interface StickyEmitter {
  emit(event: string, ...args: unknown[]): boolean;
  on(event: string, listener: Listener): void;
  off(event: string, listener: Listener): void;
  buffered(event: string): number;
}

export function createStickyEmitter(): StickyEmitter {
  const listeners = new Map<string, Listener[]>();
  const backlog = new Map<string, unknown[][]>();

  return {
    emit(event: string, ...args: unknown[]): boolean {
      const current = listeners.get(event) ?? [];
      if (current.length === 0) {
        const waiting = backlog.get(event) ?? [];
        waiting.push(args);
        backlog.set(event, waiting);
        return false;
      }
      // A copy, so a listener that unsubscribes mid-dispatch cannot make the
      // loop skip the one behind it.
      for (const listener of [...current]) listener(...args);
      return true;
    },

    on(event: string, listener: Listener): void {
      const current = listeners.get(event) ?? [];
      const wasEmpty = current.length === 0;
      current.push(listener);
      listeners.set(event, current);

      if (!wasEmpty) return;
      const waiting = backlog.get(event);
      if (!waiting) return;
      // Spend the backlog: delete first, so a listener that emits during the
      // replay cannot be replayed to itself.
      backlog.delete(event);
      for (const args of waiting) listener(...args);
    },

    off(event: string, listener: Listener): void {
      const current = listeners.get(event);
      if (!current) return;
      const index = current.indexOf(listener);
      if (index >= 0) current.splice(index, 1);
    },

    buffered(event: string): number {
      return backlog.get(event)?.length ?? 0;
    },
  };
}

// d09_emitters / ex5 - reference solution (author only, used by `dojo verify`).
import type { EventEmitter } from "node:events";

export function iterateEvents<T>(emitter: EventEmitter, name: string): AsyncIterable<T> {
  const queue: T[] = [];
  let finished = false;
  let failed = false;
  let failure: unknown;
  let wake: (() => void) | undefined;

  const notify = (): void => {
    const resume = wake;
    wake = undefined;
    resume?.();
  };

  const onData = (value: T): void => {
    queue.push(value);
    notify();
  };
  const onEnd = (): void => {
    finished = true;
    notify();
  };
  const onError = (error: unknown): void => {
    failed = true;
    failure = error;
    finished = true;
    notify();
  };

  // Attached NOW, not on the first next(): a generator body does not run until
  // it is pulled, and events emitted in the meantime would be lost.
  emitter.on(name, onData as (...args: unknown[]) => void);
  emitter.on("end", onEnd);
  emitter.on("error", onError);

  const cleanup = (): void => {
    emitter.off(name, onData as (...args: unknown[]) => void);
    emitter.off("end", onEnd);
    emitter.off("error", onError);
  };

  async function* iterate(): AsyncGenerator<T, void, undefined> {
    try {
      for (;;) {
        // Drain what is buffered before looking at the terminal states, so an
        // error never swallows values that already arrived.
        while (queue.length > 0) yield queue.shift() as T;
        if (failed) throw failure;
        if (finished) return;
        await new Promise<void>((resolve) => {
          wake = resolve;
        });
      }
    } finally {
      cleanup();
    }
  }

  return { [Symbol.asyncIterator]: iterate };
}

// d09_emitters / ex6 - reference solution (author only, used by `dojo verify`).

export type Listener = (...args: unknown[]) => void;

export interface StrictEmitter {
  on(event: string, listener: Listener): void;
  once(event: string, listener: Listener): void;
  off(event: string, listener: Listener): void;
  emit(event: string, ...args: unknown[]): boolean;
  listenerCount(event: string): number;
}

interface Registration {
  listener: Listener;
  once: boolean;
}

export function createStrictEmitter(): StrictEmitter {
  const registry = new Map<string, Registration[]>();

  const add = (event: string, listener: Listener, once: boolean): void => {
    const current = registry.get(event) ?? [];
    current.push({ listener, once });
    registry.set(event, current);
  };

  const remove = (event: string, listener: Listener): void => {
    const current = registry.get(event);
    if (!current) return;
    const index = current.findIndex((entry) => entry.listener === listener);
    if (index >= 0) current.splice(index, 1);
  };

  return {
    on: (event, listener) => add(event, listener, false),
    once: (event, listener) => add(event, listener, true),
    off: remove,

    emit(event, ...args): boolean {
      // A copy: listeners may register or remove listeners while running.
      const current = [...(registry.get(event) ?? [])];

      if (current.length === 0) {
        if (event !== "error") return false;
        // The one event whose absence of a listener is itself an error.
        const reason = args[0];
        throw reason instanceof Error
          ? reason
          : new Error(`unhandled error event: ${String(reason)}`);
      }

      for (const entry of current) {
        // Removed BEFORE it runs, so a listener that re-emits its own event
        // cannot find itself still registered.
        if (entry.once) remove(event, entry.listener);
        entry.listener(...args);
      }
      return true;
    },

    listenerCount: (event) => registry.get(event)?.length ?? 0,
  };
}

// d09_emitters / ex7 - reference solution (author only, used by `dojo verify`).

export interface CoalescingEmitter {
  push(value: string): void;
  on(listener: (batch: string[]) => void): void;
  flush(): void;
  pending(): number;
}

export function createCoalescingEmitter(options: {
  windowMs: number;
}): CoalescingEmitter {
  const listeners: ((batch: string[]) => void)[] = [];
  let buffer: string[] = [];
  let handle: ReturnType<typeof setTimeout> | undefined;

  const deliver = (): void => {
    if (handle !== undefined) {
      clearTimeout(handle);
      handle = undefined;
    }
    if (buffer.length === 0) return; // an empty batch is not a batch
    const batch = buffer;
    // A new array, not buffer.length = 0: the listeners are holding this one.
    buffer = [];
    for (const listener of listeners) listener(batch);
  };

  return {
    push(value: string): void {
      buffer.push(value);
      // Only if no window is open. Re-arming here would make this a debounce,
      // and a busy producer could hold a value back forever.
      if (handle === undefined) {
        handle = setTimeout(() => {
          handle = undefined;
          deliver();
        }, options.windowMs);
      }
    },
    on(listener): void {
      listeners.push(listener);
    },
    flush: deliver,
    pending: () => buffer.length,
  };
}

// d09_emitters / ex8 - reference solution (author only, used by `dojo verify`).
import type { EventEmitter } from "node:events";

export function onceWithSignal<T>(
  emitter: EventEmitter,
  name: string,
  signal: AbortSignal,
): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    // Checked before anything is attached: an already-aborted caller must not
    // leave a listener behind on a long-lived emitter.
    if (signal.aborted) {
      reject(signal.reason);
      return;
    }

    const onEvent = (value: T): void => {
      cleanup();
      resolve(value);
    };
    const onAbort = (): void => {
      cleanup();
      reject(signal.reason);
    };

    function cleanup(): void {
      emitter.off(name, onEvent as (...args: unknown[]) => void);
      signal.removeEventListener("abort", onAbort);
    }

    emitter.on(name, onEvent as (...args: unknown[]) => void);
    signal.addEventListener("abort", onAbort, { once: true });
  });
}

