// d10_error_patterns / ex1 - reference solution (author only, used by `dojo verify`).

export function asError(thrown: unknown): Error {
  // instanceof covers every subclass too, and returning the same object keeps
  // the original stack trace rather than one taken here.
  if (thrown instanceof Error) return thrown;

  if (typeof thrown === "string") return new Error(thrown);

  if (
    typeof thrown === "object" &&
    thrown !== null &&
    typeof (thrown as { message?: unknown }).message === "string"
  ) {
    // The shape a JSON error response or a cross-realm error arrives in.
    return new Error((thrown as { message: string }).message, { cause: thrown });
  }

  return new Error(String(thrown), { cause: thrown });
}

// d10_error_patterns / ex2 - reference solution (author only, used by `dojo verify`).

export interface GuardedCallback<A extends unknown[]> {
  (...args: A): void;
  calls(): number;
  suppressed(): number;
}

export function onceCallback<A extends unknown[]>(
  callback: (...args: A) => void,
): GuardedCallback<A> {
  let calls = 0;
  let suppressed = 0;

  const guarded = ((...args: A): void => {
    if (calls > 0) {
      // Counted, not thrown: the caller is a library you do not control, and
      // crashing it does not make its bug your problem any less.
      suppressed += 1;
      return;
    }
    calls += 1;
    callback(...args);
  }) as GuardedCallback<A>;

  guarded.calls = () => calls;
  guarded.suppressed = () => suppressed;

  return guarded;
}

// d10_error_patterns / ex3 - reference solution (author only, used by `dojo verify`).

export function ensureAsync<A extends unknown[], R>(
  fn: (...args: A) => R | Promise<R>,
): (...args: A) => Promise<R> {
  // An `async` wrapper is the whole trick: the body runs synchronously up to
  // its first await, but a throw from it becomes a rejection of the promise
  // the wrapper already returned, and a returned promise is adopted.
  return async (...args: A): Promise<R> => fn(...args);
}

// d10_error_patterns / ex4 - reference solution (author only, used by `dojo verify`).

export interface Explanation {
  chain: string[];
  root: Error;
  depth: number;
}

export function explain(error: Error): Explanation {
  const chain: string[] = [];
  // Identity, not messages: two different errors are allowed to say the same
  // thing, and a Set of objects is what makes the loop guard exact.
  const seen = new Set<Error>();

  let current: Error = error;
  for (;;) {
    seen.add(current);
    chain.push(current.message);

    const cause = (current as Error & { cause?: unknown }).cause;
    // Only an Error is another link. Anything else is a payload.
    if (!(cause instanceof Error) || seen.has(cause)) break;
    current = cause;
  }

  return { chain, root: current, depth: chain.length };
}

// d10_error_patterns / ex5 - reference solution (author only, used by `dojo verify`).

function messageOf(thrown: unknown): string {
  return thrown instanceof Error ? thrown.message : String(thrown);
}

export function withContext<A extends unknown[], R>(
  fn: (...args: A) => Promise<R>,
  context: string,
): (...args: A) => Promise<R> {
  return async (...args: A): Promise<R> => {
    try {
      // `return await`, not `return`: without the await the rejection is not
      // in flight inside this function and the catch never sees it.
      return await fn(...args);
    } catch (error) {
      // A new error every time. Editing the message of the one you caught
      // changes it for everybody else who is holding it.
      throw new Error(`${context}: ${messageOf(error)}`, { cause: error });
    }
  };
}

// d10_error_patterns / ex6 - reference solution (author only, used by `dojo verify`).

export interface SwallowOptions<R> {
  when: (error: Error) => boolean;
  fallback: R;
}

function asError(thrown: unknown): Error {
  return thrown instanceof Error ? thrown : new Error(String(thrown), { cause: thrown });
}

export async function swallow<R>(
  fn: () => Promise<R>,
  options: SwallowOptions<R>,
): Promise<R> {
  try {
    return await fn();
  } catch (error) {
    // Normalised for the PREDICATE, so it can read .message without checking
    // the type - but the original is what gets rethrown, because that is the
    // object with the real stack on it.
    if (options.when(asError(error))) return options.fallback;
    throw error;
  }
}

// d10_error_patterns / ex7 - reference solution (author only, used by `dojo verify`).

function linksBelow(error: Error): Error[] {
  const links: Error[] = [];

  if (error instanceof AggregateError && Array.isArray(error.errors)) {
    for (const entry of error.errors as unknown[]) {
      if (entry instanceof Error) links.push(entry);
    }
  }

  const cause = (error as Error & { cause?: unknown }).cause;
  if (cause instanceof Error) links.push(cause);

  return links;
}

export function flattenErrors(error: unknown): Error[] {
  if (!(error instanceof Error)) return [];

  const leaves: Error[] = [];
  const seen = new Set<Error>();

  const visit = (current: Error): void => {
    if (seen.has(current)) return;
    seen.add(current);

    // Filtering out what is already visited is what makes a cycle terminate:
    // an error whose only link points back up the tree has nothing new below
    // it, so it is the bottom.
    const unvisited = linksBelow(current).filter((link) => !seen.has(link));
    if (unvisited.length === 0) {
      leaves.push(current);
      return;
    }
    for (const link of unvisited) visit(link);
  };

  visit(error);
  return leaves;
}

// d10_error_patterns / ex8 - reference solution (author only, used by `dojo verify`).

export type Category = "operational" | "fatal";

export interface BoundaryOptions {
  classify: (error: Error) => Category;
  onOperational: (error: Error) => void;
  onFatal: (error: Error) => void;
}

export interface ErrorBoundary {
  handle(thrown: unknown): void;
}

function asError(thrown: unknown): Error {
  return thrown instanceof Error ? thrown : new Error(String(thrown), { cause: thrown });
}

export function createErrorBoundary(options: BoundaryOptions): ErrorBoundary {
  return {
    handle(thrown: unknown): void {
      const error = asError(thrown);

      let category: Category;
      try {
        category = options.classify(error);
      } catch {
        // Cannot tell what it is - assume the worst, and report the error that
        // somebody actually has to fix rather than the classifier's complaint.
        options.onFatal(error);
        return;
      }

      if (category === "fatal") {
        // Deliberately unguarded: if the last handler fails there is nowhere
        // left to send it, and swallowing it here would lose both errors.
        options.onFatal(error);
        return;
      }

      try {
        options.onOperational(error);
      } catch (handlerFailure) {
        options.onFatal(asError(handlerFailure));
      }
    },
  };
}

