// d11_custom_errors / ex1 - reference solution (author only, used by `dojo verify`).

export class NotFoundError extends Error {
  readonly resource: string;
  readonly id: string;
  readonly status: number = 404;

  constructor(resource: string, id: string) {
    super(`${resource} not found: ${id}`);
    // Without this every log line about this failure just says "Error". Set it
    // before anybody reads .stack, which is formatted from name and message.
    this.name = "NotFoundError";
    this.resource = resource;
    this.id = id;
  }
}

// d11_custom_errors / ex2 - reference solution (author only, used by `dojo verify`).

export interface HttpErrorOptions {
  cause?: unknown;
}

export class HttpError extends Error {
  readonly status: number;
  readonly expose: boolean;

  constructor(status: number, message: string, options?: HttpErrorOptions) {
    // The options object has to reach Error itself, or `cause` never gets set
    // and the chain stops at this subclass.
    super(message, options);
    // new.target.name gives each subclass its own name without every subclass
    // repeating the line.
    this.name = new.target.name;
    this.status = status;
    this.expose = status < 500;
  }
}

export class BadRequestError extends HttpError {
  constructor(message: string, options?: HttpErrorOptions) {
    super(400, message, options);
  }
}

export class ConflictError extends HttpError {
  constructor(message: string, options?: HttpErrorOptions) {
    super(409, message, options);
  }
}

// d11_custom_errors / ex3 - reference solution (author only, used by `dojo verify`).

export interface SerialisedError {
  name: string;
  message: string;
  code?: string;
  status?: number;
  cause?: SerialisedError;
}

export function serialiseError(error: Error): SerialisedError {
  const seen = new Set<Error>();

  const walk = (current: Error): SerialisedError => {
    seen.add(current);

    const extra = current as Error & { code?: unknown; status?: unknown; cause?: unknown };
    const result: SerialisedError = { name: current.name, message: current.message };

    // Assigned conditionally rather than always: an absent key is absent, not
    // a key whose value is undefined.
    if (typeof extra.code === "string") result.code = extra.code;
    if (typeof extra.status === "number") result.status = extra.status;
    if (extra.cause instanceof Error && !seen.has(extra.cause)) {
      result.cause = walk(extra.cause);
    }

    return result;
  };

  return walk(error);
}

// d11_custom_errors / ex4 - reference solution (author only, used by `dojo verify`).

export interface SerialisedError {
  name: string;
  message: string;
  code?: string;
  status?: number;
  cause?: SerialisedError;
}

export type ErrorClass = new (message: string) => Error;

export function reviveError(
  json: SerialisedError,
  registry: Record<string, ErrorClass>,
): Error {
  // hasOwnProperty rather than a bare lookup: a name like "constructor" or
  // "toString" would otherwise find something on Object.prototype.
  const Known = Object.prototype.hasOwnProperty.call(registry, json.name)
    ? registry[json.name]
    : undefined;

  const error = Known ? new Known(json.message) : new Error(json.message);

  // Even without a class, the name is the only clue left about what failed.
  error.name = json.name;

  const target = error as Error & { code?: string; status?: number; cause?: unknown };
  if (json.code !== undefined) target.code = json.code;
  if (json.status !== undefined) target.status = json.status;
  if (json.cause) target.cause = reviveError(json.cause, registry);

  return error;
}

// d11_custom_errors / ex5 - reference solution (author only, used by `dojo verify`).

export class RetryableError extends Error {
  readonly code: string;

  constructor(message: string, code: string, options?: { cause?: unknown }) {
    super(message, options);
    this.name = "RetryableError";
    this.code = code;
  }

  static is(value: unknown): value is RetryableError {
    return value instanceof RetryableError;
  }

  static wrap(thrown: unknown, code: string): RetryableError {
    // Idempotent: without this a retry loop adds a link to the cause chain on
    // every attempt, and after five retries the message is five levels deep.
    if (RetryableError.is(thrown)) return thrown;

    const message = thrown instanceof Error ? thrown.message : String(thrown);
    return new RetryableError(message, code, { cause: thrown });
  }
}

// d11_custom_errors / ex6 - reference solution (author only, used by `dojo verify`).

export class BatchError extends AggregateError {
  readonly operation: string;

  constructor(operation: string, errors: readonly Error[]) {
    // The spread is the copy: AggregateError takes an iterable and builds its
    // own array, but being explicit says the intent out loud.
    super([...errors], `${operation}: ${errors.length} failed`);
    this.name = "BatchError";
    this.operation = operation;
  }

  codes(): string[] {
    const found = new Set<string>();
    for (const error of this.errors as unknown[]) {
      const code = (error as { code?: unknown }).code;
      if (typeof code === "string") found.add(code);
    }
    return [...found].sort();
  }
}

// d11_custom_errors / ex7 - reference solution (author only, used by `dojo verify`).

/** Two string fields is the smallest honest definition of "error shaped". */
function looksLikeError(value: unknown): value is { name: string; message: string } {
  return (
    typeof value === "object" &&
    value !== null &&
    typeof (value as { name?: unknown }).name === "string" &&
    typeof (value as { message?: unknown }).message === "string"
  );
}

export function isErrorOfType(value: unknown, name: string): boolean {
  return looksLikeError(value) && value.name === name;
}

export class ErrorLike {
  // instanceof consults this when the right-hand side defines it, so a class
  // can decide for itself what membership means.
  static [Symbol.hasInstance](value: unknown): boolean {
    return looksLikeError(value);
  }
}

// d11_custom_errors / ex8 - reference solution (author only, used by `dojo verify`).

export interface Issue {
  path: string;
  code: string;
  message: string;
}

export type Rule = (value: unknown, path: string) => Issue | null;

export class ValidationFailed extends Error {
  readonly issues: readonly Issue[];

  constructor(issues: readonly Issue[]) {
    super(`validation failed (${issues.length} issues)`);
    this.name = "ValidationFailed";
    this.issues = [...issues];
  }

  // JSON.stringify calls this. Without it an Error serialises to {} - its own
  // properties are non-enumerable - and the whole report is lost.
  toJSON(): { name: string; message: string; issues: Issue[] } {
    return { name: this.name, message: this.message, issues: [...this.issues] };
  }
}

export function validate(
  input: Record<string, unknown>,
  rules: Record<string, Rule[]>,
): void {
  const issues: Issue[] = [];

  for (const [path, forPath] of Object.entries(rules)) {
    for (const rule of forPath) {
      // No early exit anywhere: the caller wants every problem in one round
      // trip, not one per resubmission.
      const issue = rule(input[path], path);
      if (issue) issues.push(issue);
    }
  }

  if (issues.length > 0) throw new ValidationFailed(issues);
}

