// d12_fs_ops / ex1 - reference solution (author only, used by `dojo verify`).
import { randomUUID } from "node:crypto";
import { mkdir, rename, rm, writeFile } from "node:fs/promises";
import path from "node:path";

export async function writeTextAtomic(file: string, text: string): Promise<void> {
  const directory = path.dirname(file);
  await mkdir(directory, { recursive: true });

  // Same directory, so the rename stays inside one filesystem - across a mount
  // point rename degrades to copy-and-delete and stops being atomic. Unique
  // name, so two writers cannot steal each other temporary file.
  const temporary = path.join(directory, `.${path.basename(file)}.${randomUUID()}.tmp`);

  try {
    await writeFile(temporary, text, "utf8");
    await rename(temporary, file);
  } catch (error) {
    await rm(temporary, { force: true });
    throw error;
  }
}

// d12_fs_ops / ex2 - reference solution (author only, used by `dojo verify`).
import { copyFile, mkdir, readdir } from "node:fs/promises";
import path from "node:path";

export interface CopyOptions {
  skip?: (relativePath: string) => boolean;
}

export async function copyTree(
  src: string,
  dest: string,
  options: CopyOptions = {},
): Promise<string[]> {
  const skip = options.skip ?? (() => false);
  const copied: string[] = [];

  // The relative path is carried as a forward-slash string and only turned
  // into a real path when the filesystem needs one. That way the values that
  // go into `copied` are portable by construction.
  const walk = async (relative: string): Promise<void> => {
    const from = relative === "" ? src : path.join(src, ...relative.split("/"));

    for (const entry of await readdir(from, { withFileTypes: true })) {
      const child = relative === "" ? entry.name : `${relative}/${entry.name}`;
      if (skip(child)) continue;

      const target = path.join(dest, ...child.split("/"));
      if (entry.isDirectory()) {
        await mkdir(target, { recursive: true });
        await walk(child);
      } else if (entry.isFile()) {
        await copyFile(path.join(from, entry.name), target);
        copied.push(child);
      }
    }
  };

  await mkdir(dest, { recursive: true });
  await walk("");
  return copied.sort();
}

// d12_fs_ops / ex3 - reference solution (author only, used by `dojo verify`).
import { readdir, stat } from "node:fs/promises";
import path from "node:path";

export interface DirStats {
  files: number;
  bytes: number;
}

export async function dirStats(dir: string): Promise<DirStats> {
  let files = 0;
  let bytes = 0;

  for (const entry of await readdir(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);

    if (entry.isDirectory()) {
      // The recursive call returns the same shape, so the totals just add up.
      const nested = await dirStats(full);
      files += nested.files;
      bytes += nested.bytes;
    } else if (entry.isFile()) {
      files += 1;
      bytes += (await stat(full)).size;
    }
  }

  return { files, bytes };
}

// d12_fs_ops / ex4 - reference solution (author only, used by `dojo verify`).
import { readdir, rmdir } from "node:fs/promises";
import path from "node:path";

export async function removeEmptyDirs(root: string): Promise<string[]> {
  const removed: string[] = [];

  /** Returns whether `relative` is empty AFTER its children have been pruned. */
  const visit = async (relative: string): Promise<boolean> => {
    const full = relative === "" ? root : path.join(root, ...relative.split("/"));
    let empty = true;

    for (const entry of await readdir(full, { withFileTypes: true })) {
      const child = relative === "" ? entry.name : `${relative}/${entry.name}`;

      if (!entry.isDirectory()) {
        empty = false;
        continue;
      }

      // Recurse FIRST: a directory is only empty once its children are gone,
      // which is why this cannot be done top down.
      if (await visit(child)) {
        await rmdir(path.join(root, ...child.split("/")));
        removed.push(child);
      } else {
        empty = false;
      }
    }

    return empty;
  };

  // The root is visited so its children are pruned, but never removed itself.
  await visit("");
  return removed.sort();
}

// d12_fs_ops / ex5 - reference solution (author only, used by `dojo verify`).
import { appendFile, mkdir, readFile } from "node:fs/promises";
import path from "node:path";

export async function appendJsonl(file: string, record: unknown): Promise<void> {
  await mkdir(path.dirname(file), { recursive: true });
  // The trailing newline is the format: it is what makes the next append a
  // new record rather than a continuation of this one.
  await appendFile(file, `${JSON.stringify(record)}\n`, "utf8");
}

export async function readJsonl<T>(file: string): Promise<T[]> {
  let raw: string;
  try {
    raw = await readFile(file, "utf8");
  } catch (error) {
    // ENOENT is the ONE failure that means "nothing has happened yet". Every
    // other one - a permissions problem, a directory where a file should be -
    // is real damage and must not be hidden behind an empty array.
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return [];
    throw error;
  }

  const records: T[] = [];
  const lines = raw.split("\n");

  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index];
    if (line.trim() === "") continue;
    try {
      records.push(JSON.parse(line) as T);
    } catch {
      // The line number, counted over EVERY line including the blank ones, is
      // the only thing that makes a four-million-line log debuggable.
      throw new Error(`invalid JSON on line ${index + 1}`);
    }
  }

  return records;
}

// d12_fs_ops / ex6 - reference solution (author only, used by `dojo verify`).
import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";

export async function withTempWorkspace<T>(
  run: (dir: string) => Promise<T>,
): Promise<T> {
  // mkdtemp appends random characters to the prefix and creates the directory
  // in one step - so two callers can never collide, even back to back.
  const dir = await mkdtemp(path.join(tmpdir(), "dojo-workspace-"));

  try {
    return await run(dir);
  } finally {
    // finally, not a line after the call: the cleanup has to happen on the
    // failure path too, and that is the path a half-written workspace is on.
    // force ignores an already-missing directory.
    await rm(dir, { recursive: true, force: true });
  }
}

// d12_fs_ops / ex7 - reference solution (author only, used by `dojo verify`).
import { copyFile, mkdir, readdir, rm, stat } from "node:fs/promises";
import path from "node:path";

export interface SyncReport {
  copied: string[];
  updated: string[];
  deleted: string[];
}

/** relative path (forward slashes) -> size in bytes, for every file below root. */
async function index(root: string): Promise<Map<string, number>> {
  const found = new Map<string, number>();

  const walk = async (relative: string): Promise<void> => {
    const full = relative === "" ? root : path.join(root, ...relative.split("/"));

    let entries;
    try {
      entries = await readdir(full, { withFileTypes: true });
    } catch (error) {
      // A destination that does not exist yet is an empty destination.
      if ((error as NodeJS.ErrnoException).code === "ENOENT") return;
      throw error;
    }

    for (const entry of entries) {
      const child = relative === "" ? entry.name : `${relative}/${entry.name}`;
      if (entry.isDirectory()) await walk(child);
      else if (entry.isFile()) {
        found.set(child, (await stat(path.join(full, entry.name))).size);
      }
    }
  };

  await walk("");
  return found;
}

export async function syncDirectories(src: string, dest: string): Promise<SyncReport> {
  // Both sides are indexed BEFORE anything is written, so the comparison is
  // made against a consistent picture rather than against a directory the
  // loop is halfway through modifying.
  const sources = await index(src);
  const targets = await index(dest);

  const copied: string[] = [];
  const updated: string[] = [];
  const deleted: string[] = [];

  for (const [relative, size] of sources) {
    const from = path.join(src, ...relative.split("/"));
    const to = path.join(dest, ...relative.split("/"));
    const existing = targets.get(relative);

    if (existing === undefined) {
      await mkdir(path.dirname(to), { recursive: true });
      await copyFile(from, to);
      copied.push(relative);
    } else if (existing !== size) {
      await copyFile(from, to);
      updated.push(relative);
    }
  }

  for (const relative of targets.keys()) {
    if (sources.has(relative)) continue;
    await rm(path.join(dest, ...relative.split("/")), { force: true });
    deleted.push(relative);
  }

  return { copied: copied.sort(), updated: updated.sort(), deleted: deleted.sort() };
}

// d12_fs_ops / ex8 - reference solution (author only, used by `dojo verify`).
import { createHash } from "node:crypto";
import { readFile, readdir } from "node:fs/promises";
import path from "node:path";

export async function findDuplicates(dir: string): Promise<string[][]> {
  const byDigest = new Map<string, string[]>();

  const walk = async (relative: string): Promise<void> => {
    const full = relative === "" ? dir : path.join(dir, ...relative.split("/"));

    for (const entry of await readdir(full, { withFileTypes: true })) {
      const child = relative === "" ? entry.name : `${relative}/${entry.name}`;

      if (entry.isDirectory()) {
        await walk(child);
        continue;
      }
      if (!entry.isFile()) continue;

      // The digest, not the contents, is the map key: a hash is a fixed 64
      // characters however big the file is.
      const contents = await readFile(path.join(full, entry.name));
      const digest = createHash("sha256").update(contents).digest("hex");

      const group = byDigest.get(digest) ?? [];
      group.push(child);
      byDigest.set(digest, group);
    }
  };

  await walk("");

  return [...byDigest.values()]
    .filter((group) => group.length > 1)
    .map((group) => [...group].sort())
    .sort((left, right) => (left[0] < right[0] ? -1 : left[0] > right[0] ? 1 : 0));
}

