// d13_path_portability / ex1 - reference solution (author only, used by `dojo verify`).
import path from "node:path";

export function relativeUrlPath(fromDir: string, toFile: string): string {
  const relative = path.relative(fromDir, toFile);
  // path.relative() answers in the platform separator; a URL only ever uses /.
  return relative === "" ? "." : relative.split(path.sep).join("/");
}

// d13_path_portability / ex2 - reference solution (author only, used by `dojo verify`).
import path from "node:path";

export function changeExtension(file: string, ext: string): string {
  const parsed = path.parse(file);
  const wanted = ext === "" || ext.startsWith(".") ? ext : `.${ext}`;
  // path.format() prefers `base` over `name` + `ext`, so the parsed object is
  // taken apart rather than spread - spreading it would ignore the new ext.
  return path.format({ dir: parsed.dir, name: parsed.name, ext: wanted });
}

// d13_path_portability / ex3 - reference solution (author only, used by `dojo verify`).
import path from "node:path";

export function safeJoin(root: string, ...segments: string[]): string | null {
  const base = path.resolve(root);
  const target = path.resolve(base, path.join(...segments));

  const relative = path.relative(base, target);
  if (relative === "") return target;
  // Segments, not characters: startsWith("..") would also reject a directory
  // that is honestly called "..config".
  if (path.isAbsolute(relative) || relative.split(path.sep)[0] === "..") return null;
  return target;
}

// d13_path_portability / ex4 - reference solution (author only, used by `dojo verify`).
import path from "node:path";

export function commonAncestor(paths: string[]): string | null {
  if (paths.length === 0) return null;

  const split = paths.map((entry) => path.resolve(entry).split(path.sep));
  let common = split[0];

  for (const parts of split.slice(1)) {
    let i = 0;
    while (i < common.length && i < parts.length && common[i] === parts[i]) i += 1;
    common = common.slice(0, i);
  }

  // Nothing shared at all: different drives on Windows, and nothing on POSIX.
  if (common.length === 0) return null;
  // ["", "var"] joins to "/var"; ["", ""] would join to "" and means the root.
  return common.join(path.sep) || path.sep;
}

// d13_path_portability / ex5 - reference solution (author only, used by `dojo verify`).
import path from "node:path";

export function resolveDocLink(fromFile: string, link: string): string | null {
  if (link === "" || link.startsWith("#")) return null;
  // "//host/path" is protocol-relative and has to be checked before the scheme.
  if (link.startsWith("//")) return null;
  if (/^[a-z][a-z0-9+.-]*:/i.test(link)) return null;
  if (link.startsWith("/")) return null;

  const target = link.split("#")[0].split("?")[0];
  if (target === "") return null;

  // A link is percent-encoded; a filename is not.
  const decoded = decodeURIComponent(target);
  // Links are written with forward slashes whatever the platform, so the
  // segments are split here rather than handed to resolve() as one string.
  return path.resolve(path.dirname(fromFile), ...decoded.split("/"));
}

// d13_path_portability / ex6 - reference solution (author only, used by `dojo verify`).
import path from "node:path";

export interface OutputOptions {
  srcRoot: string;
  outRoot: string;
  ext?: string;
}

export function outputPathFor(file: string, options: OutputOptions): string | null {
  const from = path.resolve(options.srcRoot);
  const target = path.resolve(file);

  const relative = path.relative(from, target);
  // "" is the root itself, which is a directory and not an input file.
  if (relative === "") return null;
  if (path.isAbsolute(relative) || relative.split(path.sep)[0] === "..") return null;

  const moved = path.join(options.outRoot, relative);
  if (options.ext === undefined) return moved;

  const parsed = path.parse(moved);
  const wanted = options.ext === "" || options.ext.startsWith(".") ? options.ext : `.${options.ext}`;
  return path.format({ dir: parsed.dir, name: parsed.name, ext: wanted });
}

// d13_path_portability / ex7 - reference solution (author only, used by `dojo verify`).

/** One segment of a pattern, as a regular expression anchored at both ends. */
function segmentMatcher(segment: string): RegExp {
  const escaped = segment
    .replace(/[.*+?^${}()|[\]\\]/g, "\\$&")
    // ...and then put the wildcard back, as "anything but a separator".
    .replace(/\\\*/g, "[^/]*");
  return new RegExp(`^${escaped}$`);
}

export function matchesGlob(pattern: string, filePath: string): boolean {
  const patternParts = pattern.split("/").filter((part) => part !== "");
  const fileParts = filePath.split("/").filter((part) => part !== "");

  const match = (p: number, f: number): boolean => {
    if (p === patternParts.length) return f === fileParts.length;

    if (patternParts[p] === "**") {
      // Zero segments first, then one, then two... every split has to be tried,
      // which is why this is a search and not a single regular expression.
      for (let take = f; take <= fileParts.length; take += 1) {
        if (match(p + 1, take)) return true;
      }
      return false;
    }

    if (f === fileParts.length) return false;
    return segmentMatcher(patternParts[p]).test(fileParts[f]) && match(p + 1, f + 1);
  };

  return match(0, 0);
}

// d13_path_portability / ex8 - reference solution (author only, used by `dojo verify`).

/** The last `take` segments of a path, as a string. */
function suffixOf(segments: string[], take: number): string {
  return segments.slice(Math.max(0, segments.length - take)).join("/");
}

export function shortestUniqueLabels(paths: string[]): Record<string, string> {
  const segments = paths.map((entry) => entry.split("/").filter((part) => part !== ""));
  const labels: Record<string, string> = {};

  paths.forEach((entry, index) => {
    const own = segments[index];
    for (let take = 1; take <= own.length; take += 1) {
      const candidate = suffixOf(own, take);
      // A shorter path can only clash by being entirely equal to the suffix,
      // which Math.max() in suffixOf() takes care of.
      const clashes = segments.some(
        (other, otherIndex) => otherIndex !== index && suffixOf(other, take) === candidate,
      );
      if (!clashes) {
        labels[entry] = candidate;
        return;
      }
    }
    labels[entry] = own.join("/");
  });

  return labels;
}

