// d14_buffers / ex1 - reference solution (author only, used by `dojo verify`).

export function toBase64Url(buffer: Buffer): string {
  // Node has known this encoding name since v14: it strips the padding and
  // swaps the two unsafe characters for you.
  return buffer.toString("base64url");
}

export function fromBase64Url(text: string): Buffer {
  // Decoding with "base64url" also accepts the ordinary alphabet and tolerates
  // missing padding, which is exactly the liberal behaviour that is wanted.
  return Buffer.from(text, "base64url");
}

// d14_buffers / ex2 - reference solution (author only, used by `dojo verify`).

export interface VarInt {
  value: number;
  bytesRead: number;
}

export function writeVarInt(value: number): Buffer {
  const bytes: number[] = [];
  let rest = value;
  // do/while, not while: zero is one byte, and a loop with the test at the top
  // encodes it as nothing at all.
  do {
    const seven = rest % 128;
    rest = Math.floor(rest / 128);
    bytes.push(rest > 0 ? seven | 0x80 : seven);
  } while (rest > 0);
  return Buffer.from(bytes);
}

export function readVarInt(buffer: Buffer, offset: number): VarInt {
  let value = 0;
  // Multiply rather than shift: << is a 32-bit operator in JavaScript, so the
  // fifth group of seven bits would wrap round to nothing.
  let scale = 1;
  let cursor = offset;

  for (;;) {
    if (cursor >= buffer.length) {
      throw new Error(
        "readVarInt: truncated varint - the buffer ended before a byte with the top bit clear",
      );
    }
    const byte = buffer[cursor];
    cursor += 1;
    value += (byte & 0x7f) * scale;
    if ((byte & 0x80) === 0) break;
    scale *= 128;
  }

  return { value, bytesRead: cursor - offset };
}

// d14_buffers / ex3 - reference solution (author only, used by `dojo verify`).

export interface RecordHeader {
  flags: number;
  count: number;
  id: number;
  name: string;
}

const HEADER_BYTES = 19;
const MAGIC = "DOJO";

export function parseRecordHeader(buffer: Buffer): RecordHeader {
  // Length first: every read below is an offset, and an offset past the end is
  // an ERR_OUT_OF_RANGE that names a number instead of a problem.
  if (buffer.length < HEADER_BYTES) {
    throw new Error(
      `parseRecordHeader: a record header needs 19 bytes, got ${buffer.length}`,
    );
  }

  const magic = buffer.toString("ascii", 0, 4);
  if (magic !== MAGIC) {
    throw new Error(`parseRecordHeader: bad magic ${JSON.stringify(magic)}, expected "DOJO"`);
  }

  const name = buffer.toString("ascii", 11, 19);
  return {
    flags: buffer.readUInt8(4),
    count: buffer.readUInt32LE(5),
    id: buffer.readUInt16BE(9),
    // The field is fixed width; the padding is not part of the value.
    name: name.replace(/\0+$/, ""),
  };
}

// d14_buffers / ex4 - reference solution (author only, used by `dojo verify`).

export function splitBuffer(buffer: Buffer, delimiter: Buffer): Buffer[] {
  if (delimiter.length === 0) {
    throw new Error("splitBuffer: the delimiter must be at least one byte");
  }

  const pieces: Buffer[] = [];
  let start = 0;

  for (;;) {
    // Buffer#indexOf takes a Buffer and searches bytes, not characters.
    const at = buffer.indexOf(delimiter, start);
    if (at === -1) break;
    pieces.push(buffer.subarray(start, at));
    start = at + delimiter.length;
  }

  // Whatever is left after the last delimiter is the final piece - including
  // the empty one when the buffer ends on a delimiter.
  pieces.push(buffer.subarray(start));
  return pieces;
}

// d14_buffers / ex5 - reference solution (author only, used by `dojo verify`).
import { StringDecoder } from "node:string_decoder";

export interface Utf8Decoder {
  push(chunk: Buffer): string;
  end(): string;
}

export function createUtf8Decoder(): Utf8Decoder {
  // StringDecoder holds an incomplete multi-byte sequence internally and emits
  // it once the rest of it arrives. This is what a Readable in string mode is
  // using under the hood.
  const decoder = new StringDecoder("utf8");

  return {
    push: (chunk: Buffer) => decoder.write(chunk),
    // end() flushes what is held: a sequence that can never be completed comes
    // out as the replacement character rather than disappearing.
    end: () => decoder.end(),
  };
}

// d14_buffers / ex6 - reference solution (author only, used by `dojo verify`).

export interface DataUrl {
  mediaType: string;
  data: Buffer;
}

const DEFAULT_MEDIA_TYPE = "text/plain;charset=US-ASCII";
const BASE64_MARKER = ";base64";

export function parseDataUrl(text: string): DataUrl | null {
  if (!text.startsWith("data:")) return null;

  // The first comma is the boundary; commas after it belong to the payload.
  const comma = text.indexOf(",");
  if (comma === -1) return null;

  const meta = text.slice("data:".length, comma);
  const isBase64 = meta.endsWith(BASE64_MARKER);
  const declared = isBase64 ? meta.slice(0, -BASE64_MARKER.length) : meta;
  const payload = text.slice(comma + 1);

  return {
    mediaType: declared === "" ? DEFAULT_MEDIA_TYPE : declared,
    data: isBase64
      ? Buffer.from(payload, "base64")
      : // Percent-escapes are BYTES; decodeURIComponent turns them back into
        // the characters they encoded, and utf8 re-encodes them unchanged.
        Buffer.from(decodeURIComponent(payload), "utf8"),
  };
}

// d14_buffers / ex7 - reference solution (author only, used by `dojo verify`).

export interface FrameReader {
  push(chunk: Buffer): Buffer[];
  pending(): number;
}

const HEADER_BYTES = 4;

export function createFrameReader(): FrameReader {
  //: bytes that arrived but did not add up to a whole frame yet
  let held = Buffer.alloc(0);

  return {
    push(chunk: Buffer): Buffer[] {
      held = held.length === 0 ? Buffer.from(chunk) : Buffer.concat([held, chunk]);

      const frames: Buffer[] = [];
      let offset = 0;

      // A loop, not an if: one chunk can complete any number of frames.
      for (;;) {
        // Is the length prefix even here yet?
        if (held.length - offset < HEADER_BYTES) break;
        const length = held.readUInt32BE(offset);
        // ...and is the whole payload behind it?
        if (held.length - offset - HEADER_BYTES < length) break;

        // Copy: the frame outlives the buffer it was cut from.
        frames.push(Buffer.from(held.subarray(offset + HEADER_BYTES, offset + HEADER_BYTES + length)));
        offset += HEADER_BYTES + length;
      }

      if (offset > 0) held = Buffer.from(held.subarray(offset));
      return frames;
    },

    pending: () => held.length,
  };
}

// d14_buffers / ex8 - reference solution (author only, used by `dojo verify`).

export interface HeadAndBody {
  headers: Record<string, string>;
  body: Buffer;
}

const SEPARATOR = Buffer.from("\r\n\r\n", "ascii");

export function splitHeadersAndBody(buffer: Buffer): HeadAndBody {
  // Find the boundary in BYTES. Decoding first is what corrupts the body.
  const at = buffer.indexOf(SEPARATOR);
  if (at === -1) {
    throw new Error(
      "splitHeadersAndBody: no blank line - the header block is not terminated by CRLF CRLF",
    );
  }

  const head = buffer.toString("utf8", 0, at);
  const body = Buffer.from(buffer.subarray(at + SEPARATOR.length));

  const headers: Record<string, string> = {};
  for (const line of head.split("\r\n")) {
    if (line === "") continue;

    // The FIRST colon only: values contain colons all the time.
    const colon = line.indexOf(":");
    if (colon === -1) {
      throw new Error(`splitHeadersAndBody: header line without a colon: ${line}`);
    }

    const name = line.slice(0, colon).trim().toLowerCase();
    const value = line.slice(colon + 1).trim();
    headers[name] = headers[name] === undefined ? value : `${headers[name]}, ${value}`;
  }

  return { headers, body };
}

