// d15_readable_writable / ex1 - reference solution (author only, used by `dojo verify`).
import { Readable } from "node:stream";

export function createRangeStream(from: number, to: number, step: number): Readable {
  let current = from;
  return new Readable({
    objectMode: true,
    read() {
      // Past the end - including immediately, for an empty range - is the one
      // signal a Readable owes its consumer: push(null) or they wait forever.
      if (current > to) {
        this.push(null);
        return;
      }
      const value = current;
      current += step;
      this.push(value);
    },
  });
}

// d15_readable_writable / ex2 - reference solution (author only, used by `dojo verify`).
import { Readable } from "node:stream";

export async function toArray<T>(readable: Readable): Promise<T[]> {
  const items: T[] = [];
  // for-await subscribes, unsubscribes, and turns an error event into a
  // rejection - the three things the hand-rolled data/end/error version has to
  // remember to do itself.
  for await (const item of readable) {
    items.push(item as T);
  }
  return items;
}

// d15_readable_writable / ex3 - reference solution (author only, used by `dojo verify`).
import { Writable } from "node:stream";

export interface BoundedSink {
  writable: Writable;
  bytes(): number;
}

export function createBoundedSink(limit: number): BoundedSink {
  let accepted = 0;

  const writable = new Writable({
    write(chunk: Buffer, _encoding, callback) {
      // Refuse BEFORE counting: the chunk that breaks the budget is never
      // accepted, so bytes() reports what actually got in.
      if (accepted + chunk.length > limit) {
        callback(
          new Error(`createBoundedSink: refusing to accept more than ${limit} bytes`),
        );
        return;
      }
      accepted += chunk.length;
      callback();
    },
  });

  return { writable, bytes: () => accepted };
}

// d15_readable_writable / ex4 - reference solution (author only, used by `dojo verify`).
import { Readable } from "node:stream";

export async function takeFrom<T>(readable: Readable, n: number): Promise<T[]> {
  const items: T[] = [];
  if (n <= 0) {
    readable.destroy();
    return items;
  }
  for await (const item of readable) {
    items.push(item as T);
    // Breaking out of a for-await calls the iterator's return(), which
    // destroys the underlying stream - that is the shutdown the gate checks.
    if (items.length >= n) break;
  }
  return items;
}

// d15_readable_writable / ex5 - reference solution (author only, used by `dojo verify`).
import { Readable } from "node:stream";

export function concatStreams(sources: Readable[]): Readable {
  // The generator IS the laziness: the for-await over source 2 does not exist
  // until the loop over source 1 has finished, so nothing subscribes to it,
  // resumes it, or holds it open early.
  async function* all(): AsyncGenerator<unknown> {
    for (const source of sources) {
      yield* source;
    }
  }
  // A source that errors rejects the pending next(), the generator throws, and
  // Readable.from destroys the joined stream with that error.
  return Readable.from(all());
}

// d15_readable_writable / ex6 - reference solution (author only, used by `dojo verify`).
import { Readable } from "node:stream";

export interface Page<T> {
  items: T[];
  next: string | null;
}

export function createPagedSource<T>(
  fetchPage: (cursor: string | null) => Promise<Page<T>>,
): Readable {
  let cursor: string | null = null;
  let finished = false;
  let inFlight = false;

  return new Readable({
    objectMode: true,
    // A small buffer is what keeps this a stream: the default of 16 would
    // pull pages ahead of the consumer to fill it.
    highWaterMark: 1,
    read() {
      // read() can be called again before an async fetch lands - without this
      // guard the same cursor is fetched twice and pages arrive interleaved.
      if (finished || inFlight) return;
      inFlight = true;
      fetchPage(cursor).then(
        (page) => {
          inFlight = false;
          cursor = page.next;
          if (page.next === null) finished = true;
          for (const item of page.items) this.push(item);
          if (finished) this.push(null);
        },
        (error) => this.destroy(error as Error),
      );
    },
  });
}

// d15_readable_writable / ex7 - reference solution (author only, used by `dojo verify`).
import { Readable } from "node:stream";

export function mergeStreams(sources: Readable[]): Readable {
  const merged = new Readable({ objectMode: true, read() {} });

  let open = sources.length;
  if (open === 0) {
    merged.push(null);
    return merged;
  }

  let failed = false;
  for (const source of sources) {
    source.on("data", (item) => {
      merged.push(item);
    });
    source.on("end", () => {
      // One source ending is not the merge ending - count them down.
      open -= 1;
      if (open === 0 && !failed) merged.push(null);
    });
    source.on("error", (error) => {
      if (failed) return;
      failed = true;
      // The survivors would otherwise keep producing into a dead stream.
      for (const other of sources) {
        if (other !== source) other.destroy();
      }
      merged.destroy(error);
    });
  }

  return merged;
}

// d15_readable_writable / ex8 - reference solution (author only, used by `dojo verify`).
import { Duplex } from "node:stream";

export function createDuplexPair(): [Duplex, Duplex] {
  // Each side's write() pushes into the OTHER side's readable half - the
  // closures read `a` and `b` at call time, so the forward references are fine.
  const a: Duplex = new Duplex({
    read() {},
    write(chunk, _encoding, callback) {
      b.push(chunk);
      callback();
    },
    // end() on this side is push(null) on the other: that is how the far end
    // of a socket learns you have finished sending.
    final(callback) {
      b.push(null);
      callback();
    },
  });

  const b: Duplex = new Duplex({
    read() {},
    write(chunk, _encoding, callback) {
      a.push(chunk);
      callback();
    },
    final(callback) {
      a.push(null);
      callback();
    },
  });

  return [a, b];
}

