// d16_transform_pipeline / ex1 - reference solution (author only, used by `dojo verify`).
import { Transform } from "node:stream";

export function createMapStage<T, R>(fn: (item: T) => R): Transform {
  return new Transform({
    objectMode: true,
    transform(chunk: T, _encoding, callback) {
      try {
        // The two-argument callback is push-and-continue in one call.
        callback(null, fn(chunk));
      } catch (error) {
        // A throw here would be an uncaught exception on the next tick, not a
        // stream error - the callback is the only way out.
        callback(error as Error);
      }
    },
  });
}

// d16_transform_pipeline / ex2 - reference solution (author only, used by `dojo verify`).
import { Transform } from "node:stream";

export interface FilterStage extends Transform {
  kept(): number;
  dropped(): number;
}

export function createFilterStage<T>(predicate: (item: T) => boolean): FilterStage {
  let kept = 0;
  let dropped = 0;

  const stage = new Transform({
    objectMode: true,
    transform(chunk: T, _encoding, callback) {
      if (predicate(chunk)) {
        kept += 1;
        this.push(chunk);
      } else {
        dropped += 1;
      }
      // Called on BOTH paths: the callback means "done with this chunk", not
      // "here is an output". Forgetting it on the dropped path stalls forever.
      callback();
    },
  }) as FilterStage;

  stage.kept = () => kept;
  stage.dropped = () => dropped;
  return stage;
}

// d16_transform_pipeline / ex3 - reference solution (author only, used by `dojo verify`).
import { Transform } from "node:stream";

export function createBatchStage<T>(size: number): Transform {
  let batch: T[] = [];

  return new Transform({
    objectMode: true,
    transform(chunk: T, _encoding, callback) {
      batch.push(chunk);
      if (batch.length === size) {
        this.push(batch);
        // A fresh array, not batch.length = 0: the one just pushed is now
        // owned by whatever is downstream and must not be mutated.
        batch = [];
      }
      callback();
    },
    flush(callback) {
      // The remainder. The guard is what stops an exact multiple emitting [].
      if (batch.length > 0) this.push(batch);
      callback();
    },
  });
}

// d16_transform_pipeline / ex4 - reference solution (author only, used by `dojo verify`).
import { Transform } from "node:stream";

export function createExpandStage<T, R>(
  fn: (item: T) => R[] | AsyncIterable<R>,
): Transform {
  return new Transform({
    objectMode: true,
    async transform(chunk: T, _encoding, callback) {
      try {
        const produced = fn(chunk);
        if (Array.isArray(produced)) {
          for (const item of produced) this.push(item);
        } else {
          // Drained fully before the callback, so the next input cannot start
          // interleaving its own output with this one.
          for await (const item of produced) this.push(item);
        }
        callback();
      } catch (error) {
        callback(error as Error);
      }
    },
  });
}

// d16_transform_pipeline / ex5 - reference solution (author only, used by `dojo verify`).

export type AsyncStage<T, R> = (source: AsyncIterable<T>) => AsyncGenerator<R>;

export function asyncMapStage<T, R>(fn: (item: T) => Promise<R> | R): AsyncStage<T, R> {
  return async function* stage(source: AsyncIterable<T>): AsyncGenerator<R> {
    for await (const item of source) {
      // Awaiting inside the loop is what gives you both properties for free:
      // one at a time, and therefore in order. It is also what stops the loop
      // pulling anything else once fn rejects.
      yield await fn(item);
    }
  };
}

// d16_transform_pipeline / ex6 - reference solution (author only, used by `dojo verify`).
import { PassThrough, type Readable, type Writable } from "node:stream";
import { pipeline } from "node:stream/promises";

export async function tee(source: Readable, sinks: Writable[]): Promise<void> {
  // One branch per sink. Piping the source itself into two sinks would give
  // each of them roughly half the data: reading a stream consumes it.
  const branches = sinks.map(() => new PassThrough({ objectMode: true }));
  const runs = branches.map((branch, index) => pipeline(branch, sinks[index]));

  const pump = (async () => {
    for await (const chunk of source) {
      for (const branch of branches) branch.write(chunk);
    }
    for (const branch of branches) branch.end();
  })();

  const everything = [pump, ...runs];
  // The first failure is the one reported; the rest would otherwise land as
  // unhandled rejections the moment the teardown destroys their streams.
  for (const promise of everything) promise.catch(() => {});

  try {
    await Promise.all(everything);
  } catch (error) {
    source.destroy();
    for (const branch of branches) branch.destroy();
    for (const sink of sinks) sink.destroy();
    throw error;
  }
}

// d16_transform_pipeline / ex7 - reference solution (author only, used by `dojo verify`).
import { Transform } from "node:stream";

export function createOrderedParallelStage<T, R>(
  worker: (item: T) => Promise<R>,
  limit: number,
): Transform {
  //: started work, in input order. The head is the next thing that may be
  //: emitted, whatever order the workers actually finish in.
  const queue: Promise<R>[] = [];

  return new Transform({
    objectMode: true,
    transform(chunk: T, _encoding, callback) {
      const started = worker(chunk);
      // Handled below via the queue; this only stops the rejection being
      // "unhandled" in the window before its turn at the head comes round.
      started.catch(() => {});
      queue.push(started);

      if (queue.length < limit) {
        // Room for another: take the next chunk without waiting for anything.
        callback();
        return;
      }

      // At capacity. Retiring the HEAD is what frees the slot - not whichever
      // worker happens to finish first, because that would reorder the output.
      queue[0].then(
        (value) => {
          queue.shift();
          this.push(value);
          callback();
        },
        (error: unknown) => callback(error as Error),
      );
    },

    flush(callback) {
      const drain = async (): Promise<void> => {
        while (queue.length > 0) {
          const value = await queue[0];
          queue.shift();
          this.push(value);
        }
      };
      drain().then(
        () => callback(),
        (error: unknown) => callback(error as Error),
      );
    },
  });
}

// d16_transform_pipeline / ex8 - reference solution (author only, used by `dojo verify`).
import type { Readable, Writable } from "node:stream";
import { finished } from "node:stream/promises";

export async function partitionTo<T>(
  source: Readable,
  keyOf: (item: T) => string,
  openSink: (key: string) => Writable,
): Promise<Record<string, number>> {
  const sinks = new Map<string, Writable>();
  const counts: Record<string, number> = {};
  const runs: Promise<void>[] = [];
  let failure: unknown = null;

  const fail = (error: unknown): void => {
    if (failure === null) failure = error;
    source.destroy();
    // Destroyed, not ended: an ended sink claims to be a complete file.
    for (const sink of sinks.values()) sink.destroy();
  };

  try {
    for await (const item of source) {
      if (failure !== null) break;
      const key = keyOf(item as T);

      let sink = sinks.get(key);
      if (sink === undefined) {
        // Lazily, and once per key - openSink() is a file being created.
        sink = openSink(key);
        sinks.set(key, sink);
        const run = finished(sink);
        run.catch((error: unknown) => fail(error));
        runs.push(run);
      }

      sink.write(item);
      counts[key] = (counts[key] ?? 0) + 1;
    }
  } catch (error) {
    fail(error);
  }

  if (failure === null) {
    for (const sink of sinks.values()) sink.end();
  }

  // allSettled, because on the failure path several of these have rejected and
  // it is the first failure the caller wants, not whichever settled last.
  const settled = await Promise.allSettled(runs);
  if (failure !== null) throw failure;

  const rejected = settled.find((result) => result.status === "rejected");
  if (rejected !== undefined && rejected.status === "rejected") throw rejected.reason;

  return counts;
}

