// d18_http_raw / ex1 - reference solution (author only, used by `dojo verify`).
import type { IncomingMessage, ServerResponse } from "node:http";

export type Handler = (req: IncomingMessage, res: ServerResponse) => void;

const REPORT = { id: "r-1", title: "Quarterly report", total: 42 };

//: server preference order - the tie-break when the client has no opinion
const OFFERED = ["application/json", "text/plain"] as const;

interface Preference {
  type: string;
  quality: number;
}

function parseAccept(header: string | undefined): Preference[] {
  if (header === undefined || header.trim() === "") return [{ type: "*/*", quality: 1 }];

  return header.split(",").map((entry) => {
    const [type, ...parameters] = entry.trim().split(";");
    let quality = 1;
    for (const parameter of parameters) {
      const [key, value] = parameter.trim().split("=");
      if (key !== "q") continue;
      const parsed = Number(value);
      if (!Number.isNaN(parsed)) quality = parsed;
    }
    return { type: type.trim().toLowerCase(), quality };
  });
}

/** The best q the client gave this offer, or -1 if it never mentioned it. */
function qualityOf(offer: string, preferences: Preference[]): number {
  const [group] = offer.split("/");
  let best = -1;
  for (const preference of preferences) {
    const matches =
      preference.type === offer || preference.type === `${group}/*` || preference.type === "*/*";
    if (matches && preference.quality > best) best = preference.quality;
  }
  return best;
}

function sendJson(res: ServerResponse, status: number, body: unknown): void {
  const payload = JSON.stringify(body);
  res.writeHead(status, {
    "content-type": "application/json; charset=utf-8",
    "content-length": Buffer.byteLength(payload),
  });
  res.end(payload);
}

export function createHandler(): Handler {
  return (req, res) => {
    const url = new URL(req.url ?? "/", "http://localhost");
    // The response depends on a request header, so every cache in the world
    // needs to be told which one.
    res.setHeader("vary", "Accept");

    if (url.pathname !== "/report") {
      sendJson(res, 404, { error: "not_found" });
      return;
    }

    const preferences = parseAccept(req.headers.accept);
    let chosen: string | null = null;
    // Starting at 0 rather than -1 is what makes q=0 a refusal.
    let best = 0;
    for (const offer of OFFERED) {
      const quality = qualityOf(offer, preferences);
      // Strictly greater, so a tie leaves the earlier (preferred) offer in place.
      if (quality > best) {
        best = quality;
        chosen = offer;
      }
    }

    if (chosen === null) {
      sendJson(res, 406, { error: "not_acceptable", offered: [...OFFERED] });
      return;
    }

    if (chosen === "application/json") {
      sendJson(res, 200, REPORT);
      return;
    }

    const text = `${REPORT.id} ${REPORT.title} ${REPORT.total}`;
    res.writeHead(200, {
      "content-type": "text/plain; charset=utf-8",
      "content-length": Buffer.byteLength(text),
    });
    res.end(text);
  };
}

// d18_http_raw / ex2 - reference solution (author only, used by `dojo verify`).
import type { IncomingMessage, ServerResponse } from "node:http";

export type Handler = (req: IncomingMessage, res: ServerResponse) => void;

const STATUS = { service: "café-api", ready: true };

export function createHandler(): Handler {
  return (req, res) => {
    const url = new URL(req.url ?? "/", "http://localhost");
    const method = (req.method ?? "GET").toUpperCase();

    // Decide the whole response first. A HEAD differs from a GET at exactly one
    // point - the last line - and nowhere else.
    const found = url.pathname === "/status";
    const status = found ? 200 : 404;
    const payload = JSON.stringify(found ? STATUS : { error: "not_found" });

    res.writeHead(status, {
      "content-type": "application/json; charset=utf-8",
      // BYTES, not characters. The e-acute in this payload is two bytes, so
      // payload.length would understate the size by one and the client would
      // be told to expect less than is coming.
      "content-length": Buffer.byteLength(payload),
    });

    if (method === "HEAD") {
      res.end();
      return;
    }
    res.end(payload);
  };
}

// d18_http_raw / ex3 - reference solution (author only, used by `dojo verify`).
import type { IncomingMessage, ServerResponse } from "node:http";

export type Handler = (req: IncomingMessage, res: ServerResponse) => void;

function parseCookies(header: string | undefined): Record<string, string> {
  const cookies: Record<string, string> = {};
  if (header === undefined) return cookies;

  for (const entry of header.split(";")) {
    const pair = entry.trim();
    if (pair === "") continue;

    // The FIRST equals sign only: a base64 value ends in padding, and
    // split("=") would throw the padding away.
    const separator = pair.indexOf("=");
    if (separator === -1) continue;

    const name = pair.slice(0, separator).trim();
    if (name === "") continue;
    cookies[name] = decodeURIComponent(pair.slice(separator + 1).trim());
  }
  return cookies;
}

function sendJson(res: ServerResponse, status: number, body: unknown): void {
  const payload = JSON.stringify(body);
  res.writeHead(status, {
    "content-type": "application/json; charset=utf-8",
    "content-length": Buffer.byteLength(payload),
  });
  res.end(payload);
}

export function createHandler(): Handler {
  //: the id counter lives in the closure, so each handler owns its own
  let issued = 0;

  return (req, res) => {
    const url = new URL(req.url ?? "/", "http://localhost");
    const method = (req.method ?? "GET").toUpperCase();

    if (url.pathname !== "/session") {
      sendJson(res, 404, { error: "not_found" });
      return;
    }

    if (method === "POST") {
      issued += 1;
      // One setHeader call with an ARRAY. Calling it twice replaces the first
      // header rather than adding a second one.
      res.setHeader("set-cookie", [
        `sid=s-${issued}; Path=/; HttpOnly; Max-Age=3600`,
        "theme=dark; Path=/; Max-Age=86400",
      ]);
      sendJson(res, 201, { session: `s-${issued}` });
      return;
    }

    sendJson(res, 200, { cookies: parseCookies(req.headers.cookie) });
  };
}

// d18_http_raw / ex4 - reference solution (author only, used by `dojo verify`).
import type { IncomingMessage, ServerResponse } from "node:http";

export type Handler = (req: IncomingMessage, res: ServerResponse) => void;

const CLIP = Buffer.from("0123456789", "utf8");

type RangeResult =
  | { kind: "none" }
  | { kind: "unsatisfiable" }
  | { kind: "range"; start: number; end: number };

function parseRange(header: string | undefined, size: number): RangeResult {
  if (header === undefined) return { kind: "none" };

  const spec = header.trim();
  // A unit you do not understand is ignored, not refused.
  if (!spec.toLowerCase().startsWith("bytes=")) return { kind: "none" };

  const value = spec.slice("bytes=".length);
  // Multiple ranges would need a multipart body; serving the whole thing is a
  // legal answer and a much smaller one to write.
  if (value.includes(",")) return { kind: "none" };

  const [rawStart, rawEnd] = value.split("-");
  if (rawEnd === undefined) return { kind: "none" };

  if (rawStart.trim() === "") {
    // "-N" is a SUFFIX: the last N bytes, not the first N.
    const suffix = Number(rawEnd);
    if (!Number.isInteger(suffix) || suffix <= 0) return { kind: "unsatisfiable" };
    return { kind: "range", start: Math.max(0, size - suffix), end: size - 1 };
  }

  const start = Number(rawStart);
  if (!Number.isInteger(start) || start < 0 || start >= size) return { kind: "unsatisfiable" };

  if (rawEnd.trim() === "") return { kind: "range", start, end: size - 1 };

  const requested = Number(rawEnd);
  if (!Number.isInteger(requested) || requested < start) return { kind: "unsatisfiable" };
  // An end past the last byte is clamped: the client asked for more than there
  // is and gets what there is.
  return { kind: "range", start, end: Math.min(requested, size - 1) };
}

export function createHandler(): Handler {
  return (req, res) => {
    const url = new URL(req.url ?? "/", "http://localhost");
    if (url.pathname !== "/clip.txt") {
      const payload = JSON.stringify({ error: "not_found" });
      res.writeHead(404, {
        "content-type": "application/json; charset=utf-8",
        "content-length": Buffer.byteLength(payload),
      });
      res.end(payload);
      return;
    }

    const size = CLIP.length;
    const range = parseRange(req.headers.range, size);

    if (range.kind === "unsatisfiable") {
      res.writeHead(416, {
        "content-range": `bytes */${size}`,
        "accept-ranges": "bytes",
      });
      res.end();
      return;
    }

    if (range.kind === "none") {
      res.writeHead(200, {
        "content-type": "text/plain; charset=utf-8",
        "content-length": size,
        "accept-ranges": "bytes",
      });
      res.end(CLIP);
      return;
    }

    const slice = CLIP.subarray(range.start, range.end + 1);
    res.writeHead(206, {
      "content-type": "text/plain; charset=utf-8",
      "content-length": slice.length,
      "accept-ranges": "bytes",
      // Both ends are INCLUSIVE, and the total is the whole resource.
      "content-range": `bytes ${range.start}-${range.end}/${size}`,
    });
    res.end(slice);
  };
}

// d18_http_raw / ex5 - reference solution (author only, used by `dojo verify`).
import type { IncomingMessage, ServerResponse } from "node:http";

export type Handler = (req: IncomingMessage, res: ServerResponse) => void;

const CANONICAL = "/reports/quarterly";

function sendJson(res: ServerResponse, status: number, body: unknown): void {
  const payload = JSON.stringify(body);
  res.writeHead(status, {
    "content-type": "application/json; charset=utf-8",
    "content-length": Buffer.byteLength(payload),
  });
  res.end(payload);
}

export function createHandler(): Handler {
  return (req, res) => {
    const url = new URL(req.url ?? "/", "http://localhost");

    /** The canonical location, carrying this request's query string. */
    const to = (): string => {
      // Built with URL rather than by concatenation, so a target that already
      // had a query, or a stray slash, cannot produce a broken Location.
      const target = new URL(CANONICAL, "http://localhost");
      target.search = url.search;
      return `${target.pathname}${target.search}`;
    };

    const redirect = (status: number): void => {
      res.writeHead(status, { location: to(), "content-length": 0 });
      res.end();
    };

    switch (url.pathname) {
      case "/old-report":
        // Permanent: caches and browsers may remember this forever.
        redirect(301);
        return;
      case `${CANONICAL}/`:
        // Permanent AND method-preserving, which 301 does not promise.
        redirect(308);
        return;
      case "/latest":
        // A pointer that will mean something else next quarter, so temporary.
        redirect(302);
        return;
      case CANONICAL:
        sendJson(res, 200, { id: "quarterly", year: url.searchParams.get("year") });
        return;
      default:
        sendJson(res, 404, { error: "not_found" });
    }
  };
}

// d18_http_raw / ex6 - reference solution (author only, used by `dojo verify`).
import type { IncomingMessage, ServerResponse } from "node:http";

export type Handler = (req: IncomingMessage, res: ServerResponse) => void;

async function readBody(req: IncomingMessage): Promise<string> {
  const chunks: Buffer[] = [];
  for await (const chunk of req) chunks.push(chunk as Buffer);
  return Buffer.concat(chunks).toString("utf8");
}

function sendJson(res: ServerResponse, status: number, body: unknown, etag?: string): void {
  const payload = JSON.stringify(body);
  const headers: Record<string, string | number> = {
    "content-type": "application/json; charset=utf-8",
    "content-length": Buffer.byteLength(payload),
  };
  if (etag !== undefined) headers.etag = etag;
  res.writeHead(status, headers);
  res.end(payload);
}

export function createHandler(): Handler {
  let config = { id: "cfg-1", threshold: 10 };
  let version = 1;
  //: an entity tag is a QUOTED string in the message - the quotes are syntax
  const etag = (): string => `"v${version}"`;

  return (req, res) => {
    void (async () => {
      const url = new URL(req.url ?? "/", "http://localhost");
      const method = (req.method ?? "GET").toUpperCase();

      if (url.pathname !== "/config") {
        sendJson(res, 404, { error: "not_found" });
        return;
      }

      if (method === "GET") {
        sendJson(res, 200, config, etag());
        return;
      }

      if (method !== "PUT") {
        sendJson(res, 405, { error: "method_not_allowed" });
        return;
      }

      // Drain the body first: answering without reading it leaves bytes in the
      // socket that the next response has to step over.
      const raw = await readBody(req);
      const ifMatch = req.headers["if-match"];

      if (ifMatch === undefined) {
        // Not "forgive it and write anyway". The client has to read first.
        sendJson(res, 428, { error: "precondition_required" });
        return;
      }
      if (ifMatch.trim() !== "*" && ifMatch.trim() !== etag()) {
        sendJson(res, 412, { error: "precondition_failed" });
        return;
      }

      let parsed: { threshold?: unknown };
      try {
        parsed = JSON.parse(raw) as { threshold?: unknown };
      } catch {
        sendJson(res, 400, { error: "invalid_json" });
        return;
      }
      if (typeof parsed.threshold !== "number") {
        sendJson(res, 400, { error: "invalid_body" });
        return;
      }

      config = { ...config, threshold: parsed.threshold };
      version += 1;
      sendJson(res, 200, config, etag());
    })();
  };
}

// d18_http_raw / ex7 - reference solution (author only, used by `dojo verify`).
import { readFile, stat } from "node:fs/promises";
import type { IncomingMessage, ServerResponse } from "node:http";
import path from "node:path";

export type Handler = (req: IncomingMessage, res: ServerResponse) => void;

const CONTENT_TYPES: Record<string, string> = {
  ".html": "text/html; charset=utf-8",
  ".txt": "text/plain; charset=utf-8",
  ".json": "application/json; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".svg": "image/svg+xml",
  ".png": "image/png",
};

function sendJson(res: ServerResponse, status: number, body: unknown): void {
  const payload = JSON.stringify(body);
  res.writeHead(status, {
    "content-type": "application/json; charset=utf-8",
    "content-length": Buffer.byteLength(payload),
  });
  res.end(payload);
}

export function createStaticServer(root: string): Handler {
  const base = path.resolve(root);

  return (req, res) => {
    void (async () => {
      const method = (req.method ?? "GET").toUpperCase();
      if (method !== "GET" && method !== "HEAD") {
        res.setHeader("allow", "GET, HEAD");
        sendJson(res, 405, { error: "method_not_allowed" });
        return;
      }

      const url = new URL(req.url ?? "/", "http://localhost");
      let decoded: string;
      try {
        // The pathname is still percent-encoded, and %2f is how an attacker
        // smuggles a separator past a client that would have normalised "/../".
        decoded = decodeURIComponent(url.pathname);
      } catch {
        sendJson(res, 400, { error: "bad_request" });
        return;
      }

      // Strip the leading slash so the path is resolved UNDER the root rather
      // than as an absolute path that replaces it.
      const relative = decoded.replace(/^\/+/, "");
      const target = path.resolve(base, relative);

      // Resolve first, judge second - and judge by segment, so a directory
      // honestly called "..config" is not mistaken for an escape.
      const fromBase = path.relative(base, target);
      const inside =
        fromBase !== "" && !path.isAbsolute(fromBase) && fromBase.split(path.sep)[0] !== "..";
      if (!inside) {
        sendJson(res, 403, { error: "forbidden" });
        return;
      }

      try {
        const info = await stat(target);
        // A directory is not a file, and inventing a listing leaks filenames.
        if (!info.isFile()) {
          sendJson(res, 404, { error: "not_found" });
          return;
        }

        const contents = await readFile(target);
        res.writeHead(200, {
          "content-type":
            CONTENT_TYPES[path.extname(target).toLowerCase()] ?? "application/octet-stream",
          "content-length": contents.length,
        });
        if (method === "HEAD") res.end();
        else res.end(contents);
      } catch {
        sendJson(res, 404, { error: "not_found" });
      }
    })();
  };
}

// d18_http_raw / ex8 - reference solution (author only, used by `dojo verify`).
import type { IncomingMessage, ServerResponse } from "node:http";

export type Handler = (req: IncomingMessage, res: ServerResponse) => void;

export interface SseEvent {
  id?: string;
  event?: string;
  data: string;
}

/** One event, as the bytes that go on the wire. */
function frame(event: SseEvent): string {
  const lines: string[] = [];
  if (event.id !== undefined) lines.push(`id: ${event.id}`);
  if (event.event !== undefined) lines.push(`event: ${event.event}`);
  // A newline inside the payload is not allowed to be a newline on the wire:
  // it would end the event early. Each line gets its own data: field.
  for (const line of event.data.split("\n")) lines.push(`data: ${line}`);
  // The trailing blank line is what dispatches the event.
  return `${lines.join("\n")}\n\n`;
}

export function createEventStream(source: AsyncIterable<SseEvent>): Handler {
  return (req, res) => {
    const url = new URL(req.url ?? "/", "http://localhost");
    if (url.pathname !== "/events") {
      const payload = JSON.stringify({ error: "not_found" });
      res.writeHead(404, {
        "content-type": "application/json; charset=utf-8",
        "content-length": Buffer.byteLength(payload),
      });
      res.end(payload);
      return;
    }

    // No content-length: the length is not knowable, so the response is
    // chunked and every write goes out as its own chunk.
    res.writeHead(200, {
      "content-type": "text/event-stream",
      "cache-control": "no-cache",
    });

    void (async () => {
      try {
        for await (const event of source) res.write(frame(event));
      } catch (error) {
        // The headers went out with the first event, so a 500 is no longer
        // available. Say so in the stream instead.
        const message = error instanceof Error ? error.message : String(error);
        res.write(frame({ event: "error", data: message }));
      } finally {
        // Always end: a client left hanging reconnects and fails again.
        res.end();
      }
    })();
  };
}

lessons.fullReadme:
# d19 — HTTP routing

Eight problems on dispatch, drawn from lesson **08_http_core** — the half of it
that decides *which* code answers a request. That lesson's challenge built a
router that handled `:params`, 404 and 405; this set takes the pieces apart and
then rebuilds a harder one. Problem 7 is deliberately the interview version of
that challenge: routes tried in specificity order rather than registration
order, async handlers whose rejections become 500s, and `OPTIONS` and `HEAD`
answered by the router itself.

Six of the eight are pure functions with no server at all, which is the point —
a router is string handling wearing a network costume. Problems 6 and 7 are
graded with supertest against a request listener, so nothing binds a port. No
express anywhere: `node:http` and `URL` only.

## Problem 1 — a request line, taken apart

Edit `ex1/solution.ts`. `splitRoute(url)` returns `{ segments, query }`.
Segments are percent-decoded with empty ones dropped, so leading, trailing and
doubled slashes all mean nothing. `query` maps each key to its value, or to an
**array** when the key repeats.

```
uv run dojo test node d19_http_routing ex1
```

## Problem 2 — does this pattern describe this path

Edit `ex2/solution.ts`. `matchPattern(pattern, pathname)` returns the bound
parameters or `null`. `:name` takes exactly one segment, `:name?` may be absent
(and then is not in the result at all), and a trailing `*name` takes every
remaining segment joined with `/`, including none. Parameters come out decoded.

```
uv run dojo test node d19_http_routing ex2
```

## Problem 3 — the order a router has to try things in

Edit `ex3/solution.ts`. `rankPatterns(patterns)` returns them sorted most
specific first: a literal beats a `:param`, a `:param` beats having run out of
segments, and having run out beats a `*wildcard`. Equally specific patterns keep
their original order, and the array you were given is not modified.

```
uv run dojo test node d19_http_routing ex3
```

## Problem 4 — the router, run backwards

Edit `ex4/solution.ts`. `buildLink(pattern, params, query)` fills the pattern
in: values percent-encoded, an absent optional segment left off entirely, a
wildcard keeping its separators, and the query sorted by key with arrays
becoming repeated keys. A missing required parameter throws an error naming it.

```
uv run dojo test node d19_http_routing ex4
```

## Problem 5 — one URL per resource

Edit `ex5/solution.ts`. `canonicalPath(url)` returns `{ path, changed }`:
duplicate separators collapsed, `.` and `..` resolved without ever climbing
above the root, and a trailing slash dropped except on `/`. The query string is
not part of the answer and never counts as a change — and nothing is decoded.

```
uv run dojo test node d19_http_routing ex5
```

## Problem 6 — mounting, without a framework to do it

Edit `ex6/solution.ts`. `mountAt(prefix, handler)` gives `handler` the path with
the prefix removed (`/api/v1/orders` becomes `/orders`, and the mount point
itself becomes `/`), leaves the untouched URL on the request as `originalUrl`,
restores `req.url` afterwards, and 404s anything outside the prefix — including
`/api/v1extra`, which is not under `/api/v1`.

```
uv run dojo test node d19_http_routing ex6
```

## Problem 7 — the router, assembled

Edit `ex7/solution.ts`. `createRouter({ onError })` exposes `get/post/put/delete`
and a `handler`. Routes are tried **most specific first**, so `/orders/new` wins
over a `/orders/:id` registered before it. Handlers may be async, and a rejection
becomes a 500 plus a call to `onError`. `HEAD` falls back to the `GET` handler;
`OPTIONS` is answered with 204 and `Allow`; an unknown path is 404 and a known
path with the wrong method is 405 with the same `Allow`.

```
uv run dojo test node d19_http_routing ex7
```

## Problem 8 — routing as a tree

Edit `ex8/solution.ts`. `resolveRouteTree(tree, method, pathname)` walks nodes
with `children`, a `param` child and an `index` list of methods, returning
`{ chain, params }` or `null`. A static child is tried before the param child —
and when the static branch fails further down, the walk has to back out and try
the param branch instead.

```
uv run dojo test node d19_http_routing ex8
```

## The gate

This is the entire gate, `gate.test.ts`:

```ts
// Gate for node/d19_http_routing. Quoted verbatim in README.md.
//
// Six of these eight problems are pure functions over strings, so they are
// exact and instant. The two that need a server are handed to supertest as a
// request listener - it picks the port, so nothing here can collide with
// anything else running.
import type { IncomingMessage, ServerResponse } from "node:http";
import request from "supertest";
import { describe, expect, test } from "vitest";

import { splitRoute } from "./ex1/solution";
import { matchPattern } from "./ex2/solution";
import { rankPatterns } from "./ex3/solution";
import { buildLink } from "./ex4/solution";
import { canonicalPath } from "./ex5/solution";
import { mountAt } from "./ex6/solution";
import { createRouter } from "./ex7/solution";
import { resolveRouteTree, type RouteNode } from "./ex8/solution";

/** What a mounted handler is allowed to have been told about its request. */
type Mounted = IncomingMessage & { originalUrl?: string };

function json(res: ServerResponse, status: number, body: unknown): void {
  const payload = JSON.stringify(body);
  res.writeHead(status, {
    "content-type": "application/json; charset=utf-8",
    "content-length": Buffer.byteLength(payload),
  });
  res.end(payload);
}

describe("d19_http_routing", () => {
  test("ex1 - splitRoute() takes a request line apart", () => {
    expect(
      splitRoute("/orders/42?status=paid"),
      "the path becomes segments and the query becomes an object - two " +
        "different jobs that URL does for you if you let it",
    ).toEqual({ segments: ["orders", "42"], query: { status: "paid" } });

    expect(
      splitRoute("/orders/42/"),
      "a trailing slash is not an empty last segment. Treating it as one is " +
        "why /orders/42/ 404s on a route that /orders/42 matches",
    ).toEqual({ segments: ["orders", "42"], query: {} });

    expect(
      splitRoute("/orders//42"),
      "and neither is a doubled separator",
    ).toEqual({ segments: ["orders", "42"], query: {} });

    expect(splitRoute("/"), "the root has no segments at all").toEqual({
      segments: [],
      query: {},
    });

    expect(
      splitRoute("/orders/order%2042"),
      "segments arrive percent-encoded and have to be decoded, or every id " +
        "with a space in it misses its route",
    ).toEqual({ segments: ["orders", "order 42"], query: {} });

    expect(
      splitRoute("/files/a%2fb"),
      "...and %2f decodes to a slash INSIDE one segment. Splitting the decoded " +
        "path instead of decoding the split parts turns one segment into two, " +
        "which is the bug that lets a filename climb a directory",
    ).toEqual({ segments: ["files", "a/b"], query: {} });

    expect(
      splitRoute("/search?tag=core&tag=io&q=streams"),
      "a repeated key is not a mistake to be silently deduplicated - it is an " +
        "array, and keeping only the last one loses data the client sent on " +
        "purpose",
    ).toEqual({ segments: ["search"], query: { tag: ["core", "io"], q: "streams" } });

    expect(
      splitRoute("/search?tag=a&tag=b&tag=c"),
      "three of them is an array of three, not a nested pair",
    ).toEqual({ segments: ["search"], query: { tag: ["a", "b", "c"] } });

    expect(
      splitRoute("/search?q=event%20loop&empty="),
      "query values are decoded too, and a key with no value is the empty " +
        "string rather than missing",
    ).toEqual({ segments: ["search"], query: { q: "event loop", empty: "" } });
  });

  test("ex2 - matchPattern() answers with the parameters or with nothing", () => {
    expect(
      matchPattern("/orders/:id", "/orders/42"),
      "a param segment matches one segment and binds its value",
    ).toEqual({ id: "42" });

    expect(
      matchPattern("/health", "/health"),
      "a pattern with no params still matches, with nothing to report",
    ).toEqual({});

    expect(
      matchPattern("/orders/:id", "/orders/42/lines"),
      "one param is one segment - a longer path is a different route",
    ).toBeNull();

    expect(matchPattern("/orders/:id", "/orders"), "and so is a shorter one").toBeNull();

    expect(matchPattern("/orders/:id", "/customers/42"), "the literal has to match").toBeNull();

    expect(
      matchPattern("/orders/:id/lines/:line", "/orders/7/lines/3"),
      "two params in one pattern, each bound to its own segment",
    ).toEqual({ id: "7", line: "3" });

    expect(
      matchPattern("/orders/:id?", "/orders"),
      "an optional segment may be absent, and then its name is simply not in " +
        "the answer - not present and undefined, which is a different thing to " +
        "every caller that uses in or hasOwnProperty",
    ).toEqual({});

    expect(
      matchPattern("/orders/:id?", "/orders/42"),
      "...and present when it is there",
    ).toEqual({ id: "42" });

    expect(
      matchPattern("/files/*rest", "/files/a/b/c.txt"),
      "a trailing star takes everything left, joined back together - which is " +
        "the whole reason it exists, because a param cannot cross a separator",
    ).toEqual({ rest: "a/b/c.txt" });

    expect(
      matchPattern("/files/*rest", "/files"),
      "and it is allowed to take nothing at all",
    ).toEqual({ rest: "" });

    expect(
      matchPattern("/orders/:id", "/orders/order%2042"),
      "params come out decoded, because a route parameter is a value and not a " +
        "piece of URL syntax",
    ).toEqual({ id: "order 42" });

    expect(
      matchPattern("/orders/:id", "/orders/42/"),
      "a trailing slash does not change which route this is",
    ).toEqual({ id: "42" });
  });

  test("ex3 - rankPatterns() puts the most specific route first", () => {
    expect(
      rankPatterns(["/orders/*rest", "/orders/:id", "/orders/new", "/orders", "/orders/:id/lines"]),
      "the order a router has to try these in. A literal beats a param, a " +
        "param beats nothing, and nothing beats a wildcard - so /orders/new is " +
        "reachable even though /orders/:id would also match it",
    ).toEqual(["/orders/new", "/orders/:id/lines", "/orders/:id", "/orders", "/orders/*rest"]);

    expect(
      rankPatterns(["/*all", "/health"]),
      "a catch-all is always the last thing you try, whatever order it was " +
        "registered in",
    ).toEqual(["/health", "/*all"]);

    expect(
      rankPatterns(["/a/:x", "/a/:y"]),
      "two patterns of equal specificity keep the order they arrived in. A " +
        "comparator that returns a nonzero value for equal inputs makes your " +
        "routing table depend on the sort implementation",
    ).toEqual(["/a/:x", "/a/:y"]);

    const original = ["/b", "/a/:x"];
    const ranked = rankPatterns(original);
    expect(ranked, "a longer pattern outranks a shorter one that ties on its prefix").toEqual([
      "/a/:x",
      "/b",
    ]);
    expect(
      original,
      "and the caller's array is left alone. Array.sort() sorts IN PLACE, so " +
        "the version of this that reorders the routing table it was asked to " +
        "read is a one-character mistake",
    ).toEqual(["/b", "/a/:x"]);

    expect(rankPatterns([]), "nothing in, nothing out").toEqual([]);
  });

  test("ex4 - buildLink() runs the router backwards", () => {
    expect(
      buildLink("/orders/:id", { id: "42" }),
      "the pattern and the values give you the URL, so the pattern stays the " +
        "single place a route is written down",
    ).toBe("/orders/42");

    expect(
      buildLink("/orders/:id", { id: "order 42" }),
      "values are percent-encoded on the way in - a link is not a template " +
        "string, and a space in an id would otherwise end the URL",
    ).toBe("/orders/order%2042");

    expect(
      buildLink("/orders/:id/lines/:line?", { id: "7", line: "3" }),
      "an optional segment that has a value is just a segment",
    ).toBe("/orders/7/lines/3");

    expect(
      buildLink("/orders/:id/lines/:line?", { id: "7" }),
      "...and one that does not is left off entirely, rather than becoming an " +
        "empty segment or the string undefined",
    ).toBe("/orders/7/lines");

    expect(
      buildLink("/files/*rest", { rest: "a/b/c.txt" }),
      "a wildcard keeps its separators: they are structure, not content, so " +
        "each segment is encoded but the slashes between them survive",
    ).toBe("/files/a/b/c.txt");

    expect(
      buildLink("/orders", {}, { status: "paid", limit: "10" }),
      "the query is sorted by key, so the same link is the same string every " +
        "time - which is what makes it usable as a cache key",
    ).toBe("/orders?limit=10&status=paid");

    expect(
      buildLink("/orders", {}, { tag: ["core", "io"] }),
      "an array becomes a repeated key, in the order given",
    ).toBe("/orders?tag=core&tag=io");

    expect(
      buildLink("/orders", {}, { q: "event loop" }),
      "and query values are encoded too",
    ).toBe("/orders?q=event%20loop");

    expect(buildLink("/orders"), "no params, no query, no question mark").toBe("/orders");

    expect(
      () => buildLink("/orders/:id", {}),
      "a missing required parameter is a programming error, and the message " +
        "has to name the parameter - otherwise the stack trace says only that " +
        "some link somewhere is wrong",
    ).toThrow("id");
  });

  test("ex5 - canonicalPath() decides whether a URL needs redirecting", () => {
    expect(
      canonicalPath("/orders/42"),
      "a path that is already canonical is returned unchanged, and says so - " +
        "which is what stops the caller redirecting it to itself forever",
    ).toEqual({ path: "/orders/42", changed: false });

    expect(canonicalPath("/orders//42"), "a doubled separator is collapsed").toEqual({
      path: "/orders/42",
      changed: true,
    });

    expect(canonicalPath("/orders/./42"), "a dot segment means here, so it goes").toEqual({
      path: "/orders/42",
      changed: true,
    });

    expect(
      canonicalPath("/orders/lines/../42"),
      "and a double dot cancels the segment before it",
    ).toEqual({ path: "/orders/42", changed: true });

    expect(
      canonicalPath("/../../etc/passwd"),
      "climbing above the root is not an error and not an escape - there is " +
        "nothing above the root, so the extra levels are simply discarded",
    ).toEqual({ path: "/etc/passwd", changed: true });

    expect(canonicalPath("/orders/42/"), "a trailing slash is dropped").toEqual({
      path: "/orders/42",
      changed: true,
    });

    expect(
      canonicalPath("/"),
      "except on the root, which IS a single slash and is already canonical",
    ).toEqual({ path: "/", changed: false });

    expect(canonicalPath(""), "an empty path means the root").toEqual({
      path: "/",
      changed: true,
    });

    expect(
      canonicalPath("/orders/42?status=paid"),
      "the query is not part of the path, so it neither moves nor counts as a " +
        "change - the caller reattaches it when it builds the Location",
    ).toEqual({ path: "/orders/42", changed: false });

    expect(
      canonicalPath("/orders/42/?status=paid"),
      "...and a path that does need fixing still reports only the path",
    ).toEqual({ path: "/orders/42", changed: true });

    expect(
      canonicalPath("/a/..%2fb"),
      "%2f is NOT a separator here, and decoding before you normalise is " +
        "exactly how the traversal you just removed gets put back",
    ).toEqual({ path: "/a/..%2fb", changed: false });
  });

  test("ex6 - mountAt() lends a handler a shorter world", async () => {
    const seen: { url?: string; originalUrl?: string }[] = [];
    const inner = (req: IncomingMessage, res: ServerResponse): void => {
      seen.push({ url: req.url, originalUrl: (req as Mounted).originalUrl });
      json(res, 200, { url: req.url });
    };

    const mounted = mountAt("/api/v1", inner);
    const restored: (string | undefined)[] = [];
    // Wraps the mount so the gate can see req.url AFTER the inner handler has
    // run - the rewrite is supposed to be a loan, not a change.
    const observer = (req: IncomingMessage, res: ServerResponse): void => {
      mounted(req, res);
      restored.push(req.url);
    };

    const listed = await request(observer).get("/api/v1/orders");
    expect(listed.status, "a request under the prefix reaches the handler").toBe(200);
    expect(
      listed.body.url,
      "which sees the path WITHOUT the prefix - that is the whole point of " +
        "mounting: the inner routes are written as if they were at the root",
    ).toBe("/orders");
    expect(
      seen[0].originalUrl,
      "and the untouched URL is still available, because a log line or an " +
        "error page needs the address the client actually asked for",
    ).toBe("/api/v1/orders");
    expect(
      restored[0],
      "afterwards req.url is put back. Leaving it rewritten breaks every " +
        "middleware registered after the mount, and the symptom appears " +
        "somewhere else entirely",
    ).toBe("/api/v1/orders");

    const query = await request(observer).get("/api/v1/orders?limit=2");
    expect(
      query.body.url,
      "the query string belongs to the inner handler too - it is the PREFIX " +
        "that is stripped, not everything up to the question mark",
    ).toBe("/orders?limit=2");

    const exact = await request(observer).get("/api/v1");
    expect(
      exact.body.url,
      "a request for the mount point itself leaves nothing behind, and nothing " +
        "is the root - an empty string is not a valid path",
    ).toBe("/");

    const slashed = await request(observer).get("/api/v1/");
    expect(slashed.body.url, "and the same with the slash spelled out").toBe("/");

    const before = seen.length;
    const outside = await request(observer).get("/orders");
    expect(outside.status, "a request outside the prefix is a 404").toBe(404);
    expect(outside.body, "in JSON, like everything else this app says").toEqual({
      error: "not_found",
    });
    expect(
      seen.length,
      "and the inner handler is never called - if it were, it would answer " +
        "/orders from the wrong mount",
    ).toBe(before);

    const lookalike = await request(observer).get("/api/v1extra");
    expect(
      lookalike.status,
      "the prefix has to end on a segment boundary. A startsWith test matches " +
        "/api/v1extra and hands the inner handler the path extra",
    ).toBe(404);

    const nestedSeen: string[] = [];
    const leaf = (req: IncomingMessage, res: ServerResponse): void => {
      nestedSeen.push(req.url ?? "");
      json(res, 200, { url: req.url, original: (req as Mounted).originalUrl });
    };
    const nested = await request(mountAt("/api", mountAt("/v1", leaf))).get("/api/v1/orders");
    expect(nestedSeen[0], "mounts nest, each one taking its own prefix off").toBe("/orders");
    expect(
      nested.body.original,
      "and the original is the outermost URL, not the half-stripped one the " +
        "second mount was handed",
    ).toBe("/api/v1/orders");
  });

  test("ex7 - createRouter() dispatches, refuses and explains", async () => {
    const errors: unknown[] = [];
    const router = createRouter({ onError: (error) => errors.push(error) });

    // Registered BEFORE the literal it would otherwise swallow.
    router.get("/orders/:id", (_req, res, params) => json(res, 200, { route: "show", params }));
    router.get("/orders/new", (_req, res) => json(res, 200, { route: "new" }));
    router.get("/orders", (_req, res) => json(res, 200, { route: "list" }));
    router.post("/orders", (_req, res) => json(res, 201, { route: "create" }));
    router.put("/orders/:id", (_req, res, params) => json(res, 200, { route: "replace", params }));
    router.get("/boom", async () => {
      throw new Error("upstream exploded");
    });

    const literal = await request(router.handler).get("/orders/new");
    expect(
      literal.body,
      "a literal segment wins over a param that would also match, whatever " +
        "order they were registered in. A router that tries routes in " +
        "registration order makes /orders/new unreachable and the fix look " +
        "like superstition",
    ).toEqual({ route: "new" });

    const show = await request(router.handler).get("/orders/42");
    expect(show.body, "and the param route still gets everything else").toEqual({
      route: "show",
      params: { id: "42" },
    });

    const list = await request(router.handler).get("/orders");
    expect(list.body, "the collection is its own route").toEqual({ route: "list" });

    const created = await request(router.handler).post("/orders");
    expect(created.status, "same path, different method, different handler").toBe(201);

    const head = await request(router.handler).head("/orders");
    expect(
      head.status,
      "HEAD is not a method you register: it falls back to the GET handler, " +
        "because a client asking how big something is should not need you to " +
        "have thought of it",
    ).toBe(200);
    expect(head.text, "and it sends no body").toBeFalsy();

    const options = await request(router.handler).options("/orders");
    expect(
      options.status,
      "OPTIONS is answered by the router itself - 204, because there is " +
        "nothing to say beyond the header",
    ).toBe(204);
    expect(
      options.headers.allow,
      "and the header is the point: every method registered for this path, " +
        "plus the two the router provides",
    ).toBe("GET, HEAD, OPTIONS, POST");

    const refused = await request(router.handler).delete("/orders");
    expect(
      refused.status,
      "the path exists and the method does not: that is 405, not 404. The " +
        "difference tells a client whether to fix its URL or its verb",
    ).toBe(405);
    expect(refused.headers.allow, "with the same list").toBe("GET, HEAD, OPTIONS, POST");

    const wrongOnParam = await request(router.handler).delete("/orders/42");
    expect(wrongOnParam.status, "405 works on a param route too").toBe(405);
    expect(
      wrongOnParam.headers.allow,
      "and reports what that path really supports, not what some other path does",
    ).toBe("GET, HEAD, OPTIONS, PUT");

    const nowhere = await request(router.handler).get("/nowhere");
    expect(nowhere.status, "a path with no routes at all is a 404").toBe(404);

    const optionsNowhere = await request(router.handler).options("/nowhere");
    expect(
      optionsNowhere.status,
      "including for OPTIONS - answering 204 with an empty Allow would claim " +
        "the route exists",
    ).toBe(404);

    const exploded = await request(router.handler).get("/boom");
    expect(
      exploded.status,
      "an async handler that rejects must become a 500. If the router does not " +
        "await it, the promise is unhandled, the client waits until it times " +
        "out, and the process prints a warning nobody reads",
    ).toBe(500);
    expect(exploded.body, "with a body that gives an attacker nothing").toEqual({
      error: "internal_error",
    });
    expect(
      (errors[0] as Error).message,
      "...while the real error goes to the reporter you were given, because a " +
        "500 nobody can diagnose is a 500 that happens again tomorrow",
    ).toBe("upstream exploded");
  });

  test("ex8 - resolveRouteTree() walks a nested table and backs out again", () => {
    const tree: RouteNode = {
      index: ["GET"],
      children: {
        health: { index: ["GET"] },
        orders: {
          index: ["GET", "POST"],
          children: { new: { index: ["GET"] } },
          param: {
            name: "id",
            node: {
              index: ["GET", "PUT"],
              children: {
                lines: {
                  index: ["GET"],
                  param: { name: "line", node: { index: ["GET"] } },
                },
              },
            },
          },
        },
      },
    };

    expect(
      resolveRouteTree(tree, "GET", "/"),
      "the root can handle a request itself, and the chain to it is empty",
    ).toEqual({ chain: [], params: {} });

    expect(resolveRouteTree(tree, "GET", "/health"), "a static child, one level down").toEqual({
      chain: ["health"],
      params: {},
    });

    expect(
      resolveRouteTree(tree, "POST", "/orders"),
      "a node can answer several methods",
    ).toEqual({ chain: ["orders"], params: {} });

    expect(
      resolveRouteTree(tree, "DELETE", "/orders"),
      "and only the ones it lists - a node that matches the path but not the " +
        "method has not matched",
    ).toBeNull();

    expect(
      resolveRouteTree(tree, "get", "/health"),
      "the method is compared case-insensitively, because it arrives from the " +
        "wire and you did not write it",
    ).toEqual({ chain: ["health"], params: {} });

    expect(
      resolveRouteTree(tree, "GET", "/orders/new"),
      "a static child is tried before the param child at the same level",
    ).toEqual({ chain: ["orders", "new"], params: {} });

    expect(
      resolveRouteTree(tree, "GET", "/orders/42"),
      "and the param child catches what the static ones do not, binding its name",
    ).toEqual({ chain: ["orders", ":id"], params: { id: "42" } });

    expect(
      resolveRouteTree(tree, "GET", "/orders/7/lines/3"),
      "params from different levels are merged into one object",
    ).toEqual({ chain: ["orders", ":id", "lines", ":line"], params: { id: "7", line: "3" } });

    expect(
      resolveRouteTree(tree, "GET", "/orders/new/lines"),
      "this is the whole exercise. The static child new matches, and then the " +
        "subtree underneath it has no lines - so the walk has to BACK OUT and " +
        "try the param child instead, which does. A greedy walk that commits " +
        "to the first matching child returns null here and the route looks " +
        "unregistered",
    ).toEqual({ chain: ["orders", ":id", "lines"], params: { id: "new" } });

    expect(
      resolveRouteTree(tree, "GET", "/orders/order%2042"),
      "a bound param is decoded, like every other route parameter",
    ).toEqual({ chain: ["orders", ":id"], params: { id: "order 42" } });

    expect(resolveRouteTree(tree, "GET", "/nothing"), "an unknown path is null").toBeNull();

    expect(
      resolveRouteTree(tree, "GET", "/orders/42/lines/3/extra"),
      "and so is a path that runs off the end of the tree",
    ).toBeNull();
  });
});
```

In plain English:

- **ex1** splits four shapes of path, including a `%2f` that must stay inside
  one segment, then a query with a key repeated twice and one repeated three
  times.
- **ex2** matches, fails to match on both the long and the short side, then
  covers the optional segment present and absent and the wildcard taking
  everything and nothing.
- **ex3** ranks five overlapping patterns into the one correct order, checks a
  catch-all sinks to the bottom, and checks the input array is not reordered.
- **ex4** builds six links, including an absent optional and a wildcard, and
  then asks for one with a parameter missing.
- **ex5** canonicalises seven paths, checks the already-canonical ones report
  `changed: false`, and checks that `%2f` is not treated as a separator.
- **ex6** mounts a handler and inspects what it saw, what was left on the
  request, and what `req.url` was afterwards — then tries a lookalike prefix and
  a nested mount.
- **ex7** registers a param route before the literal it would swallow, then
  exercises HEAD, OPTIONS, 404, two different 405s, and an async handler that
  throws.
- **ex8** walks a four-level tree, then asks for `/orders/new/lines`, which only
  resolves if the walk backtracks out of the static child.

Next: **d20_express_routes**, where a framework does some of this for you and
you find out which parts.

