// d19_http_routing / ex1 - reference solution (author only, used by `dojo verify`).

export interface RouteParts {
  segments: string[];
  query: Record<string, string | string[]>;
}

export function splitRoute(url: string): RouteParts {
  // A base is required because req.url is always relative; nothing about the
  // base survives into the answer.
  const parsed = new URL(url, "http://localhost");

  // Split FIRST, decode second. Decoding first would turn a %2f inside one
  // segment into a separator and split it into two.
  const segments = parsed.pathname
    .split("/")
    .filter((segment) => segment !== "")
    .map(decodeURIComponent);

  const query: Record<string, string | string[]> = {};
  // searchParams has already decoded both sides for us.
  for (const [key, value] of parsed.searchParams) {
    const existing = query[key];
    if (existing === undefined) query[key] = value;
    else if (Array.isArray(existing)) existing.push(value);
    else query[key] = [existing, value];
  }

  return { segments, query };
}

// d19_http_routing / ex2 - reference solution (author only, used by `dojo verify`).

export type RouteParams = Record<string, string>;

function segmentsOf(path: string): string[] {
  return path.split("/").filter((segment) => segment !== "");
}

export function matchPattern(pattern: string, pathname: string): RouteParams | null {
  const patternParts = segmentsOf(pattern);
  // Decoded once, up front, so literals, params and the wildcard all compare
  // and report the same way.
  const pathParts = segmentsOf(pathname).map(decodeURIComponent);
  const params: RouteParams = {};

  for (let i = 0; i < patternParts.length; i += 1) {
    const part = patternParts[i];

    if (part.startsWith("*")) {
      // The wildcard is always last and always matches, even against nothing.
      params[part.slice(1)] = pathParts.slice(i).join("/");
      return params;
    }

    if (i >= pathParts.length) {
      // The path ran out. That is only a match if everything left is optional.
      const remaining = patternParts.slice(i);
      const allOptional = remaining.every((rest) => rest.startsWith(":") && rest.endsWith("?"));
      return allOptional ? params : null;
    }

    if (part.startsWith(":")) {
      const optional = part.endsWith("?");
      params[part.slice(1, optional ? -1 : undefined)] = pathParts[i];
      continue;
    }

    if (part !== pathParts[i]) return null;
  }

  // The pattern ran out: a path with anything left over is a different route.
  return pathParts.length === patternParts.length ? params : null;
}

// d19_http_routing / ex3 - reference solution (author only, used by `dojo verify`).

function segmentsOf(pattern: string): string[] {
  return pattern.split("/").filter((segment) => segment !== "");
}

/**
 * How specific this pattern is at one position. Running out of segments scores
 * between a param and a wildcard, which is what makes `/orders` beat
 * `/orders/*rest` while still losing to `/orders/:id`.
 */
function rankAt(parts: string[], index: number): number {
  if (index >= parts.length) return 1;
  const part = parts[index];
  if (part.startsWith("*")) return 0;
  if (part.startsWith(":")) return 2;
  return 3;
}

export function rankPatterns(patterns: string[]): string[] {
  const entries = patterns.map((pattern, index) => ({
    pattern,
    index,
    parts: segmentsOf(pattern),
  }));

  // A copy, because sort() reorders in place and the caller handed us its
  // routing table, not a spare one.
  return entries
    .sort((a, b) => {
      const length = Math.max(a.parts.length, b.parts.length);
      for (let i = 0; i < length; i += 1) {
        const difference = rankAt(b.parts, i) - rankAt(a.parts, i);
        if (difference !== 0) return difference;
      }
      // Equally specific: registration order, stated rather than inherited
      // from whatever sort() happens to do.
      return a.index - b.index;
    })
    .map((entry) => entry.pattern);
}

// d19_http_routing / ex4 - reference solution (author only, used by `dojo verify`).

export function buildLink(
  pattern: string,
  params: Record<string, string> = {},
  query: Record<string, string | string[]> = {},
): string {
  const parts: string[] = [];

  for (const segment of pattern.split("/").filter((part) => part !== "")) {
    if (segment.startsWith("*")) {
      const name = segment.slice(1);
      const value = params[name];
      if (value === undefined) {
        throw new Error(`buildLink: missing parameter ${name} for ${pattern}`);
      }
      // The separators inside a wildcard are structure and survive; the
      // segments between them are content and are encoded.
      parts.push(
        ...value
          .split("/")
          .filter((part) => part !== "")
          .map(encodeURIComponent),
      );
      continue;
    }

    if (segment.startsWith(":")) {
      const optional = segment.endsWith("?");
      const name = segment.slice(1, optional ? -1 : undefined);
      const value = params[name];
      if (value === undefined) {
        if (optional) continue;
        throw new Error(`buildLink: missing parameter ${name} for ${pattern}`);
      }
      parts.push(encodeURIComponent(value));
      continue;
    }

    parts.push(segment);
  }

  const pairs: string[] = [];
  // Sorted, so the same inputs always produce the same string - which is what
  // makes the result usable as a cache key or a snapshot.
  for (const key of Object.keys(query).sort()) {
    const value = query[key];
    for (const item of Array.isArray(value) ? value : [value]) {
      pairs.push(`${encodeURIComponent(key)}=${encodeURIComponent(item)}`);
    }
  }

  return `/${parts.join("/")}${pairs.length === 0 ? "" : `?${pairs.join("&")}`}`;
}

// d19_http_routing / ex5 - reference solution (author only, used by `dojo verify`).

export interface Canonical {
  path: string;
  changed: boolean;
}

export function canonicalPath(url: string): Canonical {
  // The path only. The query is the caller's to carry.
  const raw = url.split("?")[0].split("#")[0];

  const parts: string[] = [];
  // Deliberately NOT decoded: %2f is a character in a segment, not a
  // separator, and decoding here puts back the traversal you are removing.
  for (const segment of raw.split("/")) {
    if (segment === "" || segment === ".") continue;
    if (segment === "..") {
      // pop() on an empty array is a no-op, which is exactly the rule: there
      // is nothing above the root to climb to.
      parts.pop();
      continue;
    }
    parts.push(segment);
  }

  const path = parts.length === 0 ? "/" : `/${parts.join("/")}`;
  return { path, changed: path !== raw };
}

// d19_http_routing / ex6 - reference solution (author only, used by `dojo verify`).
import type { IncomingMessage, ServerResponse } from "node:http";

export type Handler = (req: IncomingMessage, res: ServerResponse) => void;

type Mounted = IncomingMessage & { originalUrl?: string };

export function mountAt(prefix: string, handler: Handler): Handler {
  // Normalised once so the boundary test below is a single comparison.
  const base = prefix.endsWith("/") ? prefix.slice(0, -1) : prefix;

  return (req, res) => {
    const original = req.url ?? "/";
    const queryAt = original.indexOf("?");
    const pathname = queryAt === -1 ? original : original.slice(0, queryAt);
    const search = queryAt === -1 ? "" : original.slice(queryAt);

    const atMount = pathname === base || pathname === `${base}/`;
    // The trailing slash is what makes this a SEGMENT test: without it,
    // /api/v1extra starts with /api/v1 and gets mounted as "extra".
    const under = pathname.startsWith(`${base}/`);

    if (!atMount && !under) {
      const payload = JSON.stringify({ error: "not_found" });
      res.writeHead(404, {
        "content-type": "application/json; charset=utf-8",
        "content-length": Buffer.byteLength(payload),
      });
      res.end(payload);
      return;
    }

    const mounted = req as Mounted;
    // Only the outermost mount records it - a nested one would otherwise
    // overwrite it with the half-stripped path it was handed.
    if (mounted.originalUrl === undefined) mounted.originalUrl = original;

    // Nothing left means the root, because the empty string is not a path.
    req.url = `${atMount ? "/" : pathname.slice(base.length)}${search}`;
    try {
      handler(req, res);
    } finally {
      // The rewrite is a loan. Anything registered after this mount still
      // expects to see the URL the client sent.
      req.url = original;
    }
  };
}

// d19_http_routing / ex7 - reference solution (author only, used by `dojo verify`).
import type { IncomingMessage, ServerResponse } from "node:http";

export type Handler = (req: IncomingMessage, res: ServerResponse) => void;

export type RouteHandler = (
  req: IncomingMessage,
  res: ServerResponse,
  params: Record<string, string>,
) => void | Promise<void>;

export interface RouterOptions {
  onError?: (error: unknown) => void;
}

export interface Router {
  get(pattern: string, handler: RouteHandler): void;
  post(pattern: string, handler: RouteHandler): void;
  put(pattern: string, handler: RouteHandler): void;
  delete(pattern: string, handler: RouteHandler): void;
  handler: Handler;
}

interface Route {
  method: string;
  parts: string[];
  handler: RouteHandler;
}

function segmentsOf(path: string): string[] {
  return path.split("/").filter((segment) => segment !== "");
}

function rankAt(parts: string[], index: number): number {
  if (index >= parts.length) return 1;
  const part = parts[index];
  if (part.startsWith("*")) return 0;
  if (part.startsWith(":")) return 2;
  return 3;
}

function match(patternParts: string[], pathParts: string[]): Record<string, string> | null {
  const params: Record<string, string> = {};

  for (let i = 0; i < patternParts.length; i += 1) {
    const part = patternParts[i];
    if (part.startsWith("*")) {
      params[part.slice(1)] = pathParts.slice(i).join("/");
      return params;
    }
    if (i >= pathParts.length) {
      const remaining = patternParts.slice(i);
      return remaining.every((rest) => rest.startsWith(":") && rest.endsWith("?")) ? params : null;
    }
    if (part.startsWith(":")) {
      const optional = part.endsWith("?");
      params[part.slice(1, optional ? -1 : undefined)] = pathParts[i];
      continue;
    }
    if (part !== pathParts[i]) return null;
  }

  return pathParts.length === patternParts.length ? params : null;
}

function sendJson(res: ServerResponse, status: number, body: unknown): void {
  const payload = JSON.stringify(body);
  res.writeHead(status, {
    "content-type": "application/json; charset=utf-8",
    "content-length": Buffer.byteLength(payload),
  });
  res.end(payload);
}

export function createRouter(options: RouterOptions = {}): Router {
  const routes: Route[] = [];

  const register = (method: string, pattern: string, handler: RouteHandler): void => {
    routes.push({ method, parts: segmentsOf(pattern), handler });
    // Sorted on the way in rather than on every request. sort() is stable, so
    // equally specific routes keep their registration order.
    routes.sort((a, b) => {
      const length = Math.max(a.parts.length, b.parts.length);
      for (let i = 0; i < length; i += 1) {
        const difference = rankAt(b.parts, i) - rankAt(a.parts, i);
        if (difference !== 0) return difference;
      }
      return 0;
    });
  };

  const handler: Handler = (req, res) => {
    // The listener signature is synchronous, so the async work is started and
    // its failures are caught here - nothing is allowed to escape as an
    // unhandled rejection.
    void (async () => {
      try {
        const url = new URL(req.url ?? "/", "http://localhost");
        const pathParts = segmentsOf(url.pathname).map(decodeURIComponent);
        const method = (req.method ?? "GET").toUpperCase();
        // HEAD is not registered: it runs the GET and Node drops the body.
        const wanted = method === "HEAD" ? "GET" : method;

        for (const route of routes) {
          if (route.method !== wanted) continue;
          const params = match(route.parts, pathParts);
          if (params === null) continue;
          await route.handler(req, res, params);
          return;
        }

        const allowed = new Set<string>();
        for (const route of routes) {
          if (match(route.parts, pathParts) !== null) allowed.add(route.method);
        }

        // No method at all matches this path, so the path is what is missing.
        if (allowed.size === 0) {
          sendJson(res, 404, { error: "not_found" });
          return;
        }

        if (allowed.has("GET")) allowed.add("HEAD");
        allowed.add("OPTIONS");
        const allow = [...allowed].sort().join(", ");

        if (method === "OPTIONS") {
          res.writeHead(204, { allow });
          res.end();
          return;
        }

        res.setHeader("allow", allow);
        sendJson(res, 405, { error: "method_not_allowed" });
      } catch (error) {
        options.onError?.(error);
        // A handler that already started writing cannot be given a 500.
        if (res.headersSent) res.end();
        else sendJson(res, 500, { error: "internal_error" });
      }
    })();
  };

  return {
    get: (pattern, route) => register("GET", pattern, route),
    post: (pattern, route) => register("POST", pattern, route),
    put: (pattern, route) => register("PUT", pattern, route),
    delete: (pattern, route) => register("DELETE", pattern, route),
    handler,
  };
}

// d19_http_routing / ex8 - reference solution (author only, used by `dojo verify`).

export interface RouteNode {
  children?: Record<string, RouteNode>;
  param?: { name: string; node: RouteNode };
  index?: string[];
}

export interface RouteMatch {
  chain: string[];
  params: Record<string, string>;
}

export function resolveRouteTree(
  tree: RouteNode,
  method: string,
  pathname: string,
): RouteMatch | null {
  const segments = pathname
    .split("/")
    .filter((segment) => segment !== "")
    .map(decodeURIComponent);
  const wanted = method.toUpperCase();

  const walk = (node: RouteNode, depth: number): RouteMatch | null => {
    if (depth === segments.length) {
      // The path ends here, so this node has to be able to answer it. Matching
      // the path but not the method is not a match.
      return node.index?.includes(wanted) ? { chain: [], params: {} } : null;
    }

    const segment = segments[depth];

    // Static first: a literal child is more specific than a param child.
    const child = node.children?.[segment];
    if (child !== undefined) {
      const found = walk(child, depth + 1);
      // Note what does NOT happen here: a null does not return. The static
      // child matched this segment but failed further down, so the walk backs
      // out and tries the param child instead.
      if (found !== null) return { chain: [segment, ...found.chain], params: found.params };
    }

    if (node.param !== undefined) {
      const found = walk(node.param.node, depth + 1);
      if (found !== null) {
        return {
          chain: [`:${node.param.name}`, ...found.chain],
          // Spread the deeper params last, so a name bound twice resolves to
          // the innermost binding.
          params: { [node.param.name]: segment, ...found.params },
        };
      }
    }

    return null;
  };

  return walk(tree, 0);
}

