// d20_express_routes / ex1 - reference solution (author only, used by `dojo verify`).
import express, { type Express } from "express";

export interface Note {
  id: string;
  title: string;
}

export const SEED: Note[] = [
  { id: "n1", title: "buy milk" },
  { id: "n2", title: "call ada" },
];

export function createApp(): Express {
  const app = express();
  const notes: Note[] = SEED.map((note) => ({ ...note }));

  app.use(express.json());

  app
    .route("/notes/:id")
    .get((req, res) => {
      const note = notes.find((candidate) => candidate.id === req.params.id);
      if (note === undefined) {
        res.status(404).json({ error: "not_found" });
        return;
      }
      res.json(note);
    })
    .put((req, res) => {
      const note = notes.find((candidate) => candidate.id === req.params.id);
      if (note === undefined) {
        res.status(404).json({ error: "not_found" });
        return;
      }
      note.title = String(req.body.title);
      res.json(note);
    })
    .delete((req, res) => {
      const index = notes.findIndex((candidate) => candidate.id === req.params.id);
      if (index === -1) {
        res.status(404).json({ error: "not_found" });
        return;
      }
      notes.splice(index, 1);
      // 204 says "done, and there is nothing to send" - so send nothing.
      res.status(204).end();
    });

  return app;
}

// d20_express_routes / ex2 - reference solution (author only, used by `dojo verify`).
import express, { type Express, type Request } from "express";

export interface Note {
  id: string;
  title: string;
}

export const SEED: Note[] = [
  { id: "n1", title: "buy milk" },
  { id: "n2", title: "call ada" },
];

/** What the param callback adds to the request, for the handlers below it. */
interface LoadedRequest extends Request {
  note?: Note;
  seenBy?: string[];
}

export function createApp(): Express {
  const app = express();
  const notes: Note[] = SEED.map((note) => ({ ...note }));
  let lookups = 0;

  app.use(express.json());

  // Registered once, for every route whose path contains :id - and only those.
  app.param("id", (req: LoadedRequest, res, next, id: string) => {
    lookups += 1;
    const note = notes.find((candidate) => candidate.id === id);
    if (note === undefined) {
      // The one place the 404 is worded.
      res.status(404).json({ error: "not_found" });
      return;
    }
    req.note = note;
    req.seenBy = [];
    next();
  });

  const stamp = (req: LoadedRequest, _res: express.Response, next: express.NextFunction) => {
    req.seenBy?.push("stamp");
    next();
  };

  app.get("/notes/:id", stamp, (req: LoadedRequest, res) => {
    req.seenBy?.push("show");
    res.json({ note: req.note, seenBy: req.seenBy });
  });

  app.put("/notes/:id", (req: LoadedRequest, res) => {
    const note = req.note as Note;
    note.title = String(req.body.title);
    res.json(note);
  });

  app.delete("/notes/:id", (req: LoadedRequest, res) => {
    const index = notes.findIndex((candidate) => candidate.id === (req.note as Note).id);
    notes.splice(index, 1);
    res.status(204).end();
  });

  app.get("/health", (_req, res) => {
    res.json({ status: "ok" });
  });

  app.get("/stats", (_req, res) => {
    res.json({ lookups });
  });

  return app;
}

// d20_express_routes / ex3 - reference solution (author only, used by `dojo verify`).
import express, { type Express } from "express";

export interface Note {
  id: string;
  projectId: string;
  title: string;
}

export const SEED: Note[] = [
  { id: "n1", projectId: "p1", title: "buy milk" },
  { id: "n2", projectId: "p1", title: "call ada" },
  { id: "n3", projectId: "p2", title: "write it up" },
];

export const PROJECT_IDS = ["p1", "p2"];

export function createApp(): Express {
  const app = express();
  const notes = SEED.map((note) => ({ ...note }));

  // Without mergeParams the router gets only its OWN parameters, and
  // req.params.projectId is undefined inside every route below.
  const projectNotes = express.Router({ mergeParams: true });

  // One guard for the whole subtree, which is only possible because the router
  // can read the parameter it was mounted under.
  projectNotes.use((req, res, next) => {
    if (!PROJECT_IDS.includes(String(req.params.projectId))) {
      res.status(404).json({ error: "no_such_project" });
      return;
    }
    next();
  });

  projectNotes.get("/notes", (req, res) => {
    const projectId = String(req.params.projectId);
    res.json({
      projectId,
      noteIds: notes.filter((note) => note.projectId === projectId).map((note) => note.id),
    });
  });

  projectNotes.get("/notes/:noteId", (req, res) => {
    const projectId = String(req.params.projectId);
    const note = notes.find(
      (candidate) => candidate.id === req.params.noteId && candidate.projectId === projectId,
    );
    if (note === undefined) {
      res.status(404).json({ error: "not_found" });
      return;
    }
    res.json({ projectId, noteId: note.id, title: note.title });
  });

  app.use("/projects/:projectId", projectNotes);

  return app;
}

// d20_express_routes / ex4 - reference solution (author only, used by `dojo verify`).
import express, { type Express, type NextFunction, type Request, type Response } from "express";

interface TrailedRequest extends Request {
  trail?: string[];
}

export function createApp(): Express {
  const app = express();

  const guard = (req: TrailedRequest, _res: Response, next: NextFunction) => {
    req.trail = req.trail ?? [];
    req.trail.push("guard");
    // next("route") is not an error and not a skip-one: it abandons the rest of
    // THIS route and offers the request to the next route that matches.
    if (!/^\d+$/.test(String(req.params.id))) {
      next("route");
      return;
    }
    next();
  };

  app.get("/reports/:id", guard, (req: TrailedRequest, res) => {
    req.trail?.push("numeric");
    res.json({ handled: "numeric", trail: req.trail });
  });

  app.get("/reports/:id", (req: TrailedRequest, res) => {
    req.trail?.push("slug");
    res.json({ handled: "slug", trail: req.trail });
  });

  return app;
}

// d20_express_routes / ex5 - reference solution (author only, used by `dojo verify`).
import express, { type Express } from "express";

export function createApp(): Express {
  const app = express();

  // Registered on the parent, so it runs for everything - mounted or not.
  app.use((_req, res, next) => {
    res.setHeader("x-parent", "ran");
    next();
  });

  const api = express();

  // Registered on the sub-app, so mounting is what scopes it to /api/v2.
  api.use((_req, res, next) => {
    res.setHeader("x-sub", "ran");
    next();
  });

  api.get("/notes/:id", (req, res) => {
    res.json({
      // where this app was mounted
      baseUrl: req.baseUrl,
      // what the client asked for, untouched
      originalUrl: req.originalUrl,
      // what is left for this app to route on, query string included
      url: req.url,
      id: req.params.id,
    });
  });

  app.use("/api/v2", api);

  app.get("/health", (_req, res) => {
    res.json({ status: "ok" });
  });

  return app;
}

// d20_express_routes / ex6 - reference solution (author only, used by `dojo verify`).
import express, { type Express } from "express";

export interface AppConfig {
  strict: boolean;
  caseSensitive: boolean;
  service: string;
}

export function createApp(config: AppConfig): Express {
  const app = express();

  // Both settings are read when the router is built, so they have to be set
  // before any route is registered - afterwards they change nothing.
  app.set("strict routing", config.strict);
  app.set("case sensitive routing", config.caseSensitive);

  // Application-wide, shared by every request.
  app.locals.service = config.service;

  app.use((req, res, next) => {
    // Per response, thrown away when it is finished.
    res.locals.tenant = req.get("x-tenant") ?? "public";
    next();
  });

  app.get("/notes", (_req, res) => {
    res.json({
      service: app.locals.service,
      tenant: res.locals.tenant,
      strict: app.get("strict routing") as boolean,
    });
  });

  return app;
}

// d20_express_routes / ex7 - reference solution (author only, used by `dojo verify`).
import express, { type Express } from "express";

export interface ResourceRecord {
  id: string;
  title: string;
}

export interface ResourceStore {
  list(): ResourceRecord[];
  get(id: string): ResourceRecord | undefined;
  create(input: { title: string }): ResourceRecord;
  update(id: string, input: { title: string }): ResourceRecord | undefined;
  remove(id: string): boolean;
}

export interface ResourceSpec {
  name: string;
  store: ResourceStore;
}

export function mountResource(app: Express, spec: ResourceSpec): void {
  const { name, store } = spec;
  // A Router keeps the paths relative and the closure keeps `store` private to
  // this resource - which is what makes two mounts independent.
  const router = express.Router();

  router.get("/", (_req, res) => {
    res.json(store.list());
  });

  router.post("/", (req, res) => {
    const created = store.create({ title: String(req.body.title) });
    res.setHeader("location", `/${name}/${created.id}`);
    res.status(201).json(created);
  });

  router.get("/:id", (req, res) => {
    const found = store.get(req.params.id);
    if (found === undefined) {
      res.status(404).json({ error: "not_found" });
      return;
    }
    res.json(found);
  });

  router.put("/:id", (req, res) => {
    const updated = store.update(req.params.id, { title: String(req.body.title) });
    if (updated === undefined) {
      res.status(404).json({ error: "not_found" });
      return;
    }
    res.json(updated);
  });

  router.delete("/:id", (req, res) => {
    if (!store.remove(req.params.id)) {
      res.status(404).json({ error: "not_found" });
      return;
    }
    res.status(204).end();
  });

  app.use(`/${name}`, router);
}

// d20_express_routes / ex8 - reference solution (author only, used by `dojo verify`).
import express, { type Express } from "express";

export interface Note {
  id: string;
  title: string;
}

export const SEED: Note[] = [{ id: "n1", title: "buy milk" }];

/** The methods a path answers, plus the two the protocol adds for free. */
function allowHeader(methods: string[]): string {
  const advertised = new Set([...methods, "OPTIONS"]);
  if (advertised.has("GET")) advertised.add("HEAD");
  return [...advertised].sort().join(", ");
}

export function createApp(): Express {
  const app = express();
  const notes: Note[] = SEED.map((note) => ({ ...note }));

  app.use(express.json());

  app.get("/notes", (_req, res) => {
    res.json(notes);
  });
  app.post("/notes", (req, res) => {
    const note = { id: `n${notes.length + 1}`, title: String(req.body.title) };
    notes.push(note);
    res.status(201).json(note);
  });

  app.get("/notes/:id", (req, res) => {
    const note = notes.find((candidate) => candidate.id === req.params.id);
    if (note === undefined) {
      res.status(404).json({ error: "not_found" });
      return;
    }
    res.json(note);
  });
  app.patch("/notes/:id", (req, res) => {
    const note = notes.find((candidate) => candidate.id === req.params.id);
    if (note === undefined) {
      res.status(404).json({ error: "not_found" });
      return;
    }
    note.title = String(req.body.title);
    res.json(note);
  });
  app.delete("/notes/:id", (req, res) => {
    const index = notes.findIndex((candidate) => candidate.id === req.params.id);
    if (index === -1) {
      res.status(404).json({ error: "not_found" });
      return;
    }
    notes.splice(index, 1);
    res.status(204).end();
  });

  app.get("/health", (_req, res) => {
    res.json({ status: "ok" });
  });

  // One app.all() per path, AFTER that path's real methods. Express tries the
  // registrations in order, so a method that matched above never reaches here,
  // and a method that did not falls into it - which is the whole trick.
  const paths: { path: string; methods: string[] }[] = [
    { path: "/notes", methods: ["GET", "POST"] },
    { path: "/notes/:id", methods: ["GET", "PATCH", "DELETE"] },
    { path: "/health", methods: ["GET"] },
  ];

  for (const entry of paths) {
    app.all(entry.path, (req, res) => {
      res.setHeader("allow", allowHeader(entry.methods));
      if (req.method === "OPTIONS") {
        // A question about the path, not a refused method.
        res.status(204).end();
        return;
      }
      res.status(405).json({ error: "method_not_allowed" });
    });
  }

  // Nothing above matched the PATH at all.
  app.use((_req, res) => {
    res.status(404).json({ error: "not_found" });
  });

  return app;
}

