// d21_middleware / ex1 - reference solution (author only, used by `dojo verify`).
import { type RequestHandler, type Response } from "express";

export interface TimingOptions {
  now: () => number;
}

export function timing(options: TimingOptions): RequestHandler {
  return (_req, res, next) => {
    const start = options.now();

    // res.end() is the one funnel every response goes through - res.json(),
    // res.send(), a 404 from express itself. Wrapping it is how you get a
    // last word before the headers are committed; res.on("finish") is one
    // moment too late, because by then they are already on the wire.
    const originalEnd = res.end.bind(res) as (...args: unknown[]) => Response;
    res.end = ((...args: unknown[]) => {
      if (!res.headersSent) {
        res.setHeader("x-response-time", String(options.now() - start));
      }
      return originalEnd(...args);
    }) as typeof res.end;

    next();
  };
}

// d21_middleware / ex2 - reference solution (author only, used by `dojo verify`).
import { type Request, type RequestHandler } from "express";

export function only(
  predicate: (req: Request) => boolean,
  middleware: RequestHandler,
): RequestHandler {
  return (req, res, next) => {
    if (!predicate(req)) {
      // Skipping is an explicit next(), not a return: a middleware that
      // returns without calling next() leaves the request hanging.
      next();
      return;
    }
    // A pass-through, not a catch: next(error) and next("route") both have to
    // reach the caller exactly as the wrapped middleware sent them.
    middleware(req, res, next);
  };
}

// d21_middleware / ex3 - reference solution (author only, used by `dojo verify`).
import { type NextFunction, type RequestHandler } from "express";

export function compose(...middlewares: RequestHandler[]): RequestHandler {
  return (req, res, next) => {
    const step = (index: number): void => {
      const middleware = middlewares[index];
      // Ran out: the composition as a whole is done, so carry on outside it.
      if (middleware === undefined) {
        next();
        return;
      }

      const advance: NextFunction = (error?: unknown) => {
        // Anything passed to next - an Error, or the string "route" - belongs
        // to the OUTER next, not to the next middleware in this stack.
        if (error !== undefined && error !== null) {
          next(error);
          return;
        }
        step(index + 1);
      };

      middleware(req, res, advance);
    };

    step(0);
  };
}

// d21_middleware / ex4 - reference solution (author only, used by `dojo verify`).
import express, { type ErrorRequestHandler, type Express } from "express";

export interface ErrorAppHooks {
  log: (message: string) => void;
}

/** An error this API knows how to explain to a client. */
class KnownProblem extends Error {
  readonly status = 422;
  readonly code = "unprocessable";
}

export const finalErrorHandler: ErrorRequestHandler = (error, _req, res, next) => {
  // Nothing can be changed about a response that has already begun, so the
  // only honest move is to hand it back to express, which will destroy the
  // connection rather than send a second answer.
  if (res.headersSent) {
    next(error);
    return;
  }

  const hooks = res.locals.hooks as ErrorAppHooks | undefined;
  hooks?.log(`boom: ${(error as Error).message}`);

  res.status(500).json({
    error: "internal_error",
    message: "internal server error",
    touched: res.locals.touched === true,
  });
};

export function createApp(hooks: ErrorAppHooks): Express {
  const app = express();

  app.use((_req, res, next) => {
    // The final handler is a module-level constant, so it is handed its
    // collaborators through the response rather than through a closure.
    res.locals.hooks = hooks;
    next();
  });

  app.get("/ok", (_req, res) => {
    res.json({ status: "ok" });
  });

  app.get("/known", () => {
    throw new KnownProblem("known problem");
  });

  app.get("/unknown", () => {
    throw new Error("the database is on fire");
  });

  // First error handler: recognises its own errors, passes on everything else.
  app.use(((error, _req, res, next) => {
    if (error instanceof KnownProblem) {
      res.status(error.status).json({ error: error.code, message: error.message });
      return;
    }
    next(error);
  }) as ErrorRequestHandler);

  // Ordinary middleware. On the normal path it runs; in the error path express
  // skips it, because it takes three arguments and not four.
  app.use((_req, res, next) => {
    res.locals.touched = true;
    res.setHeader("x-marker", "ran");
    next();
  });

  app.use(finalErrorHandler);

  return app;
}

// d21_middleware / ex5 - reference solution (author only, used by `dojo verify`).
import express, {
  type ErrorRequestHandler,
  type Express,
  type RequestHandler,
} from "express";

export const BODY_LIMIT = 200;

/**
 * express.json() skips a content-type it was not asked to parse and says
 * nothing about it, so req.body is left undefined. Both of these checks are
 * ours - the parser raises neither.
 */
const requireJsonBody: RequestHandler = (req, res, next) => {
  if (req.body === undefined) {
    res.status(415).json({ error: "unsupported_media_type" });
    return;
  }
  if (Object.keys(req.body).length === 0) {
    res.status(400).json({ error: "empty_body" });
    return;
  }
  next();
};

/** Everything body-parser throws carries a `type`; that is the thing to switch on. */
const bodyErrorHandler: ErrorRequestHandler = (error, _req, res, next) => {
  const type = (error as { type?: string }).type;
  if (type === "entity.too.large") {
    res.status(413).json({ error: "payload_too_large" });
    return;
  }
  if (type === "entity.parse.failed") {
    res.status(400).json({ error: "invalid_json" });
    return;
  }
  next(error);
};

export function createApp(): Express {
  const app = express();

  app.use(express.json({ limit: BODY_LIMIT, type: "application/json" }));

  app.post("/notes", requireJsonBody, (req, res) => {
    res.status(201).json({ id: "n1", title: String(req.body.title) });
  });

  app.use(bodyErrorHandler);

  return app;
}

// d21_middleware / ex6 - reference solution (author only, used by `dojo verify`).
import { type Request, type RequestHandler } from "express";

export interface Principal {
  name: string;
  roles: string[];
}

export interface BearerAuthOptions {
  verify: (token: string) => Principal | undefined | Promise<Principal | undefined>;
}

export interface AuthedRequest extends Request {
  principal?: Principal;
}

/** The challenge belongs on every 401 and on no 403. */
function unauthorized(res: Parameters<RequestHandler>[1]): void {
  res.setHeader("www-authenticate", 'Bearer realm="api"');
  res.status(401).json({ error: "unauthorized" });
}

export function bearerAuth(options: BearerAuthOptions): RequestHandler {
  return async (req: AuthedRequest, res, next) => {
    const header = req.get("authorization");
    // Scheme first: a header in some other scheme is not a bearer token, and
    // handing its contents to verify() is how a Basic password ends up in a
    // token lookup.
    const [scheme, token] = (header ?? "").split(" ");
    if (scheme?.toLowerCase() !== "bearer" || !token) {
      unauthorized(res);
      return;
    }

    const principal = await options.verify(token);
    if (principal === undefined) {
      unauthorized(res);
      return;
    }

    req.principal = principal;
    next();
  };
}

export function requireRole(role: string): RequestHandler {
  return (req: AuthedRequest, res, next) => {
    if (req.principal === undefined) {
      // Nobody has said who they are yet, so this is still an authentication
      // problem and not an authorisation one.
      unauthorized(res);
      return;
    }
    if (!req.principal.roles.includes(role)) {
      // Authenticated, and still not allowed. Retrying will not help, so there
      // is no challenge to send.
      res.status(403).json({ error: "forbidden" });
      return;
    }
    next();
  };
}

// d21_middleware / ex7 - reference solution (author only, used by `dojo verify`).
import { type RequestHandler, type Response } from "express";

export interface ConcurrencyOptions {
  max: number;
  queue: number;
}

export function concurrencyLimit(options: ConcurrencyOptions): RequestHandler {
  let active = 0;
  //: requests holding a place in line, oldest first
  const waiting: (() => void)[] = [];

  /** Hand the slot to the longest waiter, or put it back on the count. */
  const release = (): void => {
    const next = waiting.shift();
    if (next) next();
    else active -= 1;
  };

  /**
   * One release per request, whatever happened to it. "finish" is a response
   * that was sent; "close" is one whose connection went away first. Both have
   * to give the slot back, and neither may give it back twice.
   */
  const releaseOnce = (res: Response): void => {
    let released = false;
    const once = () => {
      if (released) return;
      released = true;
      release();
    };
    res.on("finish", once);
    res.on("close", once);
  };

  return (_req, res, next) => {
    if (active < options.max) {
      active += 1;
      releaseOnce(res);
      next();
      return;
    }

    if (waiting.length < options.queue) {
      // The slot is handed straight over when it comes back, so `active` never
      // dips and a third request cannot slip in between the two.
      waiting.push(() => {
        releaseOnce(res);
        next();
      });
      return;
    }

    res.setHeader("retry-after", "1");
    res.status(503).json({ error: "too_busy" });
  };
}

// d21_middleware / ex8 - reference solution (author only, used by `dojo verify`).
import { type RequestHandler } from "express";

export interface ResponseCacheOptions {
  ttl: number;
  now: () => number;
}

interface Entry {
  /** Kept so a write to this path can find every entry belonging to it. */
  path: string;
  status: number;
  body: unknown;
  expiresAt: number;
}

export function responseCache(options: ResponseCacheOptions): RequestHandler {
  const store = new Map<string, Entry>();

  return (req, res, next) => {
    // A write is never answered from a cache, and it makes what is stored for
    // its path wrong - so it clears it on the way in.
    if (req.method !== "GET") {
      for (const [key, entry] of store) {
        if (entry.path === req.path) store.delete(key);
      }
      next();
      return;
    }

    // no-store is an instruction, not a hint: do not read, do not write.
    if ((req.get("cache-control") ?? "").includes("no-store")) {
      res.setHeader("x-cache", "MISS");
      next();
      return;
    }

    const key = `${req.method} ${req.originalUrl}`;
    const cached = store.get(key);
    if (cached !== undefined && cached.expiresAt > options.now()) {
      res.setHeader("x-cache", "HIT");
      res.status(cached.status).json(cached.body);
      return;
    }
    // Expired entries are dropped rather than left to rot in the map.
    if (cached !== undefined) store.delete(key);

    res.setHeader("x-cache", "MISS");

    // res.json() is where the body still exists as a value. After it, the
    // response is bytes on a socket and there is nothing left to keep.
    const originalJson = res.json.bind(res);
    res.json = ((body: unknown) => {
      if (res.statusCode >= 200 && res.statusCode < 300) {
        store.set(key, {
          path: req.path,
          status: res.statusCode,
          body,
          expiresAt: options.now() + options.ttl,
        });
      }
      return originalJson(body);
    }) as typeof res.json;

    next();
  };
}

