// d22_validation_zod / ex1 - reference solution (author only, used by `dojo verify`).
import express, { type Express } from "express";
import { z } from "zod";

export const articleQuerySchema = z.object({
  // Everything in a query string arrives as a string, so the schema coerces
  // first and constrains afterwards. default() runs before coercion, which is
  // why an absent parameter is not a failed number.
  limit: z.coerce.number().int().positive().max(50).default(10),
  page: z.coerce.number().int().min(1).default(1),
  order: z.enum(["asc", "desc"]).default("asc"),
});

export function createApp(): Express {
  const app = express();

  app.get("/articles", (req, res) => {
    const result = articleQuerySchema.safeParse(req.query);
    if (!result.success) {
      res.status(400).json({
        error: "invalid_query",
        issues: result.error.issues.map((issue) => ({
          path: issue.path.join("."),
          code: issue.code,
          message: issue.message,
        })),
      });
      return;
    }

    res.json(result.data);
  });

  return app;
}

// d22_validation_zod / ex2 - reference solution (author only, used by `dojo verify`).
import express, { type Express } from "express";
import { z } from "zod";

export const eventSchema = z.discriminatedUnion("type", [
  z.object({ type: z.literal("click"), x: z.number(), y: z.number() }),
  z.object({ type: z.literal("keypress"), key: z.string().min(1) }),
  z.object({ type: z.literal("scroll"), delta: z.number() }),
]);

export type AppEvent = z.infer<typeof eventSchema>;

function summarise(event: AppEvent): string {
  // The union is discriminated, so TypeScript narrows on `type` here for free.
  switch (event.type) {
    case "click":
      return `click at ${event.x},${event.y}`;
    case "keypress":
      return `key ${event.key}`;
    case "scroll":
      return `scroll by ${event.delta}`;
  }
}

export function createApp(): Express {
  const app = express();
  app.use(express.json());

  app.post("/events", (req, res) => {
    const result = eventSchema.safeParse(req.body);
    if (result.success) {
      res.status(202).json({ summary: summarise(result.data) });
      return;
    }

    const issues = result.error.issues.map((issue) => ({
      path: issue.path.join("."),
      code: issue.code,
      message: issue.message,
    }));

    // The discriminator failing and a branch failing are different answers:
    // one means "no such event", the other means "that event, spelled wrong".
    const unknownType = result.error.issues.some(
      (issue) => issue.code === "invalid_union_discriminator",
    );
    if (unknownType) {
      res.status(400).json({ error: "unknown_event_type", discriminator: "type", issues });
      return;
    }

    res.status(400).json({ error: "invalid_event", issues });
  });

  return app;
}

// d22_validation_zod / ex3 - reference solution (author only, used by `dojo verify`).
import { z } from "zod";

export const bookingSchema = z
  .object({
    startsAt: z.string().min(1),
    endsAt: z.string().min(1),
    seats: z.number().int().min(1).max(8),
    email: z.string().email().optional(),
    phone: z.string().min(5).optional(),
  })
  .superRefine((value, ctx) => {
    // ISO-8601 strings compare correctly as strings, which is the one thing
    // that format is for.
    if (value.endsAt <= value.startsAt) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        // Without a path the issue lands on the object and no form field can
        // display it.
        path: ["endsAt"],
        message: "endsAt must be after startsAt",
      });
    }

    if (value.email === undefined && value.phone === undefined) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        path: ["email"],
        message: "email or phone is required",
      });
    }
  });

// d22_validation_zod / ex4 - reference solution (author only, used by `dojo verify`).
import { z } from "zod";

export const signupSchema = z.object({
  // trim() and toLowerCase() are transforms; .pipe() feeds what they produced
  // into the next schema, so the address is judged AFTER it is tidied.
  email: z.string().trim().toLowerCase().pipe(z.string().email()),

  // new Date("nonsense") does not throw - it returns an Invalid Date. The
  // z.date() on the far side of the pipe is what catches that.
  joinedAt: z
    .string()
    .transform((value) => new Date(value))
    .pipe(z.date()),

  // The default is applied to the INPUT, so the transform still runs on it.
  tags: z
    .string()
    .default("")
    .transform((value) => [
      ...new Set(
        value
          .split(",")
          .map((tag) => tag.trim())
          .filter((tag) => tag !== ""),
      ),
    ]),
});

export type Signup = z.infer<typeof signupSchema>;

// d22_validation_zod / ex5 - reference solution (author only, used by `dojo verify`).
import express, { type Express } from "express";
import { z, type ZodTypeAny } from "zod";

const bookShape = { title: z.string().min(1), pages: z.number().int().positive() };

export const stripSchema = z.object(bookShape);
export const strictSchema = z.object(bookShape).strict();
export const passthroughSchema = z.object(bookShape).passthrough();

/** Parse, or answer 400 - telling an unknown key apart from a bad one. */
function handle(schema: ZodTypeAny, body: unknown, res: express.Response): void {
  const result = schema.safeParse(body);
  if (result.success) {
    res.status(201).json(result.data);
    return;
  }

  // unrecognized_keys carries the offending names, which is the only reason
  // strict() is worth more than a 400 with no detail.
  const unknown = result.error.issues.find((issue) => issue.code === "unrecognized_keys");
  if (unknown !== undefined) {
    res.status(400).json({ error: "unknown_fields", keys: unknown.keys });
    return;
  }

  res.status(400).json({
    error: "validation_failed",
    issues: result.error.issues.map((issue) => ({
      path: issue.path.join("."),
      message: issue.message,
    })),
  });
}

export function createApp(): Express {
  const app = express();
  app.use(express.json());

  app.post("/strip", (req, res) => handle(stripSchema, req.body, res));
  app.post("/strict", (req, res) => handle(strictSchema, req.body, res));
  app.post("/passthrough", (req, res) => handle(passthroughSchema, req.body, res));

  return app;
}

// d22_validation_zod / ex6 - reference solution (author only, used by `dojo verify`).
import express, { type Express, type RequestHandler } from "express";
import { z, type ZodTypeAny } from "zod";

export interface ValidationSchemas {
  params?: ZodTypeAny;
  query?: ZodTypeAny;
  body?: ZodTypeAny;
}

export interface ValidatedRequest {
  valid: { params?: unknown; query?: unknown; body?: unknown };
}

const PARTS = ["params", "query", "body"] as const;

export function validate(schemas: ValidationSchemas): RequestHandler {
  return (req, res, next) => {
    const issues: { path: string; message: string }[] = [];
    const valid: ValidatedRequest["valid"] = {};

    for (const part of PARTS) {
      const schema = schemas[part];
      if (schema === undefined) continue;

      const result = schema.safeParse(req[part]);
      if (result.success) {
        valid[part] = result.data;
        continue;
      }
      // Keep going: the client wants every problem, not the first one.
      for (const issue of result.error.issues) {
        const tail = issue.path.join(".");
        issues.push({ path: tail === "" ? part : `${part}.${tail}`, message: issue.message });
      }
    }

    if (issues.length > 0) {
      res.status(400).json({ error: "validation_failed", issues });
      return;
    }

    // req.query is a getter in express 5 - assigning to it throws, so the
    // parsed request lives in a place of its own.
    (req as unknown as ValidatedRequest).valid = valid;
    next();
  };
}

export function createApp(): Express {
  const app = express();
  app.use(express.json());

  app.patch(
    "/projects/:id/tasks",
    validate({
      params: z.object({ id: z.string().regex(/^proj-\d+$/) }),
      query: z.object({ dryRun: z.enum(["true", "false"]).default("false") }),
      body: z.object({ title: z.string().min(1) }),
    }),
    (req, res) => {
      res.json((req as unknown as ValidatedRequest).valid);
    },
  );

  return app;
}

// d22_validation_zod / ex7 - reference solution (author only, used by `dojo verify`).
import { type ZodError } from "zod";

export interface ProblemIssue {
  path: string;
  code: string;
  message: string;
}

export interface Problem {
  error: string;
  issues: ProblemIssue[];
}

/**
 * ["items", 0, "qty"] -> "items[0].qty".
 *
 * A number is an array index and binds tight to what came before it; a string
 * is a key and takes a dot, unless it is the first thing in the path.
 */
function renderPath(path: (string | number)[]): string {
  if (path.length === 0) return "(root)";
  return path.reduce<string>((rendered, segment) => {
    if (typeof segment === "number") return `${rendered}[${segment}]`;
    return rendered === "" ? segment : `${rendered}.${segment}`;
  }, "");
}

export function toProblem(error: ZodError): Problem {
  return {
    error: "validation_failed",
    // zod's own order is already stable and meaningful (schema order, with the
    // object-level issues last), so it is kept rather than sorted.
    issues: error.issues.map((issue) => ({
      path: renderPath(issue.path),
      code: issue.code,
      // An invalid_union carries the failures of every branch in unionErrors.
      // They contradict each other by construction, so the union's own message
      // is the honest one to show.
      message: issue.message,
    })),
  };
}

// d22_validation_zod / ex8 - reference solution (author only, used by `dojo verify`).
import express, { type Express } from "express";
import { z } from "zod";

export const MAX_DEPTH = 3;

export interface Category {
  name: string;
  children: Category[];
}

// The annotation is not optional: without it TypeScript cannot infer the type
// of something defined in terms of itself, and z.lazy() defers the evaluation
// so the reference to `categoryNode` inside is resolved at parse time.
const categoryNode: z.ZodType<Category> = z.lazy(() =>
  z.object({
    name: z.string().min(1),
    children: z.array(categoryNode).default([]),
  }),
);

/** ["children", 1, "name"] -> "children[1].name". */
function renderPath(path: (string | number)[]): string {
  return path.reduce<string>((rendered, segment) => {
    if (typeof segment === "number") return `${rendered}[${segment}]`;
    return rendered === "" ? segment : `${rendered}.${segment}`;
  }, "");
}

function depthOf(node: Category): number {
  return 1 + Math.max(0, ...node.children.map(depthOf));
}

export const categorySchema = categoryNode.superRefine((value, ctx) => {
  // The depth rule cannot live on the node schema: a node has no idea how far
  // down it sits. It belongs to the whole tree, walked from the root.
  const walk = (node: Category, depth: number, path: (string | number)[]): void => {
    if (depth > MAX_DEPTH) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        path: [...path, "name"],
        message: `a category tree may be at most ${MAX_DEPTH} levels deep`,
      });
      return;
    }
    node.children.forEach((child, index) => {
      walk(child, depth + 1, [...path, "children", index]);
    });
  };

  walk(value, 1, []);
});

export function createApp(): Express {
  const app = express();
  app.use(express.json());

  app.post("/categories", (req, res) => {
    const result = categorySchema.safeParse(req.body);
    if (!result.success) {
      res.status(400).json({
        error: "invalid_category",
        issues: result.error.issues.map((issue) => ({
          path: renderPath(issue.path),
          message: issue.message,
        })),
      });
      return;
    }

    res.status(201).json({ depth: depthOf(result.data) });
  });

  return app;
}

