// d23_rest_patterns / ex1 - reference solution (author only, used by `dojo verify`).
import express, { type Express, type Response } from "express";

export interface Task {
  id: string;
  title: string;
  done: boolean;
}

function notFound(res: Response): void {
  res.status(404).json({ error: "not_found" });
}

function titleOf(body: unknown): string | null {
  const title = (body as { title?: unknown } | undefined)?.title;
  return typeof title === "string" && title !== "" ? title : null;
}

export function createApp(): Express {
  const app = express();
  app.use(express.json());

  const tasks: Task[] = [{ id: "seed-1", title: "write the spec", done: false }];
  let nextId = 1;

  app.get("/tasks", (_req, res) => {
    res.json(tasks);
  });

  app.post("/tasks", (req, res) => {
    const title = titleOf(req.body);
    if (title === null) {
      res.status(400).json({ error: "invalid_body" });
      return;
    }

    // The SERVER picks the id, so the client can only learn it from Location.
    const task: Task = { id: `task-${nextId}`, title, done: false };
    nextId += 1;
    tasks.push(task);
    res.status(201).location(`/tasks/${task.id}`).json(task);
  });

  app.put("/tasks/:id", (req, res) => {
    const title = titleOf(req.body);
    if (title === null) {
      res.status(400).json({ error: "invalid_body" });
      return;
    }

    // PUT sends a whole representation, so anything it leaves out is absent -
    // not preserved from what used to be there.
    const replacement: Task = {
      id: req.params.id,
      title,
      done: (req.body as { done?: unknown }).done === true,
    };

    const index = tasks.findIndex((task) => task.id === req.params.id);
    if (index === -1) {
      tasks.push(replacement);
      res.status(201).location(`/tasks/${replacement.id}`).json(replacement);
      return;
    }

    tasks[index] = replacement;
    res.json(replacement);
  });

  app.patch("/tasks/:id", (req, res) => {
    const task = tasks.find((candidate) => candidate.id === req.params.id);
    if (task === undefined) {
      // PATCH describes a change to something that exists. There is nothing
      // here to change, and inventing it would be a PUT.
      notFound(res);
      return;
    }

    const patch = req.body as { title?: unknown; done?: unknown };
    if (typeof patch.title === "string" && patch.title !== "") task.title = patch.title;
    if (typeof patch.done === "boolean") task.done = patch.done;
    res.json(task);
  });

  app.delete("/tasks/:id", (req, res) => {
    const index = tasks.findIndex((task) => task.id === req.params.id);
    if (index === -1) {
      notFound(res);
      return;
    }

    tasks.splice(index, 1);
    res.status(204).end();
  });

  return app;
}

// d23_rest_patterns / ex2 - reference solution (author only, used by `dojo verify`).
import express, { type Express } from "express";

export interface Task {
  id: string;
  title: string;
  done: boolean;
  owner: string;
  createdAt: string;
}

const FIELDS = ["id", "title", "done", "owner", "createdAt"] as const;
type Field = (typeof FIELDS)[number];

const SEED: Task[] = [
  {
    id: "seed-1",
    title: "write the spec",
    done: false,
    owner: "ada",
    createdAt: "2026-01-05T09:00:00.000Z",
  },
  {
    id: "seed-2",
    title: "review the pull request",
    done: true,
    owner: "grace",
    createdAt: "2026-01-06T11:30:00.000Z",
  },
];

type Selection = { ok: true; fields: Field[] | null } | { ok: false; field: string };

/** null means "everything" - an absent parameter and an empty one both mean it. */
function selectionFrom(raw: unknown): Selection {
  if (typeof raw !== "string" || raw.trim() === "") return { ok: true, fields: null };

  const wanted = raw.split(",").map((field) => field.trim());
  for (const field of wanted) {
    if (!(FIELDS as readonly string[]).includes(field)) return { ok: false, field };
  }
  return { ok: true, fields: wanted as Field[] };
}

function project(task: Task, fields: Field[] | null): Partial<Task> {
  if (fields === null) return task;
  // id first and unconditionally: a resource the client cannot identify is not
  // worth sending, and a Set keeps an explicit id from arriving twice.
  const projected: Partial<Task> = { id: task.id };
  for (const field of new Set(fields)) {
    (projected as Record<string, unknown>)[field] = task[field];
  }
  return projected;
}

export function createApp(): Express {
  const app = express();
  const tasks = SEED.map((task) => ({ ...task }));

  app.get("/tasks", (req, res) => {
    const selection = selectionFrom(req.query.fields);
    if (!selection.ok) {
      res.status(400).json({ error: "unknown_field", field: selection.field });
      return;
    }

    const items = tasks.map((task) => project(task, selection.fields));
    res.json({ items, total: tasks.length });
  });

  app.get("/tasks/:id", (req, res) => {
    const selection = selectionFrom(req.query.fields);
    if (!selection.ok) {
      res.status(400).json({ error: "unknown_field", field: selection.field });
      return;
    }

    const task = tasks.find((candidate) => candidate.id === req.params.id);
    if (task === undefined) {
      res.status(404).json({ error: "not_found" });
      return;
    }

    res.json(project(task, selection.fields));
  });

  return app;
}

// d23_rest_patterns / ex3 - reference solution (author only, used by `dojo verify`).
import express, { type Express } from "express";

export interface Problem {
  type: string;
  title: string;
  status: number;
  detail: string;
  instance: string;
}

export interface ProblemInput {
  type?: string;
  title: string;
  status: number;
  detail: string;
  instance: string;
}

export function problem(input: ProblemInput): Problem {
  return {
    // about:blank is what RFC 9457 says to use when the status code is the
    // whole story - it is not a placeholder for a missing value.
    type: input.type ?? "about:blank",
    title: input.title,
    status: input.status,
    detail: input.detail,
    instance: input.instance,
  };
}

/** A failure the API meant to produce, carrying its own problem document. */
export class ProblemError extends Error {
  constructor(readonly problem: Problem) {
    super(problem.detail);
    this.name = "ProblemError";
  }
}

interface Task {
  id: string;
  title: string;
  archived: boolean;
}

export function createApp(logError: (error: unknown) => void = () => {}): Express {
  const app = express();
  app.use(express.json());

  const tasks: Task[] = [{ id: "seed-1", title: "write the spec", archived: true }];

  app.get("/tasks", (req, res) => {
    const status = req.query.status;
    if (status !== undefined && status !== "open" && status !== "done") {
      throw new ProblemError(
        problem({
          title: "Bad Request",
          status: 400,
          detail: "status must be one of open, done",
          instance: req.originalUrl,
        }),
      );
    }
    res.json({ items: tasks });
  });

  app.get("/tasks/:id", (req, res) => {
    const task = tasks.find((candidate) => candidate.id === req.params.id);
    if (task === undefined) {
      throw new ProblemError(
        problem({
          title: "Not Found",
          status: 404,
          detail: `no task with id ${req.params.id}`,
          instance: req.originalUrl,
        }),
      );
    }
    res.json(task);
  });

  app.post("/tasks/:id/archive", (req, res) => {
    const task = tasks.find((candidate) => candidate.id === req.params.id);
    if (task !== undefined && task.archived) {
      throw new ProblemError(
        problem({
          // A type of its own, because a client wants to branch on this one
          // rather than match the title with a regular expression.
          type: "https://example.com/probs/already-archived",
          title: "Conflict",
          status: 409,
          detail: `task ${req.params.id} is already archived`,
          instance: req.originalUrl,
        }),
      );
    }
    if (task === undefined) {
      throw new ProblemError(
        problem({
          title: "Not Found",
          status: 404,
          detail: `no task with id ${req.params.id}`,
          instance: req.originalUrl,
        }),
      );
    }

    task.archived = true;
    res.json(task);
  });

  app.get("/boom", (_req, _res) => {
    throw new Error("connect ECONNREFUSED postgres://api:hunter2@db.internal:5432");
  });

  // One handler at the bottom, and the only place a status code is turned into
  // a response body.
  app.use((error: unknown, req: express.Request, res: express.Response, _next: express.NextFunction) => {
    if (error instanceof ProblemError) {
      res.status(error.problem.status).type("application/problem+json").json(error.problem);
      return;
    }

    // Unexpected: the client is told nothing, the log is told everything.
    logError(error);
    res
      .status(500)
      .type("application/problem+json")
      .json(
        problem({
          title: "Internal Server Error",
          status: 500,
          detail: "an unexpected error occurred",
          instance: req.originalUrl,
        }),
      );
  });

  return app;
}

