import express, { type Express } from "express";

export interface Task {
  id: string;
  title: string;
}

export const DEFAULT_LIMIT = 2;
export const MAX_LIMIT = 3;

const SEED: Task[] = [
  { id: "t-1", title: "write the spec" },
  { id: "t-2", title: "review the pull request" },
  { id: "t-3", title: "draw the diagram" },
  { id: "t-4", title: "record the demo" },
  { id: "t-5", title: "book the room" },
];

/** The cursor is the id of the last row served, and nothing else. */
const encodeCursor = (id: string): string => Buffer.from(id, "utf8").toString("base64url");
const decodeCursor = (cursor: string): string => Buffer.from(cursor, "base64url").toString("utf8");

function limitFrom(raw: unknown): number {
  const parsed = Number(raw);
  if (!Number.isInteger(parsed) || parsed < 1) return DEFAULT_LIMIT;
  // Capped, not obeyed: one client must not be able to ask for everything.
  return Math.min(parsed, MAX_LIMIT);
}

export function createApp(): Express {
  const app = express();
  // Sorted once, and the sort is part of the contract - a cursor only means
  // anything relative to a stable order.
  const tasks = [...SEED].sort((a, b) => a.id.localeCompare(b.id));

  app.get("/tasks", (req, res) => {
    const limit = limitFrom(req.query.limit);

    let start = 0;
    if (typeof req.query.cursor === "string" && req.query.cursor !== "") {
      const after = decodeCursor(req.query.cursor);
      const index = tasks.findIndex((task) => task.id === after);
      if (index === -1) {
        // Decoding cannot fail usefully - base64url of anything is bytes. What
        // makes a cursor valid is that it names a row this collection has.
        res.status(400).json({ error: "invalid_cursor" });
        return;
      }
      start = index + 1;
    }

    const items = tasks.slice(start, start + limit);
    const last = items[items.length - 1];
    const more = last !== undefined && start + items.length < tasks.length;

    res.json({ items, nextCursor: more ? encodeCursor(last.id) : null });
  });

  return app;
}

// d23_rest_patterns / ex5 - reference solution (author only, used by `dojo verify`).
import express, { type Express, type RequestHandler } from "express";

export interface Project {
  id: string;
  name: string;
}

export interface Task {
  id: string;
  projectId: string;
  title: string;
}

export function createApp(): Express {
  const app = express();
  app.use(express.json());

  const projects: Project[] = [
    { id: "p-1", name: "Website" },
    { id: "p-2", name: "Mobile" },
  ];
  const tasks: Task[] = [
    { id: "t-1", projectId: "p-1", title: "draw the wireframes" },
    { id: "t-2", projectId: "p-2", title: "choose a crash reporter" },
  ];
  let nextId = 1;

  // The parent is checked once, in front of every nested route. Repeating it
  // per route is how one of them ends up without it.
  const requireProject: RequestHandler = (req, res, next) => {
    const exists = projects.some((project) => project.id === req.params.projectId);
    if (!exists) {
      res.status(404).json({ error: "project_not_found" });
      return;
    }
    next();
  };

  app.get("/projects/:projectId/tasks", requireProject, (req, res) => {
    const items = tasks.filter((task) => task.projectId === req.params.projectId);
    res.json({ items, total: items.length });
  });

  app.post("/projects/:projectId/tasks", requireProject, (req, res) => {
    const title = (req.body as { title?: unknown }).title;
    if (typeof title !== "string" || title === "") {
      res.status(400).json({ error: "invalid_body" });
      return;
    }

    const task: Task = { id: `task-${nextId}`, projectId: req.params.projectId, title };
    nextId += 1;
    tasks.push(task);
    // The nested url, because that is where the resource actually lives.
    res.status(201).location(`/projects/${task.projectId}/tasks/${task.id}`).json(task);
  });

  app.get("/projects/:projectId/tasks/:id", requireProject, (req, res) => {
    const task = tasks.find(
      // BOTH halves. Looking the task up by id alone is the bug that shows one
      // customer another customer data through a url they guessed.
      (candidate) =>
        candidate.id === req.params.id && candidate.projectId === req.params.projectId,
    );
    if (task === undefined) {
      res.status(404).json({ error: "not_found" });
      return;
    }
    res.json(task);
  });

  return app;
}

// d23_rest_patterns / ex6 - reference solution (author only, used by `dojo verify`).
import express, { type Express } from "express";

export interface Payment {
  id: string;
  amount: number;
}

/** What was answered the first time a key was seen. */
interface Recorded {
  fingerprint: string;
  status: number;
  body: unknown;
}

export function createApp(): Express {
  const app = express();
  app.use(express.json());

  const payments: Payment[] = [];
  const seen = new Map<string, Recorded>();
  let nextId = 1;

  app.get("/payments", (_req, res) => {
    res.json(payments);
  });

  app.post("/payments", (req, res) => {
    const key = req.get("idempotency-key");
    const fingerprint = JSON.stringify(req.body ?? null);

    if (key !== undefined) {
      const previous = seen.get(key);
      if (previous !== undefined) {
        if (previous.fingerprint !== fingerprint) {
          // Replaying the old answer would tell the client that THIS request
          // succeeded, when it was never attempted.
          res.status(409).json({ error: "idempotency_key_reuse" });
          return;
        }
        // The original answer, unchanged, plus the one header that lets the
        // client tell a retry that worked from a charge that happened twice.
        res.status(previous.status).set("Idempotency-Replayed", "true").json(previous.body);
        return;
      }
    }

    const amount = (req.body as { amount?: unknown }).amount;
    if (typeof amount !== "number") {
      res.status(400).json({ error: "invalid_body" });
      return;
    }

    const payment: Payment = { id: `pay-${nextId}`, amount };
    nextId += 1;
    payments.push(payment);

    // Record the answer, not just the fact that the key was used.
    if (key !== undefined) seen.set(key, { fingerprint, status: 201, body: payment });
    res.status(201).json(payment);
  });

  return app;
}

// d23_rest_patterns / ex7 - reference solution (author only, used by `dojo verify`).
import express, { type Express } from "express";

export interface Task {
  id: string;
  title: string;
}

export type Operation =
  | { op: "create"; title: string }
  | { op: "update"; id: string; title: string }
  | { op: "delete"; id: string };

interface Rejection {
  index: number;
  reason: string;
}

/**
 * Walk the batch as if it were running, against a copy of the id set, and
 * report the first operation that could not be applied.
 *
 * Checking every operation against the ORIGINAL state is the tempting version
 * and it is wrong: two deletes of the same id both pass, and the second one
 * then fails half way through applying the batch.
 */
function reject(operations: unknown[], ids: string[]): Rejection | null {
  const live = new Set(ids);

  for (let index = 0; index < operations.length; index += 1) {
    const operation = operations[index] as Partial<Operation> & { op?: unknown };

    if (operation?.op === "create") {
      if (typeof operation.title !== "string" || operation.title === "") {
        return { index, reason: "create needs a title" };
      }
      continue;
    }

    if (operation?.op === "update" || operation?.op === "delete") {
      const id = (operation as { id?: unknown }).id;
      if (typeof id !== "string" || !live.has(id)) {
        return { index, reason: `no such task: ${String(id)}` };
      }
      if (operation.op === "update" && (typeof operation.title !== "string" || operation.title === "")) {
        return { index, reason: "update needs a title" };
      }
      if (operation.op === "delete") live.delete(id);
      continue;
    }

    return { index, reason: `unknown operation: ${String(operation?.op)}` };
  }

  return null;
}

export function createApp(): Express {
  const app = express();
  app.use(express.json());

  const tasks: Task[] = [
    { id: "t-1", title: "write the spec" },
    { id: "t-2", title: "review the pull request" },
  ];
  let nextId = 1;

  app.get("/tasks", (_req, res) => {
    res.json(tasks);
  });

  app.post("/tasks/bulk", (req, res) => {
    const operations = (req.body as { operations?: unknown }).operations;
    if (!Array.isArray(operations)) {
      res.status(400).json({ error: "invalid_body" });
      return;
    }

    const rejection = reject(operations, tasks.map((task) => task.id));
    if (rejection !== null) {
      // Nothing has been touched yet, which is the whole point of checking
      // first: the client is told no and the store is exactly as it was.
      res.status(422).json({ error: "bulk_failed", ...rejection });
      return;
    }

    const results = (operations as Operation[]).map((operation) => {
      if (operation.op === "create") {
        const task: Task = { id: `task-${nextId}`, title: operation.title };
        nextId += 1;
        tasks.push(task);
        return { op: "create", id: task.id };
      }

      if (operation.op === "update") {
        const task = tasks.find((candidate) => candidate.id === operation.id);
        if (task !== undefined) task.title = operation.title;
        return { op: "update", id: operation.id };
      }

      const index = tasks.findIndex((candidate) => candidate.id === operation.id);
      if (index !== -1) tasks.splice(index, 1);
      return { op: "delete", id: operation.id };
    });

    res.json({ results });
  });

  return app;
}

// d23_rest_patterns / ex8 - reference solution (author only, used by `dojo verify`).
import express, { type Express, type Request, type Response } from "express";

export interface Subtask {
  id: string;
  title: string;
  done: boolean;
}

export interface Task {
  id: string;
  title: string;
  status: "open" | "done";
  subtasks: Subtask[];
}

export interface Deps {
  seed?: Task[];
}

interface Problem {
  type: string;
  title: string;
  status: number;
  detail: string;
  instance: string;
}

const FIELDS = ["id", "title", "status", "subtasks"] as const;
type Field = (typeof FIELDS)[number];

const DEFAULT_LIMIT = 2;
const MAX_LIMIT = 3;

const DEFAULT_SEED: Task[] = [
  { id: "t-1", title: "write the spec", status: "open", subtasks: [] },
  { id: "t-2", title: "review the pull request", status: "open", subtasks: [] },
];

/** Every failure in this service goes out through here. */
function sendProblem(
  res: Response,
  req: Request,
  parts: { type?: string; title: string; status: number; detail: string },
): void {
  const problem: Problem = {
    type: parts.type ?? "about:blank",
    title: parts.title,
    status: parts.status,
    detail: parts.detail,
    instance: req.originalUrl,
  };
  res.status(problem.status).type("application/problem+json").json(problem);
}

const encodeCursor = (id: string): string => Buffer.from(id, "utf8").toString("base64url");
const decodeCursor = (cursor: string): string => Buffer.from(cursor, "base64url").toString("utf8");

function project(task: Task, fields: Field[] | null): Partial<Task> {
  if (fields === null) return task;
  const projected: Partial<Task> = { id: task.id };
  for (const field of new Set(fields)) {
    (projected as Record<string, unknown>)[field] = task[field];
  }
  return projected;
}

export function createApp(deps: Deps = {}): Express {
  const app = express();
  app.use(express.json());

  // A copy, so a caller cannot mutate the service by holding on to its seed.
  const tasks: Task[] = (deps.seed ?? DEFAULT_SEED).map((task) => ({
    ...task,
    subtasks: task.subtasks.map((subtask) => ({ ...subtask })),
  }));
  let nextId = 1;

  app.get("/tasks", (req, res) => {
    const rawFields = req.query.fields;
    let fields: Field[] | null = null;
    if (typeof rawFields === "string" && rawFields.trim() !== "") {
      const wanted = rawFields.split(",").map((field) => field.trim());
      const unknown = wanted.find((field) => !(FIELDS as readonly string[]).includes(field));
      if (unknown !== undefined) {
        sendProblem(res, req, {
          title: "Bad Request",
          status: 400,
          detail: `unknown field ${unknown}`,
        });
        return;
      }
      fields = wanted as Field[];
    }

    const parsed = Number(req.query.limit);
    const limit = Number.isInteger(parsed) && parsed >= 1 ? Math.min(parsed, MAX_LIMIT) : DEFAULT_LIMIT;

    let start = 0;
    if (typeof req.query.cursor === "string" && req.query.cursor !== "") {
      const index = tasks.findIndex((task) => task.id === decodeCursor(req.query.cursor as string));
      if (index === -1) {
        sendProblem(res, req, {
          title: "Bad Request",
          status: 400,
          detail: "cursor does not name a task in this collection",
        });
        return;
      }
      start = index + 1;
    }

    const page = tasks.slice(start, start + limit);
    const last = page[page.length - 1];
    const more = last !== undefined && start + page.length < tasks.length;

    res.json({
      items: page.map((task) => project(task, fields)),
      nextCursor: more ? encodeCursor(last.id) : null,
    });
  });

  app.post("/tasks", (req, res) => {
    const title = (req.body as { title?: unknown }).title;
    if (typeof title !== "string" || title === "") {
      sendProblem(res, req, { title: "Bad Request", status: 400, detail: "title is required" });
      return;
    }

    const task: Task = { id: `task-${nextId}`, title, status: "open", subtasks: [] };
    nextId += 1;
    tasks.push(task);
    res.status(201).location(`/tasks/${task.id}`).json(task);
  });

  app.get("/tasks/:id", (req, res) => {
    const task = tasks.find((candidate) => candidate.id === req.params.id);
    if (task === undefined) {
      sendProblem(res, req, {
        title: "Not Found",
        status: 404,
        detail: `no task with id ${req.params.id}`,
      });
      return;
    }
    res.json(task);
  });

  app.patch("/tasks/:id", (req, res) => {
    const task = tasks.find((candidate) => candidate.id === req.params.id);
    if (task === undefined) {
      sendProblem(res, req, {
        title: "Not Found",
        status: 404,
        detail: `no task with id ${req.params.id}`,
      });
      return;
    }

    const patch = req.body as { title?: unknown; status?: unknown };
    if (patch.status === "done") {
      const open = task.subtasks.filter((subtask) => !subtask.done);
      if (open.length > 0) {
        // The request was perfectly well formed; the state of the world is
        // what refused it. That is a 409, not a 400.
        sendProblem(res, req, {
          type: "https://example.com/probs/open-subtasks",
          title: "Conflict",
          status: 409,
          detail: `task ${task.id} still has ${open.length} open subtask(s)`,
        });
        return;
      }
    }

    if (typeof patch.title === "string" && patch.title !== "") task.title = patch.title;
    if (patch.status === "open" || patch.status === "done") task.status = patch.status;
    res.json(task);
  });

  app.patch("/tasks/:id/subtasks/:subtaskId", (req, res) => {
    const task = tasks.find((candidate) => candidate.id === req.params.id);
    const subtask = task?.subtasks.find((candidate) => candidate.id === req.params.subtaskId);
    if (task === undefined || subtask === undefined) {
      sendProblem(res, req, {
        title: "Not Found",
        status: 404,
        detail: `no subtask ${req.params.subtaskId} on task ${req.params.id}`,
      });
      return;
    }

    const done = (req.body as { done?: unknown }).done;
    if (typeof done !== "boolean") {
      sendProblem(res, req, { title: "Bad Request", status: 400, detail: "done must be a boolean" });
      return;
    }

    subtask.done = done;
    res.json(task);
  });

  app.delete("/tasks/:id", (req, res) => {
    const index = tasks.findIndex((candidate) => candidate.id === req.params.id);
    if (index === -1) {
      sendProblem(res, req, {
        title: "Not Found",
        status: 404,
        detail: `no task with id ${req.params.id}`,
      });
      return;
    }

    tasks.splice(index, 1);
    res.status(204).end();
  });

  // An unmatched route is a failure like any other, in the same shape.
  app.use((req, res) => {
    sendProblem(res, req, { title: "Not Found", status: 404, detail: "no such route" });
  });

  return app;
}

lessons.fullReadme:
# d24 — The mixed gauntlet

The last set. Nothing here belongs to one lesson: every problem needs two or
three parts of the track at once, the way real code does — a limiter and a retry
policy and a clock, a stream and a schema, an HTTP route and a file handle. If a
problem stalls, the fix is almost never a new idea; it is remembering which of
the eight drills that came before it already answered half the question.

The rules are the ones you have been working under all along. Anything counted
is held open by the gate and released by hand. Anything timed takes an injected
clock. Streams stay in memory, HTTP is driven through supertest with no port,
and anything that touches the disk gets a temp directory and gives it back.

## Problem 1 — configuration, layered and frozen

Edit `ex1/solution.ts`. `loadConfig(dir, { env })` reads `config.json`,
deep-merges `config.<env>.json` over it when that file exists, and returns the
result deeply frozen. Objects merge key by key; arrays and scalars are replaced.
A missing base file, or one that will not parse, rejects with a message naming
the file. *(filesystem + paths + immutability)*

```
uv run dojo test node d24_mixed_gauntlet ex1
```

## Problem 2 — a limiter that retries without growing

Edit `ex2/solution.ts`. `retryingLimitedMap(items, worker, { limit, retries,
delayFor, sleep })` keeps at most `limit` items in flight, retries a failing item
**inside the slot it already holds**, waits `delayFor(attempt)` on the injected
`sleep` between attempts, returns results in input order, and fails the whole
call — starting nothing further — when an item runs out of attempts.
*(concurrency + retry policy + injected time)*

```
uv run dojo test node d24_mixed_gauntlet ex2
```

## Problem 3 — the end of a very large file

Edit `ex3/solution.ts`. `tailLines(file, n)` returns the last `n` lines in file
order, without their line endings, by reading the file **backwards** a block at a
time. A trailing newline does not produce an empty last line; a file that ends
without one still has a last line; `\r\n` is a line ending.
*(filesystem handles + buffers)*

```
uv run dojo test node d24_mixed_gauntlet ex3
```

## Problem 4 — a pipeline that says what it is doing

Edit `ex4/solution.ts`. `runNamedPipeline(source, stages, sink, emitter)` runs
the chain, emits `progress` with `{ done }` for every item that reaches the sink,
and resolves with the total. A failing stage rejects with a `StageFailure` whose
`stage` is that stage's name and whose `cause` is the original error, and emits
`failed` with the same object. *(streams + events + custom errors)*

```
uv run dojo test node d24_mixed_gauntlet ex4
```

## Problem 5 — a schema in the middle of a stream

Edit `ex5/solution.ts`. `createValidatingStage(schema, { onInvalid, failFast })`
is an object-mode Transform: records the schema accepts are pushed as the
**parsed** value, records it rejects go to `onInvalid` with their index in the
input and their issues — or, with `failFast`, fail the stream with a message
naming the record. *(streams + zod validation)*

```
uv run dojo test node d24_mixed_gauntlet ex5
```

## Problem 6 — an upload endpoint

Edit `ex6/solution.ts`. `createApp({ dir, limit, nextId })` serves `POST
/uploads`, streaming the raw request body to a file — no body parser — and
answering 201 with `{ id, bytes }` and a Location header. Over `limit` bytes it
answers 413 and leaves nothing on disk. `GET /uploads/:id` answers `{ id, bytes }`
or 404. *(HTTP + streams + filesystem)*

```
uv run dojo test node d24_mixed_gauntlet ex6
```

## Problem 7 — a client that knows when to stop calling

Edit `ex7/solution.ts`. `createResilientClient({ call, failureThreshold,
cooldownMs, now })` returns `{ get, state }`. Callers sharing a key while one
call is in flight share its outcome; `failureThreshold` consecutive failures open
the circuit, which then rejects with `CircuitOpenError` without calling anything;
after `cooldownMs` on the injected clock exactly one probe is allowed through,
and its outcome closes or re-opens the circuit.
*(de-duplication + circuit breaking + injected time + custom errors)*

```
uv run dojo test node d24_mixed_gauntlet ex7
```

## Problem 8 — the gateway

Edit `ex8/solution.ts`. `createApp({ apiKey, upstream, logError })` guards every
request on `x-api-key` (401 in the shared JSON shape), mounts a router at
`/api/v1` with `GET /orders` returning `{ items, total }`, `GET /orders/export`
streaming NDJSON, and `GET /orders/:id`; answers 404 in the same shape for
anything unmatched; and turns an upstream rejection into a 502 that leaks
nothing, logged once in full. *(express + routing + middleware + error handling +
streams)*

```
uv run dojo test node d24_mixed_gauntlet ex8
```

## The gate

This is the entire gate, `gate.test.ts`:

```ts
// Gate for node/d24_mixed_gauntlet. Quoted verbatim in README.md.
//
// The last set in the track, and the only one where every problem needs two or
// three parts of it at once. The rules do not change: work that has to be
// counted is held open by the gate and released by hand, anything timed takes
// an injected clock, streams live in memory, HTTP is driven through supertest
// with no fixed port, and anything that touches the disk gets its own directory
// under the OS temp dir and gives it back.
import { mkdtemp, readFile, readdir, rm, writeFile } from "node:fs/promises";
import { EventEmitter } from "node:events";
import { tmpdir } from "node:os";
import path from "node:path";
import { Readable, Transform, Writable } from "node:stream";
import { pipeline } from "node:stream/promises";
import request from "supertest";
import { describe, expect, test, vi } from "vitest";
import { z } from "zod";

import { loadConfig } from "./ex1/solution";
import { retryingLimitedMap } from "./ex2/solution";
import { tailLines } from "./ex3/solution";
import { StageFailure, runNamedPipeline } from "./ex4/solution";
import { createValidatingStage } from "./ex5/solution";
import { createApp as createUploads } from "./ex6/solution";
import { CircuitOpenError, createResilientClient } from "./ex7/solution";
import { createApp as createGateway } from "./ex8/solution";

const settle = () => new Promise<void>((resolve) => setTimeout(resolve, 0));

async function withTempDir<T>(run: (dir: string) => Promise<T>): Promise<T> {
  const dir = await mkdtemp(path.join(tmpdir(), "dojo-d24-"));
  try {
    return await run(dir);
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
}

/** An object-mode sink that keeps everything it was given. */
function sink(): { stream: Writable; items: unknown[] } {
  const items: unknown[] = [];
  const stream = new Writable({
    objectMode: true,
    write(chunk, _encoding, callback) {
      items.push(chunk);
      callback();
    },
  });
  return { stream, items };
}

/** Units of work the gate starts by name, counts, and settles by call number. */
function callDesk<T = string>() {
  const started: string[] = [];
  const settlers: ((outcome: { ok: boolean; value?: T; error?: unknown }) => void)[] = [];
  let active = 0;
  let maxActive = 0;

  const start = (name: string): Promise<T> => {
    started.push(name);
    active += 1;
    maxActive = Math.max(maxActive, active);
    return new Promise<T>((resolve, reject) => {
      settlers.push((outcome) => {
        active -= 1;
        if (outcome.ok) resolve(outcome.value as T);
        else reject(outcome.error);
      });
    });
  };

  return {
    start,
    started,
    maxActive: () => maxActive,
    finish: (index: number, value: T) => settlers[index]({ ok: true, value }),
    fail: (index: number, error: unknown) => settlers[index]({ ok: false, error }),
  };
}

describe("d24_mixed_gauntlet", () => {
  test("ex1 - loadConfig() layers two files and hands back something nobody can edit", async () => {
    await withTempDir(async (dir) => {
      await writeFile(
        path.join(dir, "config.json"),
        JSON.stringify({
          service: "orders",
          server: { host: "localhost", port: 3000, tls: false },
          regions: ["eu-west", "us-east"],
        }),
        "utf8",
      );
      await writeFile(
        path.join(dir, "config.prod.json"),
        JSON.stringify({ server: { host: "orders.internal", tls: true }, regions: ["eu-west"] }),
        "utf8",
      );

      const base = await loadConfig(dir);
      expect(
        base.server,
        "with no env asked for, the overlay is not even looked at",
      ).toEqual({ host: "localhost", port: 3000, tls: false });

      const prod = await loadConfig(dir, { env: "prod" });
      expect(
        prod.server,
        "objects merge KEY BY KEY, all the way down: prod says nothing about " +
          "port, so port survives. A shallow spread would have replaced the " +
          "whole server object and taken the port with it",
      ).toEqual({ host: "orders.internal", port: 3000, tls: true });
      expect(
        prod.regions,
        "an array is a value, not a thing to merge - the overlay replaces it " +
          "outright, because merging arrays leaves nobody able to remove an entry",
      ).toEqual(["eu-west"]);
      expect(prod.service, "keys the overlay never mentions come through").toBe("orders");

      expect(Object.isFrozen(prod), "the config is frozen").toBe(true);
      expect(
        Object.isFrozen(prod.server as object),
        "and frozen all the way down. A shallow freeze protects the top level " +
          "and lets any module in the process rewrite config.server.host at " +
          "runtime, which is a bug you will debug for a day",
      ).toBe(true);

      const missingEnv = await loadConfig(dir, { env: "staging" });
      expect(
