// d24_mixed_gauntlet / ex1 - reference solution (author only, used by `dojo verify`).
import { readFile } from "node:fs/promises";
import path from "node:path";

export type Config = Record<string, unknown>;

export interface LoadOptions {
  env?: string;
}

function isPlainObject(value: unknown): value is Config {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/** Objects merge key by key; anything else - arrays included - is replaced. */
function merge(base: Config, overlay: Config): Config {
  const merged: Config = { ...base };
  for (const [key, value] of Object.entries(overlay)) {
    const previous = merged[key];
    merged[key] =
      isPlainObject(previous) && isPlainObject(value) ? merge(previous, value) : value;
  }
  return merged;
}

function deepFreeze<T>(value: T): T {
  if (isPlainObject(value) || Array.isArray(value)) {
    for (const member of Object.values(value as object)) deepFreeze(member);
    Object.freeze(value);
  }
  return value;
}

/** The parsed file, or null when it is simply not there. */
async function readJsonFile(file: string): Promise<Config | null> {
  let text: string;
  try {
    text = await readFile(file, "utf8");
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return null;
    throw error;
  }
  try {
    return JSON.parse(text) as Config;
  } catch {
    throw new Error(`invalid JSON in ${path.basename(file)}`);
  }
}

export async function loadConfig(dir: string, options: LoadOptions = {}): Promise<Readonly<Config>> {
  const base = await readJsonFile(path.join(dir, "config.json"));
  if (base === null) throw new Error("missing config.json");

  let merged = base;
  if (options.env !== undefined) {
    const overlay = await readJsonFile(path.join(dir, `config.${options.env}.json`));
    if (overlay !== null) merged = merge(base, overlay);
  }

  return deepFreeze(merged);
}

// d24_mixed_gauntlet / ex2 - reference solution (author only, used by `dojo verify`).

export interface RetryLimitOptions {
  limit: number;
  retries: number;
  delayFor: (attempt: number) => number;
  sleep: (ms: number) => Promise<void>;
}

export async function retryingLimitedMap<T, R>(
  items: readonly T[],
  worker: (item: T, index: number) => Promise<R>,
  options: RetryLimitOptions,
): Promise<R[]> {
  const { limit, retries, delayFor, sleep } = options;
  const results = new Array<R>(items.length);
  let next = 0;
  //: set by the first item that runs out of attempts; stops the other runners
  //: from taking any more work.
  let failed: unknown = null;

  const runner = async (): Promise<void> => {
    while (failed === null) {
      const index = next;
      if (index >= items.length) return;
      next += 1;

      // The retry loop is INSIDE the slot: nothing else starts while this item
      // is waiting to try again.
      for (let attempt = 1; ; attempt += 1) {
        try {
          results[index] = await worker(items[index], index);
          break;
        } catch (error) {
          if (attempt > retries || failed !== null) {
            failed = error;
            throw error;
          }
          await sleep(delayFor(attempt));
        }
      }
    }
  };

  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, () => runner()));
  return results;
}

// d24_mixed_gauntlet / ex3 - reference solution (author only, used by `dojo verify`).
import { open } from "node:fs/promises";

const BLOCK = 64;

export async function tailLines(file: string, n: number): Promise<string[]> {
  if (n <= 0) return [];

  const handle = await open(file, "r");
  try {
    const { size } = await handle.stat();
    if (size === 0) return [];

    const blocks: Buffer[] = [];
    let position = size;
    let newlines = 0;

    // Keep walking back until there are more newlines than lines wanted: the
    // extra one is what proves the first line in the region is complete.
    while (position > 0 && newlines <= n) {
      const length = Math.min(BLOCK, position);
      position -= length;
      const buffer = Buffer.alloc(length);
      await handle.read(buffer, 0, length, position);
      blocks.unshift(buffer);
      for (const byte of buffer) if (byte === 0x0a) newlines += 1;
    }

    // Concatenate the BYTES and decode once: a block boundary lands in the
    // middle of a multi-byte character sooner or later.
    const text = Buffer.concat(blocks).toString("utf8");
    const lines = text.split("\n").map((line) => line.replace(/\r$/, ""));
    if (lines[lines.length - 1] === "") lines.pop();
    return lines.slice(Math.max(0, lines.length - n));
  } finally {
    await handle.close();
  }
}

// d24_mixed_gauntlet / ex4 - reference solution (author only, used by `dojo verify`).
import type { EventEmitter } from "node:events";
import { Transform, type Duplex, type Readable, type Writable } from "node:stream";
import { pipeline } from "node:stream/promises";

export class StageFailure extends Error {
  readonly stage: string;

  constructor(stage: string, cause: unknown) {
    super(`stage ${stage} failed`, { cause });
    this.name = "StageFailure";
    this.stage = stage;
  }
}

export interface NamedStage {
  name: string;
  stream: Duplex;
}

export function runNamedPipeline(
  source: Readable,
  stages: readonly NamedStage[],
  sink: Writable,
  emitter: EventEmitter,
): Promise<number> {
  let done = 0;
  // The counter sits immediately before the sink, so "done" means "arrived",
  // not "was read".
  const counter = new Transform({
    objectMode: true,
    transform(chunk, _encoding, callback) {
      done += 1;
      emitter.emit("progress", { done });
      callback(null, chunk);
    },
  });

  // A stream error carries no idea which stream produced it, so ask each one.
  let culprit: string | null = null;
  for (const stage of stages) {
    stage.stream.on("error", () => {
      if (culprit === null) culprit = stage.name;
    });
  }

  return pipeline([source, ...stages.map((stage) => stage.stream), counter, sink]).then(
    () => done,
    (error: unknown) => {
      const failure = new StageFailure(culprit ?? "pipeline", error);
      emitter.emit("failed", failure);
      throw failure;
    },
  );
}

// d24_mixed_gauntlet / ex5 - reference solution (author only, used by `dojo verify`).
import { Transform } from "node:stream";
import type { ZodSchema } from "zod";

export interface InvalidRecord {
  index: number;
  value: unknown;
  issues: { path: string; message: string }[];
}

export interface ValidatingOptions {
  onInvalid?: (record: InvalidRecord) => void;
  failFast?: boolean;
}

export function createValidatingStage<T>(
  schema: ZodSchema<T>,
  options: ValidatingOptions = {},
): Transform {
  //: counts every record that arrived, valid or not - it is a position in the
  //: input file, not a count of the ones that got through.
  let index = 0;

  return new Transform({
    objectMode: true,
    transform(chunk, _encoding, callback) {
      const position = index;
      index += 1;

      const result = schema.safeParse(chunk);
      if (result.success) {
        // The PARSED value, so the schema's stripping and coercion actually
        // reach the sink.
        callback(null, result.data);
        return;
      }

      const issues = result.error.issues.map((issue) => ({
        path: issue.path.join("."),
        message: issue.message,
      }));

      if (options.failFast === true) {
        callback(new Error(`record ${position} failed validation: ${issues[0]?.path}`));
        return;
      }

      options.onInvalid?.({ index: position, value: chunk, issues });
      // Not pushing anything is how a Transform drops a record.
      callback();
    },
  });
}

// d24_mixed_gauntlet / ex6 - reference solution (author only, used by `dojo verify`).
import { createWriteStream } from "node:fs";
import { rm } from "node:fs/promises";
import path from "node:path";
import express, { type Express } from "express";

export interface UploadDeps {
  dir: string;
  limit: number;
  nextId: () => string;
}

export function createApp(deps: UploadDeps): Express {
  const app = express();
  //: id -> bytes stored. No express.json() anywhere: a body parser here would
  //: read the whole upload into memory before the route ever saw it.
  const stored = new Map<string, number>();

  app.post("/uploads", (req, res, next) => {
    const id = deps.nextId();
    const file = path.join(deps.dir, id);
    const out = createWriteStream(file);
    let size = 0;
    let tooLarge = false;

    req.on("data", (chunk: Buffer) => {
      size += chunk.length;
      // Past the limit: keep draining the request, but stop keeping the bytes.
      if (size > deps.limit) {
        tooLarge = true;
        return;
      }
      out.write(chunk);
    });

    req.on("error", next);

    req.on("end", () => {
      out.end(() => {
        if (!tooLarge) {
          stored.set(id, size);
          res.setHeader("location", `/uploads/${id}`);
          res.status(201).json({ id, bytes: size });
          return;
        }
        rm(file, { force: true }).then(() => {
          res.status(413).json({ error: "payload_too_large" });
        }, next);
      });
    });
  });

  app.get("/uploads/:id", (req, res) => {
    const bytes = stored.get(req.params.id);
    if (bytes === undefined) {
      res.status(404).json({ error: "not_found" });
      return;
    }
    res.json({ id: req.params.id, bytes });
  });

  return app;
}

// d24_mixed_gauntlet / ex7 - reference solution (author only, used by `dojo verify`).

export class CircuitOpenError extends Error {
  constructor(message = "circuit is open") {
    super(message);
    this.name = "CircuitOpenError";
  }
}

export interface ClientOptions<T> {
  call: (key: string) => Promise<T>;
  failureThreshold: number;
  cooldownMs: number;
  now: () => number;
}

export interface ResilientClient<T> {
  get(key: string): Promise<T>;
  state(): "closed" | "open" | "half-open";
}

export function createResilientClient<T>(options: ClientOptions<T>): ResilientClient<T> {
  //: key -> the flight every caller for that key is sharing
  const inFlight = new Map<string, Promise<T>>();
  let failures = 0;
  let openedAt: number | null = null;
  let probing = false;

  const state = (): "closed" | "open" | "half-open" => {
    if (openedAt === null) return "closed";
    return options.now() - openedAt >= options.cooldownMs ? "half-open" : "open";
  };

  const get = (key: string): Promise<T> => {
    const existing = inFlight.get(key);
    if (existing !== undefined) return existing;

    const current = state();
    if (current === "open") return Promise.reject(new CircuitOpenError());
    if (current === "half-open") {
      // Exactly one probe: the rest keep failing fast until it has answered.
      if (probing) return Promise.reject(new CircuitOpenError());
      probing = true;
    }

    const flight = options
      .call(key)
      .then(
        (value) => {
          failures = 0;
          openedAt = null;
          probing = false;
          return value;
        },
        (error: unknown) => {
          probing = false;
          failures += 1;
          // Reaching the threshold opens it; a failed probe re-opens it and
          // restarts the cooldown from now.
          if (failures >= options.failureThreshold || openedAt !== null) {
            openedAt = options.now();
          }
          throw error;
        },
      )
      .finally(() => {
        inFlight.delete(key);
      });

    inFlight.set(key, flight);
    return flight;
  };

  return { get, state };
}

// d24_mixed_gauntlet / ex8 - reference solution (author only, used by `dojo verify`).
import { pipeline } from "node:stream/promises";
import express, { Router, type Express, type NextFunction, type Request, type Response } from "express";

export interface Order {
  id: string;
  item: string;
  amount: number;
}

export interface GatewayDeps {
  apiKey: string;
  upstream: { listOrders: () => Promise<Order[]> };
  logError: (error: unknown) => void;
}

class UpstreamError extends Error {
  constructor(cause: unknown) {
    super("upstream failed", { cause });
    this.name = "UpstreamError";
  }
}

export function createApp(deps: GatewayDeps): Express {
  const app = express();

  app.use((req, res, next) => {
    if (req.get("x-api-key") !== deps.apiKey) {
      res.status(401).json({ error: "unauthorized" });
      return;
    }
    next();
  });

  const api = Router();

  const load = async (): Promise<Order[]> => {
    try {
      return await deps.upstream.listOrders();
    } catch (error) {
      throw new UpstreamError(error);
    }
  };

  api.get("/orders", async (_req, res) => {
    const orders = await load();
    res.json({ items: orders, total: orders.length });
  });

  // Registered BEFORE /orders/:id, or "export" is just another order id.
  api.get("/orders/export", async (_req, res) => {
    const orders = await load();
    res.setHeader("content-type", "application/x-ndjson");
    await pipeline(
      (async function* () {
        for (const order of orders) yield `${JSON.stringify(order)}\n`;
      })(),
      res,
    );
  });

  api.get("/orders/:id", async (req, res) => {
    const orders = await load();
    const order = orders.find((candidate) => candidate.id === req.params.id);
    if (order === undefined) {
      res.status(404).json({ error: "not_found" });
      return;
    }
    res.json(order);
  });

  app.use("/api/v1", api);

  app.use((_req, res) => {
    res.status(404).json({ error: "not_found" });
  });

  // Four arguments: this is the error handler, and it is the only place a
  // status is chosen for a failure.
  app.use((error: unknown, _req: Request, res: Response, _next: NextFunction) => {
    deps.logError(error);
    if (error instanceof UpstreamError) {
      res.status(502).json({ error: "upstream_failed" });
      return;
    }
    res.status(500).json({ error: "internal_error" });
  });

  return app;
}

