import express, { type Express, type RequestHandler } from "express";

export interface BucketOptions {
  capacity: number;
  refillPerSecond: number;
  now: () => number;
}

export function createTokenBucket(options: BucketOptions): RequestHandler {
  let tokens = options.capacity;
  let lastRefill = options.now();

  return (_req, res, next) => {
    const time = options.now();
    const gained = ((time - lastRefill) / 1000) * options.refillPerSecond;
    // The cap is the whole point: an uncapped bucket lets an idle client
    // build up an unlimited burst.
    tokens = Math.min(options.capacity, tokens + gained);
    lastRefill = time;

    if (tokens < 1) {
      const seconds = (1 - tokens) / options.refillPerSecond;
      res.setHeader("retry-after", String(Math.max(1, Math.ceil(seconds))));
      res.status(429).json({ error: "too many requests" });
      return;
    }

    tokens -= 1;
    res.setHeader("x-ratelimit-limit", String(options.capacity));
    res.setHeader("x-ratelimit-remaining", String(Math.floor(tokens)));
    next();
  };
}

export function createApp(options: BucketOptions): Express {
  const app = express();
  app.use(createTokenBucket(options));
  app.get("/ping", (_req, res) => {
    res.json({ pong: true });
  });
  return app;
}

// i2_interview_drills / ex5 - reference solution (author only, used by `dojo verify`).

export type Callback<T> = (error: Error | null, value?: T) => void;

export function promisify<A, T>(
  fn: (arg: A, callback: Callback<T>) => void,
): (arg: A) => Promise<T> {
  return (arg: A) =>
    new Promise<T>((resolve, reject) => {
      fn(arg, (error, value) => {
        if (error) reject(error);
        else resolve(value as T);
      });
    });
}

export function callbackify<A, T>(
  fn: (arg: A) => Promise<T>,
): (arg: A, callback: Callback<T>) => void {
  return (arg: A, callback: Callback<T>): void => {
    // then() always calls back asynchronously, even for an already-settled
    // promise, which is exactly the guarantee the convention needs.
    fn(arg).then(
      (value) => callback(null, value),
      (error: unknown) => callback(error instanceof Error ? error : new Error(String(error))),
    );
  };
}

// i2_interview_drills / ex6 - reference solution (author only, used by `dojo verify`).
import { Transform } from "node:stream";
import { StringDecoder } from "node:string_decoder";

const REPLACEMENT = "[REDACTED]";

export function createRedactor(secret: string): Transform {
  const decoder = new StringDecoder("utf8");
  // Anything shorter than the secret could still be the start of a match, so
  // it has to wait for the next chunk.
  const keepBack = Math.max(0, secret.length - 1);
  let pending = "";

  return new Transform({
    transform(chunk: Buffer, _encoding, callback) {
      pending = (pending + decoder.write(chunk)).split(secret).join(REPLACEMENT);

      if (pending.length > keepBack) {
        const safe = pending.slice(0, pending.length - keepBack);
        pending = pending.slice(pending.length - keepBack);
        this.push(safe);
      }
      callback();
    },

    flush(callback) {
      pending = (pending + decoder.end()).split(secret).join(REPLACEMENT);
      if (pending.length > 0) this.push(pending);
      callback();
    },
  });
}

exercises.importantHints:
## Hint 1

Start from the plain emitter you built in lesson 04: a
`Map<string, Listener[]>`, `on` appends, `off` removes by identity, `emit`
walks a **copy** of the array so a listener that unsubscribes itself does not
skip the next one.

Then add the two things that are new here: wildcards, and a return value from
`emit`.

## Hint 2

A wildcard listener is registered under the literal key `"*"` and is called
for every event - but with the event name as its **first** argument, ahead of
the payload. So `emit` has two passes: the exact listeners with `...args`, and
then the `"*"` listeners with `(event, ...args)`.

`emit` returns how many listeners it called in total. That is more useful than
the boolean the real `EventEmitter` returns and it makes the gate precise.

`once` needs the same wrapper trick as before: the thing registered is not the
function the caller gave you, so `off` has to be able to find its way back.

## Hint 3

```ts
emit(event, ...args) {
  let called = 0;
  for (const listener of [...(listeners.get(event) ?? [])]) {
    listener(...args);
    called += 1;
  }
  for (const listener of [...(listeners.get("*") ?? [])]) {
    listener(/* what comes first? */);
    called += 1;
  }
  return called;
}
```

Two decisions left: the wildcard argument list, and whether a `"*"` listener
should also fire when someone emits the literal event `"*"` (the gate does not
test it - decide on purpose and be able to defend it). Worth saying in the
room: wildcards make a bus convenient and make it hard to know who is
listening, which is why most production buses log or namespace them.

references.solution.ts:
// i2_interview_drills / review1 - reference solution (author only, used by `dojo verify`).

export type BusListener = (...args: any[]) => void;

export interface Bus {
  on(event: string, listener: BusListener): void;
  once(event: string, listener: BusListener): void;
  off(event: string, listener: BusListener): void;
  emit(event: string, ...args: unknown[]): number;
}

export function createBus(): Bus {
  const listeners = new Map<string, BusListener[]>();
  const wrappers = new Map<BusListener, BusListener>();

  const bus: Bus = {
    on(event, listener) {
      const existing = listeners.get(event);
      if (existing) existing.push(listener);
      else listeners.set(event, [listener]);
    },

    once(event, listener) {
      const wrapper: BusListener = (...args) => {
        bus.off(event, wrapper);
        listener(...args);
      };
      wrappers.set(listener, wrapper);
      bus.on(event, wrapper);
    },

    off(event, listener) {
      const target = wrappers.get(listener) ?? listener;
      const existing = listeners.get(event);
      if (!existing) return;
      const index = existing.indexOf(target);
      if (index !== -1) existing.splice(index, 1);
      if (existing.length === 0) listeners.delete(event);
      wrappers.delete(listener);
    },

    emit(event, ...args) {
      let called = 0;
      // Copy before walking: a listener may add or remove listeners.
      for (const listener of [...(listeners.get(event) ?? [])]) {
        listener(...args);
        called += 1;
      }
      // Wildcard listeners are told which event it was, first.
      for (const listener of [...(listeners.get("*") ?? [])]) {
        listener(event, ...args);
        called += 1;
      }
      return called;
    },
  };

  return bus;
}

lessons.briefing:
# i3 — Rapid fire

Short questions on the four things that come up in nearly every Node
interview, in shapes you have not seen before. Nothing here should take more
than ten minutes. That is the point: these are the answers that have to be
*automatic*, because in the room you will be producing them while also
listening, explaining and being watched.

This lesson exists mainly to feed the review ladder. Every exercise here is
about a ⭐⭐⭐ concept from `i1_interview_concepts`, and `dojo review` will bring
the review variant back at 3, 7, 21 and 60 days — so the material that matters
most is the material you meet most often. Redo the whole lesson cold whenever
it surfaces; it takes half an hour and it is the cheapest interview prep there
is.

The four:

| exercise | concept | first taught |
|---|---|---|
| ex1 | event loop and queue order | 02_event_loop |
| ex2 | backpressure | 06_buffers_streams |
| ex3 | timeouts, and cleaning up after them | 03_async_patterns |
| ex4 | operational vs programmer errors, as HTTP | 04, 10 |

## Exercise 1 — five labels, thirty seconds

Edit `ex1/solution.ts`. `ex1/snippet.ts`, run from inside a timer callback:

```ts
export function run(log: (label: string) => void): void {
  const start = async (): Promise<void> => {
    log("A");
    await Promise.resolve();
    log("B");
  };

  void start();
  process.nextTick(() => log("C"));
  queueMicrotask(() => log("D"));
  log("E");
}
```

Return the five labels in order. The interesting decision is between the two
microtasks, and it is decided by when each was *queued* rather than where it
sits in the source.

```
uv run dojo test node i3_interview_rapidfire ex1
```

## Exercise 2 — the one boolean everybody ignores

Edit `ex2/solution.ts`. Implement `pumpAll(source, dest)`: write every chunk
from an async iterable into a writable stream, honouring backpressure, and
return how many chunks you wrote. Do not end the stream — the caller owns it.

The gate gives you a sink with a 16-byte `highWaterMark` and a slow write, and
records how much was queued inside it at the worst moment. Write without
checking and that number is about 150; write properly and it stays at 16.

```
uv run dojo test node i3_interview_rapidfire ex2
```

## Exercise 3 — a deadline with a tidy exit

Edit `ex3/solution.ts`. Implement `withDeadline(promise, ms, message)`:

- the work settles first → its value or its error, unchanged;
- the deadline passes first → reject with an `Error` carrying that `message`
  **and** `code: "ETIMEDOUT"`;
- either way, no timer is left pending.

The gate uses fake timers, so five seconds pass instantly, and it checks
`vi.getTimerCount()` after the fast case.

```
uv run dojo test node i3_interview_rapidfire ex3
```

## Exercise 4 — from a thrown thing to an honest reply

Edit `ex4/solution.ts`. Implement `toResponse(error)` returning
`{ status, body: { error, message } }`:

1. an `Error` with a numeric `status` **and** a string `code` → use its own
   status, code and message (this is your own `AppError`);
2. an `Error` with a Node system code (`ECONNREFUSED`, `ENOENT` — capitals,
   starting with `E`) → **502**, `upstream_error`,
   `"upstream request failed"`;
3. anything else, including things that are not `Error`s → **500**,
   `internal_error`, `"internal server error"`.

Rule 2 is the one with teeth: the real message is
`connect ECONNREFUSED 10.0.0.7:5432`, and sending that to a client hands out
your internal topology.

```
uv run dojo test node i3_interview_rapidfire ex4
```

## Review

`review1/solution.ts` comes back on the spaced-review schedule.
`review1/snippet.ts`, again from inside a timer callback:

```ts
export function run(log: (label: string) => void): void {
  log("start");

  Promise.resolve()
    .then(() => {
      log("p1");
    })
    .then(() => {
      log("p2");
    });

  process.nextTick(() => log("tick"));

  setTimeout(() => {
    log("timer");
    process.nextTick(() => log("tick-in-timer"));
  }, 0);

  log("end");
}
```

Seven labels. Two things are being checked: that a chained `.then` is queued
when its predecessor settles, and that the checkpoint runs after *each*
callback — including that timer.

```
uv run dojo test node i3_interview_rapidfire review1
```

